async function savePendingGuestSmartReview(attempts=[]) {
  const cleanAttempts=attempts
    .filter(attempt=>attempt?.qid)
    .map(attempt=>({
      ...attempt,
      guestBridge:true,
      createdAt:attempt.createdAt||new Date().toISOString(),
    }));
  if(!cleanAttempts.length)return;
  await storageSet(GUEST_SMART_REVIEW_BRIDGE_KEY,JSON.stringify({
    createdAt:Date.now(),
    attempts:cleanAttempts,
  }));
}

async function takePendingGuestSmartReview() {
  try{
    const stored=await storageGet(GUEST_SMART_REVIEW_BRIDGE_KEY);
    if(!stored?.value)return [];
    await storageDelete(GUEST_SMART_REVIEW_BRIDGE_KEY);
    const parsed=JSON.parse(stored.value);
    if(Date.now()-Number(parsed?.createdAt||0)>GUEST_SMART_REVIEW_BRIDGE_TTL_MS)return [];
    return Array.isArray(parsed?.attempts)?parsed.attempts.filter(attempt=>attempt?.qid):[];
  }catch{
    await storageDelete(GUEST_SMART_REVIEW_BRIDGE_KEY).catch(()=>{});
    return [];
  }
}

const emptyCipherWallet = () => ({
  balance:0,
  lifetimeEarned:0,
  examPasses:0,
  unlockedPbqIds:[],
  unlocks:[],
  transactions:[],
  checkInStreak:0,
  challengeStreak:0,
  lastCheckInDate:"",
  lastChallengeDate:"",
  status:"ready",
  error:"",
});

const emptyAccountDeletionState = () => ({
  stage:"idle",
  token:"",
  busy:false,
  error:"",
  email:"",
  retryAt:0,
  allowRestart:false,
});

function readAccountDeletionState() {
  const state=emptyAccountDeletionState();
  try{
    const params=new URLSearchParams(window.location.search);
    const urlToken=String(params.get("delete_account_token")||"").trim();
    const storedToken=String(window.sessionStorage?.getItem(ACCOUNT_DELETION_TOKEN_KEY)||"").trim();
    const token=urlToken||storedToken;
    if(urlToken){
      params.delete("delete_account_token");
      const clean=`${window.location.origin}${window.location.pathname}${params.toString()?`?${params.toString()}`:""}${window.location.hash||""}`;
      window.history.replaceState({},"",clean);
    }
    if(token){
      window.sessionStorage?.setItem(ACCOUNT_DELETION_TOKEN_KEY,token);
      return {...state,stage:"confirm",token};
    }
  }catch{}
  return state;
}

function normalizeCipherWallet(wallet={}) {
  return {
    ...emptyCipherWallet(),
    ...wallet,
    balance:Math.max(0,Number(wallet.balance)||0),
    lifetimeEarned:Math.max(0,Number(wallet.lifetimeEarned)||0),
    examPasses:Math.max(0,Number(wallet.examPasses)||0),
    unlockedPbqIds:Array.isArray(wallet.unlockedPbqIds)?wallet.unlockedPbqIds:[],
    unlocks:Array.isArray(wallet.unlocks)?wallet.unlocks:[],
    transactions:Array.isArray(wallet.transactions)?wallet.transactions:[],
  };
}

