const GLOSSARY_TERMS = {
  ...ACRONYM_GLOSSARY_TERMS,
  "SQL injection": "A vulnerability where attacker-controlled input changes a SQL query.",
  "Zero Trust": "A security model that continuously verifies users, devices, and access instead of trusting by location.",
  "Tokenization": "Replacing sensitive data with a non-sensitive token while storing the real value separately.",
  "Hashing": "A one-way transformation used to verify integrity or store passwords safely when done with salts and slow algorithms.",
  "Encryption": "A reversible protection method that converts readable data into ciphertext using a key.",
};

const ACRONYM_TERMS_SORTED = Object.keys(ACRONYM_GLOSSARY_TERMS).sort((a,b)=>b.length-a.length);

function extractAcronymsFromText(...values) {
  const found=new Set();
  const text=values.flat(Infinity).filter(value=>value!==null&&value!==undefined).map(value=>String(value)).join(" ");
  if(!text.trim())return [];
  ACRONYM_TERMS_SORTED.forEach(term=>{
    const escaped=term.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");
    const pattern=new RegExp(`(^|[^A-Za-z0-9])${escaped}(?=$|[^A-Za-z0-9])`,"i");
    if(pattern.test(text)) found.add(term);
  });
  return [...found].sort((a,b)=>a.localeCompare(b,undefined,{sensitivity:"base"}));
}

function getMcqAcronyms(question) {
  return extractAcronymsFromText(
    question?.q,
    question?.opts || [],
    question?.exp,
    Object.values(question?.wrongFeedback || {})
  );
}

function getPbqAcronyms(question) {
  return extractAcronymsFromText(
    question?.title,
    question?.cat,
    question?.scenario,
    question?.question,
    question?.choices || [],
    question?.explanation,
    Object.values(question?.wrongFeedback || {}),
    question?.steps || [],
    question?.codeLanguage,
    question?.codeBlock,
    question?.logData,
    question?.diagram,
    question?.currentConfig
  );
}

function stripPbqHintsForExam(value) {
  if(Array.isArray(value)) return value.map(stripPbqHintsForExam);
  if(value&&typeof value==="object") {
    return Object.fromEntries(
      Object.entries(value)
        .filter(([key])=>key!=="hint")
        .map(([key,nextValue])=>[key,stripPbqHintsForExam(nextValue)])
    );
  }
  return value;
}

const FILL_BLANK_SPELLING_VARIANTS = {
  "accessorise":"accessorize",
  "authorisation":"authorization",
  "authorisations":"authorizations",
  "authorise":"authorize",
  "authorised":"authorized",
  "behaviour":"behavior",
  "behaviours":"behaviors",
  "behavioural":"behavioral",
  "cancelled":"canceled",
  "catalogue":"catalog",
  "centralised":"centralized",
  "centralisation":"centralization",
  "centre":"center",
  "defence":"defense",
  "demilitarised":"demilitarized",
  "emphasise":"emphasize",
  "enrolment":"enrollment",
  "favour":"favor",
  "favourite":"favorite",
  "federated":"federated",
  "grey":"gray",
  "honour":"honor",
  "labelled":"labeled",
  "licence":"license",
  "modelling":"modeling",
  "organisation":"organization",
  "organisations":"organizations",
  "organisational":"organizational",
  "organise":"organize",
  "organised":"organized",
  "prioritise":"prioritize",
  "realise":"realize",
  "recognise":"recognize",
  "recognised":"recognized",
  "specialised":"specialized",
  "standardise":"standardize",
  "unauthorised":"unauthorized",
  "utilise":"utilize",
  "visualise":"visualize"
};

function normalizeFillBlankAnswer(value) {
  return String(value||"")
    .trim()
    .toLowerCase()
    .replace(/[’']/g,"")
    .replace(/[-_/]+/g," ")
    .replace(/[^\p{L}\p{N}\s]/gu,"")
    .replace(/\s+/g," ")
    .split(" ")
    .map(word=>FILL_BLANK_SPELLING_VARIANTS[word]||word)
    .join(" ");
}

function isFillBlankAnswerCorrect(input, blank) {
  const expected=[blank?.answer, ...(blank?.acceptedAnswers||[]), ...(blank?.aliases||[])];
  const normalizedInput=normalizeFillBlankAnswer(input);
  return expected.some(answer=>normalizeFillBlankAnswer(answer)===normalizedInput);
}

function parseAcceptedAnswers(value) {
  if(Array.isArray(value)) return value.map(answer=>String(answer||"").trim()).filter(Boolean);
  return String(value||"")
    .split(/[\n,]+/)
    .map(answer=>answer.trim())
    .filter(Boolean);
}

