const LOW_QUALITY_PBQ_IDS = new Set([
  // Hidden because the prompt or explanation is too long for a smooth PBQ practice flow.
  "p053","p059","p063","p065","p071","p072","p076","p081","p087","p088","p090","p091",
  "p092","p093","p097","p098","p100"
]);

const SY0701_SELECTION_DISTRACTORS = Object.freeze({
  "1":["Hashing","Tokenization","Data masking","Digital signature","Key escrow","Key stretching","Certificate revocation"],
  "2":["Phishing","Vishing","Smishing","Whaling","Pretexting","Tailgating","Watering-hole attack"],
  "3":["Network segmentation","NAC","Firewall","IDS","IPS","VPN","Zero Trust"],
  "4":["Preparation","Detection and analysis","Containment","Eradication","Recovery","Lessons learned","Root cause analysis"],
  "5":["Risk acceptance","Risk avoidance","Risk transfer","Risk mitigation","SLE","ALE","ARO","Exposure factor"],
});

function uniqueSelectionOptions(values=[]) {
  const seen=new Set();
  return values
    .map(value=>String(value||"").trim())
    .filter(value=>{
      if(!value)return false;
      const key=normalizeFillBlankAnswer(value);
      if(!key||seen.has(key))return false;
      seen.add(key);
      return true;
    });
}

function stableSelectionOptionOrder(options,seed="secureplus") {
  const score=value=>{
    const input=`${seed}:${value}`;
    let hash=2166136261;
    for(let index=0;index<input.length;index+=1) hash=Math.imul(hash^input.charCodeAt(index),16777619);
    return hash>>>0;
  };
  return [...options].sort((left,right)=>score(left)-score(right)||left.localeCompare(right));
}

function hintSelectionOptions(hint) {
  const value=String(hint||"").trim();
  if(!value || !/[,;|]/.test(value))return [];
  return value
    .split(/[,;|]/)
    .map(option=>option.trim())
    .filter(option=>option.length>=2&&option.length<=120);
}

function buildSelectionOptionBank(question,blanks,seedOptions=[],minimumDistractors=0) {
  const answers=uniqueSelectionOptions(blanks.map(blank=>blank.answer));
  const hinted=blanks.flatMap(blank=>hintSelectionOptions(blank.hint));
  const options=uniqueSelectionOptions([...answers,...seedOptions,...hinted]);
  const answerKeys=new Set(answers.map(normalizeFillBlankAnswer));
  const distractorCount=()=>options.filter(option=>!answerKeys.has(normalizeFillBlankAnswer(option))).length;
  const fallback=SY0701_SELECTION_DISTRACTORS[String(question.ch||question.domain||"1")]||[];
  for(const option of fallback) {
    if(options.length>=Math.max(4,answers.length+minimumDistractors)&&distractorCount()>=minimumDistractors)break;
    if(!options.some(existing=>normalizeFillBlankAnswer(existing)===normalizeFillBlankAnswer(option))) options.push(option);
  }
  return options;
}

const SY0701_DOMAIN_LABELS=Object.freeze({
  "1":"General Security Concepts",
  "2":"Threats, Vulnerabilities, and Mitigations",
  "3":"Security Architecture",
  "4":"Security Operations",
  "5":"Security Program Management and Oversight",
});

const PBQ_OBJECTIVE_FALLBACKS=Object.freeze({
  "1":"1.2",
  "2":"2.4",
  "3":"3.2",
  "4":"4.9",
  "5":"5.2",
});

function compactFeedbackText(value,maxLength=520) {
  const clean=String(value||"").replace(/\s+/g," ").trim();
  if(clean.length<=maxLength)return clean;
  return `${clean.slice(0,maxLength-1).replace(/\s+\S*$/,"")}…`;
}

function ensureFeedbackLead(text,isCorrectAnswer) {
  const clean=String(text||"").trim();
  if(/^correct\./i.test(clean) || /^incorrect\./i.test(clean)) return clean;
  return `${isCorrectAnswer?"Correct.":"Incorrect."} ${clean}`.trim();
}

function inferPbqObjective(question) {
  const ch=String(question?.ch||question?.domain||"1");
  if(question?.objective && /^\d+\.\d+$/.test(String(question.objective)) && String(question.objective).startsWith(`${ch}.`)) return String(question.objective);
  const text=[
    question?.title,
    question?.cat,
    question?.type,
    question?.scenario,
    question?.question,
    question?.explanation,
  ].join(" ").toLowerCase();
  if(ch==="1") {
    if(/pki|certificate|crypt|hash|signature|tls|key|kerberos|symmetric|asymmetric/.test(text)) return "1.4";
    if(/control|zero trust|authentication|authorization|password|mfa|privilege|identity/.test(text)) return "1.2";
    return "1.1";
  }
  if(ch==="2") {
    if(/actor|motivation|phish|social engineering|pretext|whaling|smishing|vishing/.test(text)) return "2.1";
    if(/attack vector|attack surface|wireless|default credential|open service|email|removable/.test(text)) return "2.2";
    if(/vulnerab|injection|xss|sql|patch|cve|misconfig|dependency|supply chain/.test(text)) return "2.3";
    return "2.4";
  }
  if(ch==="3") {
    if(/cloud|shared responsibility|iaas|paas|saas|serverless|container|iot|ics|scada|architecture/.test(text)) return "3.1";
    if(/data|classification|dlp|mask|token|encrypt|retention|privacy|state/.test(text)) return "3.3";
    if(/resilience|recovery|backup|rto|rpo|dr|continuity|failover|replication/.test(text)) return "3.4";
    return "3.2";
  }
  if(ch==="4") {
    if(/automation|orchestration|script|playbook|ticket|baseline/.test(text)) return "4.7";
    if(/incident response phase|containment|eradication|recovery|lessons learned|root cause/.test(text)) return "4.8";
    if(/log|process|packet|capture|netflow|firewall|endpoint|investigat|forensic|chain of custody|siem|ids|ips|ioc|alert/.test(text)) return "4.9";
    return "4.9";
  }
  if(ch==="5") {
    if(/policy|standard|procedure|governance|change management|legal|regulatory|privacy/.test(text)) return "5.1";
    if(/third party|vendor|agreement|sla|mou|moa|risk|bia|sle|ale|aro|impact|likelihood/.test(text)) return "5.2";
    return "5.2";
  }
  return PBQ_OBJECTIVE_FALLBACKS[ch]||"1.2";
}

function pbqEvidenceNudge(question) {
  const type=String(question?.type||"").toUpperCase();
  if(type==="LOG ANALYSIS") return "Use the event pattern, source, destination, and timing instead of judging by one word in the log.";
  if(type==="TERMINAL SIM") return "Use the command output and the scenario goal together before choosing the answer.";
  if(type==="CONFIG/ACL") return "Check the required source, destination, service, and rule order before changing a control.";
  if(type==="HOTSPOT") return "Match the answer to the affected system or location shown in the scenario evidence.";
  if(type==="ORDERING") return "The safest order is the one that protects evidence, limits damage, and then restores service.";
  return "Focus on the stated business requirement and the strongest Security+ control for that situation.";
}

function buildPbqOptionFeedback(question,index,choice,correctIndex) {
  const choices=question.choices||question.options||[];
  const correctChoice=choices[correctIndex]||"the correct option";
  const correctLetter=String.fromCharCode(65+correctIndex);
  const explanation=compactFeedbackText(question.explanation,360);
  if(index===correctIndex) {
    return compactFeedbackText(`Correct. This is the strongest answer because it matches the scenario evidence and the task requirement. ${explanation || pbqEvidenceNudge(question)}`,520);
  }
  return compactFeedbackText(`Incorrect. This option may sound related, but it does not best satisfy the scenario. The stronger answer is ${correctLetter}: ${correctChoice}. ${pbqEvidenceNudge(question)}`,520);
}

function ensurePbqBlankExplanations(question) {
  if(question.type!==SELECT_FILL_PBQ_TYPE || !Array.isArray(question.blanks)) return question;
  const blanks=question.blanks.map((blank,index)=>{
    const answer=String(blank.answer||"").trim();
    const existing=String(blank.explanation||blank.solution||"").trim();
    const explanation=existing.length>=25
      ? existing
      : `The best selection for blank ${index+1} is "${answer}" because it matches the scenario clue and the SY0-701 concept being tested.`;
    return {...blank,explanation};
  });
  return {...question,blanks};
}

function ensurePbqChoiceFeedback(question) {
  const choices=Array.isArray(question.choices)?question.choices:Array.isArray(question.options)?question.options:null;
  if(!choices?.length || !Number.isInteger(question.correct)) return question;
  const correctIndex=question.correct;
  const optionFeedback={...(question.optionFeedback||question.choiceFeedback||{})};
  const wrongFeedback={...(question.wrongFeedback||{})};
  choices.forEach((choice,index)=>{
    const existing=optionFeedback[index] ?? optionFeedback[String(index)] ?? (index!==correctIndex ? wrongFeedback[index] ?? wrongFeedback[String(index)] : "");
    const fallback=buildPbqOptionFeedback(question,index,choice,correctIndex);
    const feedback=compactFeedbackText(String(existing||"").trim().length>=25 ? existing : fallback);
    optionFeedback[index]=ensureFeedbackLead(feedback,index===correctIndex);
    if(index!==correctIndex) wrongFeedback[index]=optionFeedback[index].replace(/^Incorrect\.\s*/i,"");
  });
  return {...question,choices,options:choices,optionFeedback,wrongFeedback};
}

const GENERIC_PBQ_TITLE_RE=/^(identify|match|complete|order|name|classify|map|choose|apply|configure|evaluate|sequence|place)\b/i;

function pbqContentContext(question) {
  const domain=String(question?.ch||question?.domain||"");
  const cat=String(question?.cat||"Security+").toLowerCase();
  if(domain==="1") return `You are helping a junior analyst make a safe decision about ${cat}.`;
  if(domain==="2") return `During threat triage, you need to connect the evidence to the most likely ${cat} issue.`;
  if(domain==="3") return `You are reviewing a proposed architecture change and must choose the safest ${cat} decision.`;
  if(domain==="4") return `You are the on-call security analyst reviewing operational evidence from a real incident queue.`;
  if(domain==="5") return `You are supporting a governance and risk review where the answer must be practical and defensible.`;
  return "You are working through a Security+ performance-based task that requires applying the evidence, not memorising a definition.";
}

function improvePBQTitle(question) {
  const title=String(question?.title||"Security+ PBQ").trim();
  if(!GENERIC_PBQ_TITLE_RE.test(title)) return title;
  const cat=String(question?.cat||"Security+").trim();
  const type=String(question?.type||"").toUpperCase();
  const focus=title
    .replace(GENERIC_PBQ_TITLE_RE,"")
    .replace(/^(the|a|an|to|each|correct)\s+/i,"")
    .replace(/\s+/g," ")
    .trim();
  const suffix=focus ? ` — ${focus.charAt(0).toLowerCase()}${focus.slice(1)}` : "";
  if(type==="LOG ANALYSIS") return `${cat} evidence triage`;
  if(type==="CONFIG/ACL") return `${cat} safe configuration review`;
  if(type==="TERMINAL SIM") return `${cat} command-output investigation`;
  if(type==="HOTSPOT") return `${cat} priority finding`;
  if(type==="ORDERING") return `${cat} action sequence${suffix}`;
  if(type===SELECT_FILL_PBQ_TYPE || type==="FILL BLANK" || type==="DRAG & DROP") return `${cat} scenario application${suffix}`;
  return `${cat} evidence-based decision${suffix}`;
}

function improvePBQScenario(question) {
  const scenario=String(question?.scenario||"").trim();
  const type=String(question?.type||"").toUpperCase();
  if(scenario.length>=110) return scenario;
  const context=pbqContentContext(question);
  if(type==="LOG ANALYSIS") {
    return `${context} Review the log evidence below, separate strong indicators from distractors, and choose the conclusion that is best supported by the data.`;
  }
  if(type==="CONFIG/ACL") {
    return `${context} Review the current configuration and choose the change that satisfies the requirement with least privilege and the least unintended access.`;
  }
  if(type==="TERMINAL SIM") {
    return `${context} Run or review the command output, then use the result to make the best Security+ decision.`;
  }
  if(type==="ORDERING") {
    return `${context} Put the actions in the order that a careful security team should follow during a realistic work scenario.`;
  }
  if(type===SELECT_FILL_PBQ_TYPE || type==="FILL BLANK" || type==="DRAG & DROP") {
    return `${context} Complete each item by matching the scenario clue to the Security+ term or control that fits best.`;
  }
  if(type==="HOTSPOT") {
    return `${context} Review the diagram or evidence and select the finding that matters most for the stated security objective.`;
  }
  return `${context} Use the scenario details to choose the best answer. ${scenario}`.trim();
}

function improvePBQQuestion(question) {
  const prompt=String(question?.question||"").trim();
  if(prompt.length>=70 && /best|most|first|correct|which|what|why|order|match|select/i.test(prompt)) return prompt;
  const type=String(question?.type||"").toUpperCase();
  if(type==="LOG ANALYSIS") return `${prompt ? `${prompt} ` : ""}Which conclusion is best supported by the logs, and which distractors should be ruled out?`.trim();
  if(type==="CONFIG/ACL") return `${prompt ? `${prompt} ` : ""}Which option most safely meets the requirement while avoiding unnecessary exposure?`.trim();
  if(type==="TERMINAL SIM") return `${prompt ? `${prompt} ` : ""}Based on the command output, which answer is the strongest Security+ decision?`.trim();
  if(type==="HOTSPOT") return `${prompt ? `${prompt} ` : ""}Which selection best fits the evidence and the security priority?`.trim();
  if(type==="SCENARIO") return `${prompt ? `${prompt} ` : ""}Choose the best answer using the scenario details, not keyword matching.`;
  return prompt || "Complete the activity using the scenario evidence and choose the best Security+ answer.";
}

function improvePBQExplanation(question) {
  const explanation=String(question?.explanation||"").trim();
  const type=String(question?.type||"").toUpperCase();
  const examSkill=type==="LOG ANALYSIS"
    ? "Exam skill: connect multiple log fields before deciding."
    : type==="CONFIG/ACL"
      ? "Exam skill: apply least privilege while preserving required business access."
      : type==="ORDERING"
        ? "Exam skill: sequence actions so containment, validation, and recovery happen in a safe order."
        : type===SELECT_FILL_PBQ_TYPE || type==="FILL BLANK" || type==="DRAG & DROP"
          ? "Exam skill: match the term to the clue, then explain why nearby distractors do not fit."
          : "Exam skill: choose the control that best satisfies the scenario, not merely a familiar keyword.";
  if(explanation.includes("Exam skill:")) return compactFeedbackText(explanation,620);
  return `${compactFeedbackText(explanation,520)} ${examSkill}`;
}

function applyPBQContentEditorialPass(question) {
  return {
    ...question,
    title:improvePBQTitle(question),
    scenario:improvePBQScenario(question),
    question:improvePBQQuestion(question),
    explanation:improvePBQExplanation(question),
  };
}

function normalizeSelectionPBQ(question) {
  const sourceType=String(question?.type||"").trim().toUpperCase();
  if(!["DRAG & DROP","FILL BLANK",SELECT_FILL_PBQ_TYPE].includes(sourceType))return question;
  const legacyType=String(question?.legacySelectionType||sourceType).trim().toUpperCase().replace(/[_-]+/g," ");
  const legacyIsDrag=legacyType.includes("DRAG") || (sourceType===SELECT_FILL_PBQ_TYPE&&question?.items?.length&&question?.correctMapping&&!question?.blanks?.length);
  const legacyIsFill=legacyType==="FILL BLANK" || (sourceType===SELECT_FILL_PBQ_TYPE&&question?.blanks?.length&&!question?.selectionOptions?.length);

  if(legacyIsDrag) {
    const targets=(question.targets||[]).filter(target=>target?.droppable!==false);
    const targetById=new Map(targets.map((target,index)=>[target.id,target.label||`Answer area ${index+1}`]));
    const blanks=(question.items||[]).map((item,index)=>({
      id:item.id||`b${index}`,
      sentence:String(item.label||`Prompt ${index+1}`).includes("___")?String(item.label):`${item.label||`Prompt ${index+1}`} → ___`,
      answer:targetById.get(question.correctMapping?.[item.id])||"",
      acceptedAnswers:[],
      hint:"",
      explanation:item.explanation||item.solution||`Match this item to "${targetById.get(question.correctMapping?.[item.id])||"the correct target"}" because that pairing best satisfies the scenario.`,
    })).filter(blank=>blank.sentence&&blank.answer);
    const selectionOptions=stableSelectionOptionOrder(buildSelectionOptionBank(question,blanks,targets.map((target,index)=>target.label||`Answer area ${index+1}`),0),question.id);
    return {...question,type:SELECT_FILL_PBQ_TYPE,emoji:"🧩",legacySelectionType:"DRAG & DROP",blanks,selectionOptions};
  }

  const blanks=(question.blanks||[]).map((blank,index)=>({
    ...blank,
    id:blank.id||`b${index}`,
    sentence:String(blank.sentence||""),
    answer:String(blank.answer||"").trim(),
    acceptedAnswers:Array.isArray(blank.acceptedAnswers)?blank.acceptedAnswers:Array.isArray(blank.aliases)?blank.aliases:[],
  })).filter(blank=>blank.sentence&&blank.answer);
  const seedOptions=question.selectionOptions||question.optionBank||question.distractors||[];
  const minimumDistractors=legacyIsFill?2:0;
  const selectionOptions=legacyIsFill
    ? stableSelectionOptionOrder(buildSelectionOptionBank(question,blanks,seedOptions,minimumDistractors),question.id)
    : buildSelectionOptionBank(question,blanks,seedOptions,minimumDistractors);
  return {...question,type:SELECT_FILL_PBQ_TYPE,emoji:"🧩",legacySelectionType:legacyIsFill?"FILL BLANK":question.legacySelectionType||sourceType,blanks,selectionOptions};
}

function enhancePBQQuestion(question) {
  const normalized=applyPBQContentEditorialPass(ensurePbqBlankExplanations(normalizeSelectionPBQ(question)));
  const ch=String(normalized.ch||normalized.domain||"1");
  return ensurePbqChoiceFeedback({
    ...normalized,
    ch,
    objective:inferPbqObjective(normalized),
    syllabusDomain:normalized.syllabusDomain || `Domain ${ch}: ${SY0701_DOMAIN_LABELS[ch]||"Security+"}`,
  });
}

const BASE_PBQ_BANK = [...PBQ_BANK_BASE, ...IMPORTED_PBQ_BANK]
  .filter(q=>!LOW_QUALITY_PBQ_IDS.has(q.id))
  .map(enhancePBQQuestion);
let PBQ_BANK = BASE_PBQ_BANK;

const REMOTE_PBQ_TYPE_ALIASES = {
  config_acl:"CONFIG/ACL",
  config:"CONFIG/ACL",
  terminal_sim:"TERMINAL SIM",
  terminal:"TERMINAL SIM",
  log_analysis:"LOG ANALYSIS",
  hotspot:"HOTSPOT",
  scenario:"SCENARIO",
  drag_drop:SELECT_FILL_PBQ_TYPE,
  drag_and_drop:SELECT_FILL_PBQ_TYPE,
  ordering:"ORDERING",
  fill_blank:SELECT_FILL_PBQ_TYPE,
  select_fill:SELECT_FILL_PBQ_TYPE,
  select_and_fill:SELECT_FILL_PBQ_TYPE,
};

function normalizeRemotePbqType(type) {
  const value=String(type||"SCENARIO").trim();
  const key=value.toLowerCase().replace(/[\s/&-]+/g,"_");
  return REMOTE_PBQ_TYPE_ALIASES[key] || value.toUpperCase();
}

function normalizeRemotePBQRow(row) {
  const payload=row?.payload || {};
  const appQuestion=payload.appQuestion || {};
  const evidence=payload.evidence || {};
  const interactiveData=payload.interactiveData || {};
  const correctAnswer=payload.correctAnswer || {};
  const wrongFeedback=payload.wrongFeedback ?? appQuestion.wrongFeedback ?? {};
  const optionFeedback=payload.optionFeedback ?? appQuestion.optionFeedback ?? payload.choiceFeedback ?? appQuestion.choiceFeedback ?? {};
  const choices=interactiveData.choices || appQuestion.choices || appQuestion.options || payload.choices;
  const type=normalizeRemotePbqType(row?.type || appQuestion.type || payload.type);
  const domain=Number(row?.domain || appQuestion.ch || appQuestion.domain || payload.domain || 1);
  const normalized={
    ...appQuestion,
    id:String(row?.id || appQuestion.id || ""),
    title:row?.title || appQuestion.title || payload.title || "Untitled PBQ",
    type,
    legacySelectionType:appQuestion.legacySelectionType || row?.type || appQuestion.type || payload.type,
    ch:String(Number.isFinite(domain)&&domain>0?domain:1),
    cat:appQuestion.cat || payload.cat || payload.domainName || `Domain ${Number.isFinite(domain)?domain:1}`,
    difficulty:appQuestion.difficulty || payload.difficulty || "medium",
    beyondTextbook:Boolean(appQuestion.beyondTextbook || payload.beyondTextbook),
    is_pro:row?.is_pro !== false,
    payload,
    scenario:payload.scenario ?? appQuestion.scenario ?? "",
    question:payload.question ?? appQuestion.question ?? payload.prompt ?? "",
    explanation:payload.explanation ?? correctAnswer.explanation ?? appQuestion.explanation ?? (typeof wrongFeedback==="string" ? wrongFeedback : ""),
    logData:evidence.logData ?? appQuestion.logData ?? "",
    currentConfig:evidence.currentConfig ?? appQuestion.currentConfig ?? "",
    codeBlock:evidence.codeBlock ?? appQuestion.codeBlock ?? "",
    codeLanguage:evidence.codeLanguage ?? appQuestion.codeLanguage ?? "",
    diagram:evidence.diagram ?? appQuestion.diagram ?? "",
    hint:evidence.hint ?? appQuestion.hint ?? "",
    answer:correctAnswer.answer ?? appQuestion.answer ?? "",
    choices:Array.isArray(choices) ? choices : undefined,
    options:Array.isArray(choices) ? choices : undefined,
    correct:Number.isInteger(correctAnswer.correct) ? correctAnswer.correct : Number.isInteger(appQuestion.correct) ? appQuestion.correct : 0,
    wrongFeedback:typeof wrongFeedback==="string" ? {} : wrongFeedback,
    optionFeedback:typeof optionFeedback==="string" ? {} : optionFeedback,
    items:interactiveData.items || appQuestion.items,
    targets:interactiveData.targets || appQuestion.targets,
    targetLayout:interactiveData.targetLayout || appQuestion.targetLayout,
    correctMapping:correctAnswer.correctMapping || appQuestion.correctMapping,
    correctOrder:correctAnswer.correctOrder || appQuestion.correctOrder,
    blanks:interactiveData.blanks || appQuestion.blanks,
    selectionOptions:interactiveData.selectionOptions || appQuestion.selectionOptions || payload.selectionOptions,
    acronyms:appQuestion.acronyms || payload.acronyms || [],
  };
  return enhancePBQQuestion(normalized);
}

function mergeRemotePBQBanks(localQuestions=[],remoteQuestions=[]) {
  const validRemoteQuestions=remoteQuestions.filter(question=>question?.id);
  const remoteById=new Map(validRemoteQuestions.map(question=>[question.id,question]));
  const localIds=new Set(localQuestions.map(question=>question.id));
  return [
    ...localQuestions.map(question=>remoteById.get(question.id)||question),
    ...validRemoteQuestions.filter(question=>!localIds.has(question.id)),
  ].map(enhancePBQQuestion);
}

function buildSupabasePBQMutation(question, sortOrder) {
  const domain=Number.parseInt(question.ch || question.domain || "1",10) || 1;
  const evidence={
    logData:question.logData || "",
    currentConfig:question.currentConfig || "",
    codeBlock:question.codeBlock || "",
    codeLanguage:question.codeLanguage || "",
    diagram:question.diagram || "",
    hint:question.hint || "",
  };
  Object.keys(evidence).forEach(key=>{if(!evidence[key]) delete evidence[key];});
  const interactiveData={
    choices:question.choices || question.options || [],
    items:question.items || [],
    targets:question.targets || [],
    targetLayout:question.targetLayout || null,
    blanks:question.blanks || [],
    selectionOptions:question.selectionOptions || [],
  };
  Object.keys(interactiveData).forEach(key=>{
    if(interactiveData[key]===null || (Array.isArray(interactiveData[key])&&!interactiveData[key].length)) delete interactiveData[key];
  });
  const correctAnswer={
    correct:question.correct,
    answer:question.answer || "",
    correctMapping:question.correctMapping || null,
    correctOrder:question.correctOrder || null,
  };
  Object.keys(correctAnswer).forEach(key=>{
    if(correctAnswer[key]===null || correctAnswer[key]==="" || correctAnswer[key]===undefined) delete correctAnswer[key];
  });
  const payload=JSON.parse(JSON.stringify({
    scenario:question.scenario || "",
    question:question.question || "",
    explanation:question.explanation || "",
    evidence,
    interactiveData,
    correctAnswer,
    wrongFeedback:question.wrongFeedback || {},
    optionFeedback:question.optionFeedback || {},
    objective:question.objective || inferPbqObjective(question),
    syllabusDomain:question.syllabusDomain || `Domain ${String(question.ch || domain)}: ${SY0701_DOMAIN_LABELS[String(question.ch || domain)]||"Security+"}`,
    difficulty:question.difficulty || "medium",
    cat:question.cat || "",
    ch:String(question.ch || domain),
    beyondTextbook:Boolean(question.beyondTextbook),
    acronyms:question.acronyms || [],
    sortOrder,
    appQuestion:question,
  }));
  return {
    id:question.id,
    title:question.title,
    type:question.type,
    domain,
    is_pro:question.is_pro ?? question.isPro ?? !isFreePBQPreview(question),
    payload,
    updated_at:new Date().toISOString(),
  };
}

async function loadRemotePBQs() {
  if(!isSupabaseConfigured || !supabase) return {questions:[], error:null};
  const { data, error } = await supabase.from("pbqs").select("*");
  if(error) throw error;
  return {questions:(data||[]).map(normalizeRemotePBQRow).filter(question=>question.id), error:null};
}

function applyQuestionOverrides(rows=[]) {
  const mergeBank=(base,kind)=>{
    const byId=new Map(base.map((q,index)=>[q.id,{...q,_baseOrder:index+1}]));
    rows
      .filter(row=>row.status==="active"&&row.question_kind===kind)
      .forEach(row=>{
        const id=row.question_id;
        if(!id)return;
        if(row.action==="disable"){
          byId.delete(id);
          return;
        }
        const payload={...(row.payload||{})};
        if(payload.id&&payload.id!==id) payload.id=id;
        const sortOrder=Number(row.sort_order);
        const next={...(byId.get(id)||{}),...payload,id};
        if(Number.isFinite(sortOrder)&&sortOrder>0) next._adminOrder=sortOrder;
        byId.set(id, kind==="mcq" ? ensureMcqWrongFeedback(next) : next);
      });
    return [...byId.values()].sort((a,b)=>{
      const ao=Number.isFinite(Number(a._adminOrder))?Number(a._adminOrder):Number.MAX_SAFE_INTEGER;
      const bo=Number.isFinite(Number(b._adminOrder))?Number(b._adminOrder):Number.MAX_SAFE_INTEGER;
      return ao-bo || (a._baseOrder||Number.MAX_SAFE_INTEGER)-(b._baseOrder||Number.MAX_SAFE_INTEGER) || String(a.id).localeCompare(String(b.id));
    });
  };
  MCQ_BANK=mergeBank(BASE_MCQ_BANK,"mcq");
  PBQ_BANK=mergeBank(BASE_PBQ_BANK,"pbq");
}

