function AchievementCelebration({ids,t,onClose}) {
  const unlocked=ids.map(id=>ACHIEVEMENT_MAP[id]).filter(Boolean);
  if(!unlocked.length)return null;
  const starTotal=unlocked.reduce((sum,item)=>sum+Number(item.star_value||0),0);
  return (
    <div className="achievement-celebration" role="status" aria-live="polite">
      <div className="achievement-confetti" aria-hidden="true">
        {Array.from({length:18},(_,index)=>(
          <span
            key={index}
            style={{
              "--x":`${8+(index*5)%88}%`,
              "--delay":`${(index%7)*.08}s`,
              "--confetti-color":[t.amber,t.green,t.accent,"#ef4444"][index%4],
            }}
          />
        ))}
      </div>
      <div style={{position:"relative",zIndex:1,display:"flex",gap:12,alignItems:"flex-start"}}>
        <span className="achievement-mini-star" style={{flexShrink:0}}>{starTotal}</span>
        <div style={{flex:1,minWidth:0}}>
          <h3>{unlocked.length===1?"Achievement unlocked":"Achievements unlocked"}</h3>
          <p>
            {unlocked.map(item=>item.title).join(", ")} · {starTotal} star{starTotal===1?"":"s"} added.
          </p>
        </div>
        <button className="btn btn-ghost" type="button" style={{fontSize:11,minHeight:32,padding:"6px 9px"}} onClick={onClose}>Dismiss</button>
      </div>
    </div>
  );
}

function AchievementsPage({user,t,onBack}) {
  const [loading,setLoading]=useState(true);
  const [data,setData]=useState({definitions:ACHIEVEMENTS,unlocks:[],totalStars:Number(user?.totalStars||0),error:null});
  const [achievementFilter,setAchievementFilter]=useState("all");
  const [selectedAchievementId,setSelectedAchievementId]=useState(null);
  const canLoad=user?.authProvider==="supabase"&&user?.id;

  useEffect(()=>{
    let active=true;
    if(!canLoad){
      setLoading(false);
      return()=>{active=false;};
    }
    setLoading(true);
    loadSupabaseAchievements(user.id).then(result=>{
      if(active)setData(result);
    }).finally(()=>{
      if(active)setLoading(false);
    });
    return()=>{active=false;};
  },[canLoad,user?.id]);

  const unlockMap=useMemo(()=>new Map((data.unlocks||[]).map(item=>[item.achievement_id,item])),[data.unlocks]);
  const definitions=(data.definitions||ACHIEVEMENTS).map(item=>({
    ...item,
    star_value:Number(item.star_value ?? item.stars ?? 0),
  }));
  const fallbackStars=definitions.reduce((sum,item)=>unlockMap.has(item.id)?sum+item.star_value:sum,0);
  const totalStars=Math.min(ACHIEVEMENT_STAR_TOTAL,Number(data.totalStars||user?.totalStars||fallbackStars||0));
  const progress=Math.min(100,Math.round((totalStars/ACHIEVEMENT_STAR_TOTAL)*100));
  const unlockedDefinitions=definitions.filter(item=>unlockMap.has(item.id));
  const lockedDefinitions=definitions.filter(item=>!unlockMap.has(item.id));
  const selectedAchievement=definitions.find(item=>item.id===(selectedAchievementId||lockedDefinitions[0]?.id||unlockedDefinitions[0]?.id))||definitions[0];
  const selectedUnlocked=selectedAchievement?unlockMap.get(selectedAchievement.id):null;
  const visibleAchievements=achievementFilter==="unlocked"
    ? unlockedDefinitions
    : achievementFilter==="locked"
      ? lockedDefinitions
      : definitions;
  const nextAchievement=lockedDefinitions[0]||unlockedDefinitions.at(-1)||definitions[0];

  if(!canLoad) return (
    <div className="achievements-page">
      <div className="card achievements-hero" style={{display:"block"}}>
        <div className="page-title-row" style={{marginBottom:10}}>
          <NavGlyph type="achievements" active/>
          <h2>Stars need a signed-in cloud account</h2>
        </div>
        <p>
          SecurePlus awards stars from the server after checking completed practice sessions. Sign in with a Supabase-backed account so achievements cannot be faked from the browser.
        </p>
        <button className="btn btn-outline" style={{marginTop:16}} onClick={onBack}>Back to dashboard</button>
      </div>
    </div>
  );

  if(loading) return (
    <div className="achievements-page">
      <div className="card achievements-hero">
        <div className="achievement-star-display"><div><strong>…</strong><small>Loading</small></div></div>
        <div>
          <div className="label" style={{color:t.amber}}>Stars and achievements</div>
          <h2>Checking your verified milestones</h2>
          <p>Loading the achievement definitions, unlock history, and total star balance.</p>
          <div className="achievement-progress"><span style={{width:"38%"}}/></div>
        </div>
      </div>
      <div className="achievement-grid">
        {Array.from({length:8},(_,index)=><div key={index} className="card achievement-card locked" style={{minHeight:180,animationDelay:`${index*.05}s`}} />)}
      </div>
    </div>
  );

  return (
    <div className="achievements-page">
      <section className="card achievements-hero">
        <div className="achievement-star-display" aria-label={`${totalStars} of ${ACHIEVEMENT_STAR_TOTAL} stars earned`}>
          <div><strong>{totalStars}</strong><small>/ {ACHIEVEMENT_STAR_TOTAL} stars</small></div>
        </div>
        <div>
          <div className="label" style={{color:t.amber}}>Verified milestone track</div>
          <h2>Stars you earn from real progress</h2>
          <p>
            Stars are awarded by SecurePlus after completed sessions are checked on the server. This keeps the system fair and makes future rewards harder to spoof.
          </p>
          <div className="achievement-progress"><span style={{width:`${progress}%`}}/></div>
          <div style={{display:"flex",gap:10,flexWrap:"wrap",alignItems:"center",fontSize:12,color:t.textSec}}>
            <span>{unlockMap.size} of {definitions.length} achievements unlocked</span>
            <span>·</span>
            <span>{ACHIEVEMENT_STAR_TOTAL-totalStars} stars remaining</span>
          </div>
          {data.error&&(
            <div style={{marginTop:12,fontSize:12,color:t.amber,lineHeight:1.55}}>
              Using local achievement definitions because the live achievement table could not be read yet.
            </div>
          )}
        </div>
      </section>

      <section className="achievement-interactive-board" aria-label="Achievement progress board">
        <div className="achievement-spotlight-card card">
          <div className="label" style={{color:t.green}}>Next milestone</div>
          <h3>{nextAchievement?.title||"Keep practising"}</h3>
          <p>{nextAchievement?.description||"Complete practice sessions to unlock more verified achievements."}</p>
          <div className="achievement-spotlight-reward"><Star size={16} fill="currentColor"/> {nextAchievement?.star_value||0} stars waiting</div>
        </div>
        <div className="achievement-spotlight-card card selected">
          <div className="label" style={{color:selectedUnlocked?t.amber:t.accent}}>{selectedUnlocked?"Unlocked spotlight":"Locked spotlight"}</div>
          <h3>{selectedAchievement?.title||"Select an achievement"}</h3>
          <p>{selectedAchievement?.description||"Tap an achievement card below to inspect it here."}</p>
          <div className="achievement-spotlight-reward">
            {selectedUnlocked?<CheckCircle2 size={16}/>:<LockKeyhole size={16}/>}
            {selectedUnlocked?`Unlocked ${new Date(selectedUnlocked.unlocked_at).toLocaleDateString()}`:"Tap cards below to preview goals"}
          </div>
        </div>
        <div className="achievement-filter-card card">
          <div className="label" style={{color:t.accent}}>Filter board</div>
          {[
            ["all","All",definitions.length],
            ["unlocked","Unlocked",unlockedDefinitions.length],
            ["locked","Locked",lockedDefinitions.length],
          ].map(([id,label,count])=>(
            <button key={id} className={`btn ${achievementFilter===id?"btn-primary":"btn-outline"}`} type="button" onClick={()=>setAchievementFilter(id)}>
              {label} <span>{count}</span>
            </button>
          ))}
        </div>
      </section>

      <div className="achievement-grid">
        {visibleAchievements.map(item=>{
          const unlocked=unlockMap.get(item.id);
          return (
            <article key={item.id} className={`card achievement-card ${unlocked?"unlocked":"locked"} ${selectedAchievement?.id===item.id?"selected":""}`} role="button" tabIndex={0} onClick={()=>setSelectedAchievementId(item.id)} onKeyDown={event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();setSelectedAchievementId(item.id);}}}>
              <div className="achievement-card-top">
                <span className="achievement-badge">{unlocked?<Star size={19} fill="currentColor"/>:<LockKeyhole size={19}/>}</span>
                <span className="achievement-stars"><Star size={13} fill="currentColor"/> {item.star_value}</span>
              </div>
              <div>
                <h3>{item.title}</h3>
                <p>{item.description}</p>
              </div>
              {unlocked?(
                <div className="achievement-earned">Unlocked {new Date(unlocked.unlocked_at).toLocaleDateString()}</div>
              ):(
                <div className="achievement-locked">Locked · complete the milestone to earn stars</div>
              )}
            </article>
          );
        })}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// MCQ PRACTICE
// ═══════════════════════════════════════════════════════════════
function MCQPractice({user,attempts,onSave,onUpgrade,onOpenDeepDive,t,onSignup,onFocusModeChange,isVisible=true,starred=[],onToggleStar,onReportQuestion,showQuestionCodes=false,smartReviewRequest=null,onSessionComplete,mcqBank=MCQ_BANK}) {
  const isGuest=user?.authProvider==="guest"||user?.loginMethod==="guest";
  const sessionKey=`mcq:${practiceSessionOwner(user)}`;
  const requestSignup=onSignup||onUpgrade;
  const bank=mcqBank?.length ? mcqBank : MCQ_BANK;
  const [chFilter,setChFilter]=useState("all");
  const [diffFilter,setDiffFilter]=useState("all");
  const [topicFilter,setTopicFilter]=useState("all");
  const [reviewMode,setReviewMode]=useState(isGuest?"random":"smart");
  const [quizCount,setQuizCount]=useState(isGuest?5:10);
  const [started,setStarted]=useState(false);
  const [questions,setQuestions]=useState([]);
  const [qi,setQi]=useState(0);
  const [selected,setSelected]=useState(null);
  const [submitted,setSubmitted]=useState(false);
  const [draftSelections,setDraftSelections]=useState([]);
  const [results,setResults]=useState([]);
  const [done,setDone]=useState(false);
  const [finishedReviewMode,setFinishedReviewMode]=useState(false);
  const [showWrong,setShowWrong]=useState(false);
  const [resumeAvailable,setResumeAvailable]=useState(false);
  const [answerBurst,setAnswerBurst]=useState(null);
  const [starredView,setStarredView]=useState(false);
  const [sessionStartedAt,setSessionStartedAt]=useState(null);
  const [sessionContext,setSessionContext]=useState(null);
  const starredSet=useMemo(()=>new Set(starred),[starred]);
  const starredMcqs=useMemo(()=>bank.filter(q=>starredSet.has(starKey("mcq",q.id))),[bank,starredSet]);
  const starredQuestionIds=useMemo(()=>new Set(starredMcqs.map(question=>question.id)),[starredMcqs]);

  const allTopics=[...new Set(bank.map(q=>q.topic))].sort();
  const chapterOptions=[
    {value:"all",label:`All Chapters (${bank.length})`},
    ...CHAPTERS.map(ch=>({value:ch.id,label:`Ch.${ch.id}: ${ch.title} (${bank.filter(q=>q.ch===ch.id).length})`})),
  ];
  const difficultyOptions=[
    {value:"all",label:"All Difficulties"},
    {value:"easy",label:"Easy",...difficultyMeta("easy")},
    {value:"medium",label:"Medium",...difficultyMeta("medium")},
    {value:"hard",label:"Hard",...difficultyMeta("hard")},
  ];
  const topicOptions=[
    {value:"all",label:"All Topics"},
    ...allTopics.map(tp=>({value:tp,label:tp})),
  ];
  const activeDiffFilter=isGuest?"all":diffFilter;
  const activeTopicFilter=isGuest?"all":topicFilter;

  const filtered=bank.filter(q=>{
    if(chFilter!=="all"&&q.ch!==chFilter)return false;
    if(activeDiffFilter!=="all"&&q.difficulty!==activeDiffFilter)return false;
    if(activeTopicFilter!=="all"&&q.topic!==activeTopicFilter)return false;
    return true;
  });
  const reviewSummary = getReviewSummary(attempts,bank);
  const quizSizes = isGuest ? [10,20,30] : [10,20,30,40,50];
  const sessionMinimum = 10;
  const latestMcqAttempts=getLatestMcqAttempts(attempts);
  const missedMcqIds=[...latestMcqAttempts.entries()].filter(([,attempt])=>attempt.correct===false).map(([questionId])=>questionId);
  const missedQuestions=bank.filter(q=>missedMcqIds.includes(q.id));
  const selectedChapter=chFilter==="all"?null:CHAPTERS.find(ch=>ch.id===chFilter);
  const guestMcqBenefits=[
    {title:"No account needed",body:"Try the question bank first. Sign up only when saving progress matters.",Icon:ShieldCheck,color:t.green},
    {title:"Instant weak-area clue",body:"Your result highlights the chapter that needs attention.",Icon:Target,color:t.amber},
    {title:"Save Smart Review later",body:"Create a free account after the set to keep your repair queue.",Icon:Brain,color:t.accent},
  ];
  const guestLengthLabels={10:"Quick warm-up",20:"Focused session",30:"Deep practice"};
  const launchChapterLabel=selectedChapter?`Chapter ${selectedChapter.id}: ${selectedChapter.title}`:"All chapters";
  const launchModeLabel=isGuest?"Random practice":reviewMode==="smart"?"Smart Review":"Random practice";

  useEffect(()=>{
    if(!isGuest)return;
    setDiffFilter("all");
    setTopicFilter("all");
    setReviewMode("random");
    setQuizCount(count=>[10,20,30].includes(count)?count:10);
  },[isGuest]);

  useEffect(()=>{
    onFocusModeChange?.(isVisible && started && !done && !finishedReviewMode);
    return()=>onFocusModeChange?.(false);
  },[isVisible,started,done,finishedReviewMode,onFocusModeChange]);

  useEffect(()=>{
    if(started)return;
    const available = quizSizes.filter(size=>filtered.length>=size);
    if(available.length && !available.includes(quizCount)) setQuizCount(available[available.length-1]);
  },[filtered.length,quizCount,started]);

  const startQuiz=()=>{
    const pool=buildMcqPracticePool(filtered, attempts, Math.min(quizCount,filtered.length), reviewMode, starredQuestionIds).map(shuffleMcqOptions);
    capture("mcq_quiz_started", { review_mode: reviewMode, chapter: chFilter, difficulty: activeDiffFilter, topic: activeTopicFilter, question_count: pool.length, tier: user.tier });
    setSessionContext({kind:reviewMode,label:reviewMode==="smart"?"Smart Review":"MCQ Practice"});
    setQuestions(pool);setQi(0);setSelected(null);setSubmitted(false);setDraftSelections([]);setResults([]);setDone(false);setFinishedReviewMode(false);setStarted(true);setSessionStartedAt(Date.now());
  };
  const startMissedQuiz=()=>{
    const pool=buildMcqPracticePool(missedQuestions,attempts,Math.min(50,missedQuestions.length),"smart",starredQuestionIds,{directMissedIds:missedMcqIds}).map(shuffleMcqOptions);
    capture("mcq_missed_review_started", { question_count: pool.length, tier: user.tier });
    setSessionContext({kind:"missed",label:"Missed-question repair"});
    setQuestions(pool);setQi(0);setSelected(null);setSubmitted(false);setDraftSelections([]);setResults([]);setDone(false);setFinishedReviewMode(false);setStarted(true);setSessionStartedAt(Date.now());
  };
  const startChapterSmartReview=useCallback((chapterId,requestedCount=10,source="chapter_review")=>{
    if(!chapterId||isGuest)return;
    const chapterKey=String(chapterId);
    const latestAttempts=getLatestMcqAttempts(attempts);
    const chapterQuestions=bank.filter(question=>String(question.ch)===chapterKey);
    const missedIds=new Set(chapterQuestions.filter(question=>latestAttempts.get(question.id)?.correct===false).map(question=>question.id));
    const missedTopics=new Set(chapterQuestions.filter(question=>missedIds.has(question.id)).map(question=>question.topic).filter(Boolean));
    const count=Math.max(1,Math.min(Number(requestedCount)||10,chapterQuestions.length));
    const pool=buildMcqPracticePool(
      chapterQuestions,
      attempts,
      count,
      "smart",
      starredQuestionIds,
      {focusChapterId:chapterKey,focusTopics:missedTopics,directMissedIds:missedIds}
    ).map(shuffleMcqOptions);
    if(!pool.length)return;
    const chapter=CHAPTERS.find(item=>item.id===chapterKey);
    setChFilter(String(chapterId));
    setDiffFilter("all");
    setTopicFilter("all");
    setReviewMode("smart");
    setQuizCount(pool.length);
    setQuestions(pool);
    setQi(0);
    setSelected(null);
    setSubmitted(false);
    setDraftSelections([]);
    setResults([]);
    setDone(false);
    setFinishedReviewMode(false);
    setStarted(true);
    setSessionStartedAt(Date.now());
    setStarredView(false);
    setSessionContext({kind:"weak-area",label:`Chapter ${chapterKey} repair sprint`,chapterId:chapterKey,chapterTitle:chapter?.title||"Focused review",source});
    capture("mcq_chapter_smart_review_started", { chapter: chapterKey, question_count: pool.length, missed_topic_count: missedTopics.size, source, tier: user.tier });
  },[attempts,bank,isGuest,starredQuestionIds,user.tier]);
  const startStarredQuiz=()=>{
    const pool=rankQuestionsBySm2(starredMcqs,attempts,new Set(starredMcqs.map(q=>q.id))).slice(0,Math.min(50,starredMcqs.length)).map(shuffleMcqOptions);
    capture("mcq_starred_review_started", { question_count: pool.length, tier: user.tier });
    setSessionContext({kind:"starred",label:"Starred-question review"});
    setQuestions(pool);setQi(0);setSelected(null);setSubmitted(false);setDraftSelections([]);setResults([]);setDone(false);setFinishedReviewMode(false);setStarted(true);setSessionStartedAt(Date.now());setStarredView(false);
  };

  useEffect(()=>{
    if(!smartReviewRequest?.chapterId||!smartReviewRequest?.nonce)return;
    startChapterSmartReview(smartReviewRequest.chapterId,smartReviewRequest.count,smartReviewRequest.source);
  },[smartReviewRequest?.chapterId,smartReviewRequest?.count,smartReviewRequest?.nonce,smartReviewRequest?.source,startChapterSmartReview]);

  useEffect(()=>{
    if(isGuest){setResumeAvailable(false);return;}
    let active=true;
    DB.getPracticeSession(sessionKey).then(saved=>{
      if(active)setResumeAvailable(Boolean(saved&&!saved.done&&saved.questions?.length));
    });
    return()=>{active=false;};
  },[isGuest,sessionKey]);

  useEffect(()=>{
    if(isGuest)return;
    if(!started||done||finishedReviewMode||!questions.length)return;
    DB.savePracticeSession(sessionKey,{questions,qi,selected,submitted,draftSelections,results,sessionContext,done:false,updatedAt:new Date().toISOString()});
  },[isGuest,sessionKey,started,done,finishedReviewMode,questions,qi,selected,submitted,draftSelections,results,sessionContext]);

  const continueQuiz=async()=>{
    const saved=await DB.getPracticeSession(sessionKey);
    if(!saved?.questions?.length)return;
    setQuestions(saved.questions);
    setQi(saved.qi||0);
    setSelected(saved.selected ?? saved.draftSelections?.[saved.qi||0] ?? null);
    setSubmitted(Boolean(saved.submitted));
    setDraftSelections(saved.draftSelections||[]);
    setResults(saved.results||[]);
    setSessionContext(saved.sessionContext||{kind:"saved",label:"Saved MCQ practice"});
    setDone(false);
    setFinishedReviewMode(false);
    setStarted(true);
    setShowWrong(false);
    setSessionStartedAt(Date.now());
  };

  const current=questions[qi];
  const answeredCount=results.filter(Boolean).length;
  const allAnswered=questions.length>0&&answeredCount===questions.length;
  const reportPracticeSession=useCallback(()=>{
    if(isGuest||!questions.length)return;
    const answered=results.filter(Boolean);
    if(answered.length!==questions.length)return;
    const correct=answered.filter(r=>r.correct).length;
    const chapterIds=[...new Set(questions.map(q=>String(q.ch||"")).filter(Boolean))];
    onSessionComplete?.({
      session_type:"practice",
      score:Math.round((correct/questions.length)*100),
      duration_seconds:Math.max(1,Math.round((Date.now()-(sessionStartedAt||Date.now()))/1000)),
      questions_count:questions.length,
      chapter_id:chapterIds.length===1?chapterIds[0]:null,
    });
  },[isGuest,onSessionComplete,questions,results,sessionStartedAt]);
  const goToQuestion=index=>{
    if(index<0||index>=questions.length)return;
    setQi(index);
    setSelected(results[index]?.selected ?? draftSelections[index] ?? null);
    setSubmitted(Boolean(results[index]));
    setShowWrong(false);
  };
  const reviewCompletedQuestion=index=>{
    const result=results[index];
    if(!result||!questions[index])return;
    setQi(index);
    setSelected(result.selected);
    setSubmitted(true);
    setDone(false);
    setFinishedReviewMode(true);
    setStarted(true);
    setShowWrong(false);
    setAnswerBurst(null);
    capture("mcq_completed_question_reviewed", { question_id: questions[index].id, correct: result.correct, tier: user.tier });
  };

  const submitQ=()=>{
    if(selected===null)return;
    const correct=selected===current.correct;
    const r={qid:current.id,correct,selected,title:current.q.slice(0,60),ch:current.ch,domain:CHAPTERS.find(c=>c.id===current.ch)?.title||"",topic:current.topic,difficulty:current.difficulty,mcq:true,createdAt:new Date().toISOString()};
    capture("mcq_question_answered", { question_id: current.id, chapter: current.ch, difficulty: current.difficulty, topic: current.topic, correct, tier: user.tier });
    setResults(rs=>{const next=[...rs];next[qi]=r;return next;});
    if(!results[qi]) onSave(r);
    playAnswerSound(correct);
    setAnswerBurst({correct,key:Date.now()});
    setTimeout(()=>setAnswerBurst(null),1700);
    setSubmitted(true);setShowWrong(false);
  };
  const nextQ=()=>{
    if(qi<questions.length-1) goToQuestion(qi+1);
    else {
      capture("mcq_quiz_completed", { correct_count: correctCount, question_count: questions.length, tier: user.tier });
      reportPracticeSession();
      DB.clearPracticeSession(sessionKey);
      setFinishedReviewMode(false);
      setDone(true);
    }
  };
  const finishQuiz=()=>{
    if(!allAnswered){
      const firstUnanswered=questions.findIndex((_,index)=>!results[index]);
      goToQuestion(firstUnanswered>=0?firstUnanswered:0);
      return;
    }
    capture("mcq_quiz_completed", { correct_count: correctCount, question_count: questions.length, tier: user.tier });
    reportPracticeSession();
    DB.clearPracticeSession(sessionKey);
    setFinishedReviewMode(false);
    setDone(true);
  };
  const retakeCurrentQuiz=()=>{
    setQi(0);setSelected(null);setSubmitted(false);setDraftSelections([]);setResults([]);setDone(false);setFinishedReviewMode(false);setStarted(true);setShowWrong(false);setSessionStartedAt(Date.now());
  };

  const correctCount=results.filter(r=>r?.correct).length;
  const scorePct=questions.length?correctCount/questions.length:0;
  const canSeeFeedback = user.tier === "pro";
  const chapterEvaluation=CHAPTERS.map(ch=>{
    const chapterResults=results.map((r,index)=>r?{...r,question:questions[index]}:null).filter(r=>r&&r.ch===ch.id);
    const missed=chapterResults.filter(r=>!r.correct);
    const topicCounts=missed.reduce((acc,r)=>{const topic=r.topic||r.question?.topic||"Core concepts";acc[topic]=(acc[topic]||0)+1;return acc;},{});
    const focusTopics=Object.entries(topicCounts).sort((a,b)=>b[1]-a[1]).slice(0,2).map(([topic])=>topic);
    return {chapter:ch,total:chapterResults.length,correct:chapterResults.filter(r=>r.correct).length,missed:missed.length,focusTopics};
  }).filter(item=>item.total>0).sort((a,b)=>(a.correct/a.total)-(b.correct/b.total));
  const weakChapters=chapterEvaluation.filter(item=>item.missed>0).slice(0,3);
  const sessionMissedQuestions=results
    .map((result,index)=>result&&!result.correct?questions[index]:null)
    .filter(Boolean);
  const sessionLessonPath=getDeepDiveRecommendations(sessionMissedQuestions,{limit:2});
  const guestWeakChapter=weakChapters[0]||null;
  const guestWeakTopics=guestWeakChapter?.focusTopics||[];
  const saveGuestSmartReview=async()=>{
    await savePendingGuestSmartReview(results.filter(Boolean));
    capture("guest_smart_review_save_clicked", {
      chapter:guestWeakChapter?.chapter?.id||"none",
      missed_count:sessionMissedQuestions.length,
      question_count:questions.length,
    });
    requestSignup?.();
  };
  const guestSignupPrompt=(
    <div className="card" style={{padding:"18px 20px",marginBottom:16,borderColor:`${t.accent}55`,background:`linear-gradient(135deg, ${t.accent}18, ${t.surface} 58%, ${t.green}10)`,boxShadow:`0 18px 42px ${t.accent}18`,textAlign:"left"}}>
      <div style={{display:"flex",gap:14,alignItems:"center",flexWrap:"wrap"}}>
        <div style={{width:52,height:52,borderRadius:14,background:`${guestWeakChapter?t.amber:t.green}18`,border:`1px solid ${guestWeakChapter?t.amber:t.green}38`,display:"flex",alignItems:"center",justifyContent:"center",flexShrink:0,color:guestWeakChapter?t.amber:t.green}}>
          {guestWeakChapter?<Target size={24}/>:<CheckCircle2 size={24}/>}
        </div>
        <div style={{flex:1,minWidth:240}}>
          <div className="label" style={{color:guestWeakChapter?t.amber:t.green,marginBottom:4}}>
            {guestWeakChapter?"Instant weak-area result":"Strong first set"}
          </div>
          <div style={{fontWeight:900,fontSize:17,color:t.text,marginBottom:4}}>
            {guestWeakChapter
              ? `Chapter ${guestWeakChapter.chapter.id}: ${guestWeakChapter.chapter.title}`
              : "Keep this result in your Smart Review history"}
          </div>
          <div style={{fontSize:13,color:t.textSec,lineHeight:1.65}}>
            {guestWeakChapter
              ? `You missed ${guestWeakTopics.length?guestWeakTopics.join(" and "):"one core concept"}. Create free account to save Smart Review, then run a 10-question repair set after signup.`
              : "Create a free account and SecurePlus will save this score, space out mastered questions, and build your personalised Smart Review queue."}
          </div>
        </div>
        <button className="btn btn-primary" style={{fontSize:13,flexShrink:0}} onClick={saveGuestSmartReview}>Save my Smart Review</button>
      </div>
    </div>
  );

  if(starredView) return(
    <div style={{padding:"24px",maxWidth:860,margin:"0 auto"}}>
      <div className="page-title-row" style={{marginBottom:12}}>
        <NavGlyph type="mcq" active/>
        <div>
          <h2 style={{fontSize:24,fontWeight:800,color:t.text}}>Starred MCQs</h2>
          <p style={{fontSize:13,color:t.textSec}}>Questions you saved for future review.</p>
        </div>
      </div>
      <div style={{display:"flex",gap:10,marginBottom:16,flexWrap:"wrap"}}>
        <button className="btn btn-ghost" onClick={()=>setStarredView(false)}>← Back to MCQ Practice</button>
        <button className="btn btn-primary" disabled={!starredMcqs.length} onClick={startStarredQuiz}>Practise Starred</button>
      </div>
      {starredMcqs.length?(
        <div style={{display:"grid",gap:10}}>
          {starredMcqs.map(q=>(
            <div key={q.id} className="card card-hover" style={{padding:"14px 16px",display:"flex",gap:12,alignItems:"flex-start"}}>
              <StarButton active onToggle={()=>onToggleStar?.("mcq",q.id)} label="Unstar question"/>
              <div style={{flex:1,minWidth:0}}>
                <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:8}}>
                  <ChBadge chId={q.ch} t={t}/>
                  {showQuestionCodes&&<QuestionCodeChip id={q.id} t={t}/>}
                  <DiffBadge d={q.difficulty} t={t}/>
                  <span className="chip" style={{background:t.panel,color:t.textSec,borderColor:t.border}}>{q.topic}</span>
                  <BeyondTextbookTag question={q} t={t}/>
                </div>
                <div style={{fontSize:14,color:t.text,lineHeight:1.65}}><QuestionStemText text={q.q} t={t} compact/></div>
              </div>
            </div>
          ))}
        </div>
      ):(
        <div className="card" style={{padding:"20px 22px",color:t.textSec,fontSize:14,lineHeight:1.7}}>
          No starred MCQs yet. Press the star while doing a question to save it here.
        </div>
      )}
    </div>
  );

  if(!started) return(
    <div className={`mcq-setup-screen fu ${isGuest?"guest-mcq-setup":""}`} style={{padding:"24px",maxWidth:1040,margin:"0 auto"}}>
      <header className="practice-page-head">
        <div className="practice-page-heading">
          <div className="practice-page-icon"><BookOpenCheck size={23} strokeWidth={2.3}/></div>
          <div>
            <div className="label" style={{color:t.accent}}>Knowledge practice</div>
            <h2>{isGuest?"Start a free MCQ set":"MCQ Practice"}</h2>
            <p>{isGuest?"Choose 10, 20, or 30 questions and filter by chapter without creating an account.":"Build a focused question set and get clear feedback as you work."}</p>
          </div>
        </div>
        <div className="practice-page-meta">
          <span className="practice-meta-pill"><strong>{bank.length}</strong> questions</span>
          <span className="practice-meta-pill"><strong>5</strong> chapters</span>
          <span className="practice-meta-pill">SY0-701</span>
        </div>
      </header>
      <div style={{marginBottom:16}}>
        <TrustBadge t={t}/>
      </div>

      <section className="practice-setup-hero">
        <div className="practice-setup-copy">
          <div>
            <div className="label" style={{color:t.green}}>Step 1 · Choose your practice style</div>
            <h3>{isGuest?"Choose a simple guest set":"How should SecurePlus choose your questions?"}</h3>
            <p>{isGuest?"Guest practice uses random Security+ questions from your selected chapter. Create an account later to save results and unlock Smart Review.":"Use Smart Review to revisit weak or due topics, or choose Random Practice for a fresh mixed set."}</p>
          </div>
          {!isGuest&&(
            <div className="setup-stats">
              {[
                {label:"Due",value:reviewSummary.due,color:t.amber},
                {label:"Weak",value:reviewSummary.weak,color:t.red},
                {label:"New",value:reviewSummary.untouched,color:t.accent},
              ].map(item=>(
                <div key={item.label} className="setup-stat">
                  <div style={{fontSize:18,fontWeight:800,color:item.color}}>{item.value}</div>
                  <div className="label">{item.label}</div>
                </div>
              ))}
            </div>
          )}
        </div>
        {isGuest?(
          <div className="guest-mcq-path-grid">
            {[
              ["1","Choose chapter","Filter broadly by exam chapter only.",Layers3,t.accent],
              ["2","Pick set size","10, 20, or 30 questions. No account required.",ListChecks,t.green],
              ["3","Save if useful","Turn results into Smart Review after signup.",Brain,t.amber],
            ].map(([step,title,body,Icon,color])=>(
              <article key={step} style={{"--path-color":color}}>
                <span>{step}</span>
                <Icon size={19}/>
                <strong>{title}</strong>
                <small>{body}</small>
              </article>
            ))}
          </div>
        ):(
          <div className="practice-mode-grid">
            <button className={`practice-mode-card ${reviewMode==="smart"?"active":""}`} style={{"--mode-color":t.green}} onClick={()=>setReviewMode("smart")} aria-pressed={reviewMode==="smart"}>
              <span className="practice-mode-icon"><Brain size={19}/></span>
              <span><strong>Smart Review</strong><small>Prioritises due, missed, and starred questions.</small></span>
              <span className="practice-mode-check"><Check size={13} strokeWidth={3}/></span>
            </button>
            <button className={`practice-mode-card ${reviewMode==="random"?"active":""}`} style={{"--mode-color":t.accent}} onClick={()=>setReviewMode("random")} aria-pressed={reviewMode==="random"}>
              <span className="practice-mode-icon"><Sparkles size={19}/></span>
              <span><strong>Random Practice</strong><small>Creates a fresh set from your selected scope.</small></span>
              <span className="practice-mode-check"><Check size={13} strokeWidth={3}/></span>
            </button>
          </div>
        )}
        {isGuest&&(
          <div className="guest-mcq-lock-note">
            <LockKeyhole size={15}/>
            <span>Topic, difficulty, and Smart Review use saved history, so they unlock after account creation.</span>
          </div>
        )}
      </section>

      {!isGuest&&(
        <section className="mcq-review-queue-row" aria-label="MCQ review queues">
          <button className="mcq-review-queue-card unfinished" type="button" disabled={!resumeAvailable} onClick={continueQuiz}>
            <span className="mcq-review-queue-icon"><Clock3 size={21}/></span>
            <span>
              <strong>Unfinished MCQ</strong>
              <small>{resumeAvailable?"Continue your saved set":"No unfinished set"}</small>
            </span>
            <em>{resumeAvailable?"Continue":"0"}</em>
          </button>
          <button className="mcq-review-queue-card missed" type="button" disabled={!missedQuestions.length} onClick={startMissedQuiz}>
            <span className="mcq-review-queue-icon"><Target size={21}/></span>
            <span>
              <strong>Missed MCQ</strong>
              <small>{missedQuestions.length?`Repair ${missedQuestions.length} incorrect question${missedQuestions.length===1?"":"s"}`:"No missed MCQs yet"}</small>
            </span>
            <em>{missedQuestions.length}</em>
          </button>
          <button className="mcq-review-queue-card starred" type="button" onClick={()=>setStarredView(true)}>
            <span className="mcq-review-queue-icon"><Star size={21} fill="currentColor"/></span>
            <span>
              <strong>Starred MCQ</strong>
              <small>{starredMcqs.length?`Review ${starredMcqs.length} saved question${starredMcqs.length===1?"":"s"}`:"Build a saved review list"}</small>
            </span>
            <em>{starredMcqs.length}</em>
          </button>
        </section>
      )}

      <section className="mcq-launch-pad" aria-label="Start MCQ question set">
        <div className="mcq-launch-main">
          <span className="mcq-launch-icon"><Play size={25} fill="currentColor"/></span>
          <div>
            <h3>Ready to answer questions?</h3>
            <p>Press the button to begin now. Changing chapter or set size below is optional.</p>
            <div className="mcq-launch-steps" aria-label="Selected MCQ setup">
              <span><strong>{quizCount}</strong> questions</span>
              <span>{launchChapterLabel}</span>
              <span>{launchModeLabel}</span>
            </div>
          </div>
        </div>
        <div className="mcq-launch-action">
          <button className="btn btn-primary" type="button" onClick={startQuiz} disabled={filtered.length<sessionMinimum}>
            Start questions now →
          </button>
          <small>{filtered.length>=sessionMinimum?`${filtered.length} questions available for this choice.`:`Only ${filtered.length} questions match. Choose all chapters to start.`}</small>
        </div>
      </section>

      {isGuest&&(
        <section className="guest-mcq-showcase">
          <div className="guest-mcq-showcase-copy">
            <div className="label" style={{color:t.accent}}>Practice studio</div>
            <h3>Try the real study loop before signing up.</h3>
            <p>Pick a chapter, choose 10–30 MCQs, then see what SecurePlus would save into Smart Review if you create an account.</p>
            <div className="guest-mcq-benefit-grid">
              {guestMcqBenefits.map(({title,body,Icon,color})=>(
                <article key={title} style={{"--guest-benefit-color":color}}>
                  <span><Icon size={17}/></span>
                  <strong>{title}</strong>
                  <small>{body}</small>
                </article>
              ))}
            </div>
            <div className="guest-mcq-save-strip">
              <Sparkles size={17}/>
              <span><strong>After your set:</strong> save your weak-area result, streaks, and Smart Review queue with an account.</span>
              <button type="button" className="btn btn-primary" onClick={requestSignup}>Create account</button>
            </div>
          </div>
        </section>
      )}

      {user.tier==="free"&&(
        <div className="card" style={{padding:"16px 20px",marginBottom:16,borderColor:`${t.accent}30`,background:`${t.accent}06`}}>
          <div style={{display:"flex",gap:12,alignItems:"center",flexWrap:"wrap"}}>
            <div style={{flex:1}}>
              <div style={{fontWeight:600,fontSize:14,color:t.text}}>MCQs stay free. Pro adds exam-style PBQs.</div>
              <div style={{fontSize:13,color:t.textSec}}>When you are ready to practise terminal, log, ordering, and Select &amp; Fill simulations, the {PRO_ACADEMY_PASS_NAME} is {PRO_ACADEMY_PASS_PRICE}.</div>
            </div>
            <button className="btn btn-outline" style={{fontSize:12,flexShrink:0}} onClick={onUpgrade}>See Pro PBQs</button>
          </div>
        </div>
      )}
      <div className="card practice-filter-card" style={{padding:"20px 24px",marginBottom:16}}>
        <div className="practice-builder-head">
          <div>
            <div className="label" style={{color:t.accent}}>Optional setup</div>
            <h3>Want a different set?</h3>
            <p>Use these controls only if you want to change the chapter or number of questions before starting.</p>
          </div>
          {(chFilter!=="all"||diffFilter!=="all"||topicFilter!=="all")&&(
            <button className="btn btn-ghost" style={{fontSize:11,minHeight:34,padding:"7px 10px"}} onClick={()=>{setChFilter("all");setDiffFilter("all");setTopicFilter("all");}}><X size={14}/> Reset filters</button>
          )}
        </div>
        <div className="practice-builder-step">
          <div className="practice-step-head"><span className="practice-step-index">1</span><strong>Choose chapter</strong><span>{filtered.length} matching questions</span></div>
          <div className="practice-filter-grid" style={{display:"grid",gridTemplateColumns:"1fr 1fr 1fr",gap:12}}>
            <div>
              <label className="label" style={{display:"block",marginBottom:6}}>Chapter</label>
              <FilterSelect value={chFilter} onChange={setChFilter} options={chapterOptions} label="Chapter filter"/>
            </div>
            <div>
              <label className="label" style={{display:"block",marginBottom:6}}>Difficulty</label>
              <FilterSelect value={diffFilter} onChange={setDiffFilter} options={difficultyOptions} disabled={isGuest} label="Difficulty filter"/>
              {isGuest&&<div style={{fontSize:11,color:t.textDim,marginTop:6}}>Create an account to filter by difficulty.</div>}
            </div>
            <div>
              <label className="label" style={{display:"block",marginBottom:6}}>Topic</label>
              <FilterSelect value={topicFilter} onChange={setTopicFilter} options={topicOptions} disabled={isGuest} label="Topic filter"/>
              {isGuest&&<div style={{fontSize:11,color:t.textDim,marginTop:6}}>Create an account to filter by topic.</div>}
            </div>
          </div>
          {isGuest&&(
            <div style={{marginTop:14,padding:"12px 14px",borderRadius:7,background:`${t.accent}08`,border:`1px solid ${t.accent}25`,fontSize:12,color:t.textSec,lineHeight:1.6}}>
              Guest users can choose chapter and fixed set size only. Topic, difficulty, Smart Review, and saved weak-area history unlock after account creation.
            </div>
          )}
          {isGuest&&(
            <div className="guest-chapter-choice-grid" aria-label="Guest chapter quick choices">
              <button type="button" className={chFilter==="all"?"active":""} style={{"--chapter-choice-color":t.accent}} onClick={()=>setChFilter("all")}>
                <span>All</span>
                <strong>Mixed chapters</strong>
                <small>{bank.length} questions available</small>
              </button>
              {CHAPTERS.map(ch=>(
                <button key={ch.id} type="button" className={chFilter===ch.id?"active":""} style={{"--chapter-choice-color":chapterColor(ch.id)}} onClick={()=>setChFilter(ch.id)}>
                  <span>Ch.{ch.id}</span>
                  <strong>{ch.title}</strong>
                  <small>{bank.filter(q=>q.ch===ch.id).length} questions · {ch.weight}% exam weight</small>
                </button>
              ))}
            </div>
          )}
        </div>
        <div className="practice-builder-step">
          <div className="practice-step-head"><span className="practice-step-index">2</span><strong>Choose number of questions</strong><span>{quizCount} selected</span></div>
          <div className={`quiz-length-grid ${isGuest?"guest-length-grid":""}`} style={{display:"grid",gridTemplateColumns:`repeat(${quizSizes.length},minmax(0,1fr))`,gap:8}}>
            {quizSizes.map(size=>(
              <button
                key={size}
                className={`btn ${quizCount===size?"btn-primary":"btn-ghost"}`}
                style={{fontSize:12,padding:"8px 10px",minHeight:isGuest?58:36}}
                disabled={filtered.length<size}
                onClick={()=>setQuizCount(size)}
              >
                <span>{size}<span style={{fontSize:9,opacity:.7}}> Qs</span></span>
                {isGuest&&<small>{guestLengthLabels[size]}</small>}
              </button>
            ))}
          </div>
        </div>
        <div className="practice-builder-footer">
          <div className="practice-builder-result">
            <div className="practice-builder-count">{quizCount}</div>
            <div><strong>{isGuest?"Guest practice set":reviewMode==="smart"?"Smart Review set":"Random practice set"}</strong><small>{filtered.length>=sessionMinimum?`${filtered.length} questions match your focus`:`Only ${filtered.length} match — broaden your filters`}</small></div>
          </div>
          <button className="btn btn-primary" style={{minWidth:170}} onClick={startQuiz} disabled={filtered.length<sessionMinimum}>
            {`Start questions now →`}
          </button>
        </div>
      </div>

      {/* Chapter overview */}
      <details className="practice-secondary">
        <summary><span>Browse all five exam chapters</span><span style={{fontSize:11,color:t.textDim,fontWeight:700}}>Optional</span></summary>
        <div className="practice-secondary-content practice-chapter-grid">
          {CHAPTERS.map(ch=>(
            <div key={ch.id} className="chapter-card" style={{display:"flex",gap:12,alignItems:"center",padding:"10px 14px",borderRadius:8,background:chFilter===ch.id?`${chapterColor(ch.id)}12`:t.panel,cursor:"pointer",border:`1px solid ${chFilter===ch.id?chapterColor(ch.id):t.border}`,transition:"all .15s"}} onClick={()=>setChFilter(ch.id===chFilter?"all":ch.id)}>
              <ChapterIcon id={ch.id}/>
              <div style={{flex:1}}>
                <div style={{fontSize:13,fontWeight:600,color:t.text}}>Ch.{ch.id}: {ch.title}</div>
                <div style={{fontSize:11,color:t.textDim}}>{ch.weight}% of exam · {bank.filter(q=>q.ch===ch.id).length} questions available</div>
              </div>
              <span className="chip" style={{background:`${t.accent}12`,color:t.accent,borderColor:`${t.accent}25`,fontSize:11}}>{ch.weight}%</span>
            </div>
          ))}
        </div>
      </details>
    </div>
  );

  if(done) return(
    <div className="fu mcq-results-screen" style={{padding:"24px",maxWidth:760,margin:"0 auto",textAlign:"center"}}>
      <section className="practice-result-hero" style={{"--result-color":scorePct>=.8?t.green:scorePct>=.5?t.amber:t.red}}>
        <div className="practice-score-ring" style={{"--score":Math.round(scorePct*100),"--ring":scorePct>=.8?t.green:scorePct>=.5?t.amber:t.red}}>
          <strong>{Math.round(scorePct*100)}%</strong>
          <small>{correctCount} / {questions.length} correct</small>
        </div>
        <div className="practice-result-copy">
          <div className="practice-result-kicker">Practice complete</div>
          <h2>{scorePct>=.8?"Strong work.":scorePct>=.5?"Good progress.":"A useful first pass."}</h2>
          <p>{scorePct>=.8
            ?"You are showing solid recall across this set. Keep the momentum by spacing the next review."
            :scorePct>=.5
              ?"You have a good base. Review the misses below, then try a focused set while the ideas are fresh."
              :"Mistakes are useful data. Review the missed concepts now and they will become easier to recognise next time."}</p>
          <div className="practice-result-actions">
            <button className="btn btn-primary" onClick={retakeCurrentQuiz}>Retry this set</button>
            <button className="btn btn-ghost" onClick={()=>{setStarted(false);setDone(false);setFinishedReviewMode(false);}}>Build a new quiz</button>
          </div>
        </div>
      </section>
      {isGuest&&guestSignupPrompt}
      <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",gap:12,margin:"22px 0 10px",textAlign:"left"}}>
        <div>
          <div style={{fontSize:11,fontWeight:900,textTransform:"uppercase",color:t.accent}}>Answer review</div>
          <h3 style={{fontSize:19,color:t.text}}>Tap any question to review it</h3>
          <p style={{fontSize:12,color:t.textSec,lineHeight:1.55,marginTop:3}}>Review correct and incorrect answers in their answered state.</p>
        </div>
        <span className="chip" style={{color:t.textSec,borderColor:t.border,background:t.panel}}>{results.length} answered</span>
      </div>
      <div className="card practice-review-list" style={{padding:"16px 20px",marginBottom:16,textAlign:"left"}}>
        {results.map((r,i)=>(
          <button key={i} type="button" className="practice-review-row" style={{"--review-color":r.correct?t.green:t.red}} onClick={()=>reviewCompletedQuestion(i)}>
            <span className="practice-review-status">{r.correct?<Check size={16} strokeWidth={3}/>:<X size={16} strokeWidth={3}/>}</span>
            <span>{questions[i]?.q?.slice(0,88)}{questions[i]?.q?.length>88?"...":""}</span>
            <small>{r.correct?"Review correct":"Review miss"}</small>
          </button>
        ))}
      </div>
      {!isGuest&&user.tier!=="pro"&&sessionLessonPath.length>0&&(
        <SmartReviewLessonPath recommendations={sessionLessonPath} onOpenDeepDive={onOpenDeepDive} source="mcq_result" title="Concept lessons matched to this set"/>
      )}
      {user.tier==="pro"?(
        <div className="card" style={{padding:"16px 18px",marginBottom:16,textAlign:"left",borderColor:`${t.accent}28`,background:`${t.accent}05`}}>
          <div style={{display:"flex",justifyContent:"space-between",gap:10,alignItems:"center",marginBottom:10,flexWrap:"wrap"}}>
            <div>
              <div style={{fontWeight:900,color:t.text,fontSize:15}}>Pro evaluation</div>
              <div style={{fontSize:12,color:t.textDim}}>Based on this set</div>
            </div>
            <span className="chip" style={{background:`${t.accent}12`,color:t.accent,borderColor:`${t.accent}25`}}>Pro evaluation</span>
          </div>
          {weakChapters.length===0?(
            <div style={{fontSize:13,color:t.textSec,lineHeight:1.65}}>
              No weak chapter detected in this set. Next: run a timed Exam Mode set or continue Smart Review.
            </div>
          ):(
            <div style={{display:"grid",gap:9}}>
              <div style={{fontSize:13,color:t.textSec,lineHeight:1.6}}>
                Work on {weakChapters.map(item=>`Ch.${item.chapter.id}`).join(", ")} first. Open the matched lesson, then retry Smart Review.
              </div>
              {weakChapters.map(item=>{
                const accuracy=Math.round((item.correct/item.total)*100);
                const topics=item.focusTopics.length?item.focusTopics.join(" and "):item.chapter.title;
                const lessonPath=getDeepDiveRecommendations(
                  sessionMissedQuestions.filter(question=>question.ch===item.chapter.id),
                  {limit:1}
                );
                const lesson=lessonPath[0];
                return(
                  <div key={item.chapter.id} style={{display:"grid",gridTemplateColumns:"minmax(0,1fr) auto",gap:10,alignItems:"center",padding:"11px 12px",border:`1px solid ${t.border}`,borderRadius:10,background:t.surface}}>
                    <div style={{minWidth:0}}>
                      <div style={{display:"flex",gap:8,alignItems:"center",flexWrap:"wrap",marginBottom:4}}>
                        <div style={{fontSize:13,fontWeight:900,color:t.text}}>Ch.{item.chapter.id}: {item.chapter.title}</div>
                        <span style={{fontSize:12,fontWeight:900,color:accuracy>=75?t.green:accuracy>=50?t.amber:t.red}}>{accuracy}%</span>
                      </div>
                      <div style={{fontSize:12,color:t.textSec,lineHeight:1.5}}>
                        Focus: {topics}{lesson?` · Lesson: ${lesson.title}`:""}
                      </div>
                    </div>
                    {lesson?(
                      <button className="btn btn-outline" type="button" style={{fontSize:12,minHeight:36,padding:"8px 12px",whiteSpace:"nowrap"}} onClick={()=>onOpenDeepDive?.(lesson.id,{source:"mcq_result_pro_evaluation"})}>
                        Learn <ChevronRight size={14}/>
                      </button>
                    ):(
                      <div style={{fontSize:12,fontWeight:700,color:accuracy>=75?t.green:accuracy>=50?t.amber:t.red}}>{accuracy}%</div>
                    )}
                  </div>
                );
              })}
            </div>
          )}
        </div>
      ):(
        <div className="card" style={{padding:"16px 20px",marginBottom:16,textAlign:"left",borderColor:`${t.accent}35`,background:`${t.accent}07`}}>
          <div style={{fontWeight:700,color:t.text,fontSize:14,marginBottom:4}}>Pro unlocks your improvement plan</div>
          <div style={{fontSize:13,color:t.textSec,lineHeight:1.65,marginBottom:10}}>
            After each MCQ test, Pro shows which chapters need work and suggests what to study next, such as PKI, access control, or incident response concepts.
          </div>
          <button className="btn btn-outline" style={{fontSize:12}} onClick={onUpgrade}>See Pro</button>
        </div>
      )}
      {user.tier==="free"&&(
        <div className="card" style={{padding:"16px 20px",marginBottom:16,textAlign:"left",borderColor:`${t.accent}35`,background:`${t.accent}07`}}>
          <div style={{fontWeight:700,color:t.text,fontSize:14,marginBottom:4}}>Want the PBQ side of the exam too?</div>
          <div style={{fontSize:13,color:t.textSec,lineHeight:1.65,marginBottom:10}}>
            Your MCQ practice stays free. The {PRO_ACADEMY_PASS_NAME} adds hands-on PBQ simulations for {PRO_ACADEMY_PASS_PRICE}.
          </div>
          <button className="btn btn-outline" style={{fontSize:12}} onClick={onUpgrade}>Preview Pro PBQs</button>
        </div>
      )}
    </div>
  );

  return(
    <div style={{padding:"24px",maxWidth:700,margin:"0 auto"}} className="fu active-practice-screen mcq-question-screen" key={qi}>
      <header className="practice-session-header">
        <div className="practice-session-top">
          <div className="practice-session-name"><span>{finishedReviewMode?<CheckCircle2 size={16}/>:sessionContext?.kind==="weak-area"?<Brain size={16}/>:<BookOpenCheck size={16}/>}</span>{finishedReviewMode?"Answered Set Review":sessionContext?.label||"MCQ Practice"}</div>
          <div className="practice-session-count">Question {qi+1} of {questions.length} · {answeredCount} answered</div>
        </div>
        <div className="practice-session-progress" aria-label={`${Math.round(((qi+1)/questions.length)*100)}% through this practice set`}><span style={{width:`${((qi+1)/questions.length)*100}%`}}/></div>
        <nav className="practice-question-nav" aria-label="Questions in this practice set">
          {questions.map((_,i)=>(
            <button
              key={i}
              className={`practice-question-index ${i===qi?"current":results[i]?.correct?"correct":results[i]?"wrong":draftSelections[i]!==undefined?"draft":""}`}
              aria-label={`Go to question ${i+1}`}
              aria-current={i===qi?"step":undefined}
              onClick={()=>goToQuestion(i)}
            >{i+1}</button>
          ))}
        </nav>
        <div className="practice-session-controls">
          <button className="btn btn-ghost" style={{fontSize:11,minHeight:34,padding:"7px 10px"}} disabled={qi===0} onClick={()=>goToQuestion(qi-1)}>← Previous</button>
          <span>{finishedReviewMode?"Reviewing completed answers":allAnswered?"All questions answered":"You can return to drafted answers anytime"}</span>
          <button className="btn btn-ghost" style={{fontSize:11,minHeight:34,padding:"7px 10px"}} disabled={qi===questions.length-1} onClick={()=>goToQuestion(qi+1)}>Next →</button>
        </div>
      </header>

      {/* Question card */}
      <div className="card question-card" style={{padding:"22px 26px",marginBottom:18}}>
        <div className="label" style={{color:t.accent,marginBottom:9}}>Question {qi+1}</div>
        <div style={{display:"flex",gap:8,marginBottom:12,flexWrap:"wrap"}}>
          <ChBadge chId={current.ch} t={t}/>
          {showQuestionCodes&&<QuestionCodeChip id={current.id} t={t}/>}
          <DiffBadge d={current.difficulty} t={t}/>
          <span className="chip meta-chip" style={{fontSize:11}}>{current.topic}</span>
          <BeyondTextbookTag question={current} t={t}/>
          {!isGuest&&(
            <span style={{marginLeft:"auto"}}>
              <StarButton active={starredSet.has(starKey("mcq",current.id))} onToggle={()=>onToggleStar?.("mcq",current.id)} label="Star MCQ"/>
            </span>
          )}
        </div>
        <div className="question-text" style={{fontSize:16,lineHeight:1.75,color:t.text}}>
          <QuestionStemText text={current.q} t={t}/>
        </div>
      </div>

      {/* Options */}
      <div className="practice-option-list" style={{display:"flex",flexDirection:"column",gap:9,marginBottom:20}}>
        {current.opts.map((opt,i)=>{
          let cls="opt";
          if(submitted){cls+=" done"; if(i===current.correct)cls+=" ok"; else if(i===selected&&i!==current.correct)cls+=" bad";}
          else if(selected===i)cls+=" sel";
          const showSelectedWrongFeedback=submitted&&canSeeFeedback&&i===selected&&i!==current.correct;
          return(
            <button
              type="button"
              key={i}
              className={cls}
              aria-pressed={!submitted&&selected===i}
              disabled={submitted}
              onClick={()=>{if(submitted)return;setSelected(i);setDraftSelections(prev=>{const next=[...prev];next[qi]=i;return next;});}}
            >
              <div className="opt-ltr">{String.fromCharCode(65+i)}</div>
              <div className="option-body">
                <span className="option-text" style={{fontSize:14,flex:1,lineHeight:1.55,color:t.text}}><GlossaryText text={opt} t={t}/></span>
                {showSelectedWrongFeedback&&(
                  <div className="option-inline-feedback">
                    <strong>Why this choice is wrong:</strong>
                    <GlossaryText text={getWrongOptionFeedback(current, i)} t={t}/>
                  </div>
                )}
              </div>
              {submitted&&i===current.correct&&<Check size={18} color={t.green} strokeWidth={2.8}/>}
              {submitted&&i===selected&&i!==current.correct&&<X size={18} color={t.red} strokeWidth={2.8}/>}
            </button>
          );
        })}
      </div>

      {!submitted?(
        <div className="practice-action-bar">
          <div className="practice-action-copy"><strong>{selected===null?"Choose one answer":"Answer selected"}</strong>{selected===null?"Select the option you think is strongest.":`Option ${String.fromCharCode(65+selected)} is ready to submit.`}</div>
          <button className="btn btn-primary" style={{minWidth:190}} disabled={selected===null} onClick={submitQ}>
            Check my answer →
          </button>
        </div>
      ):(
        <>
          <div className="card answer-feedback" style={{padding:"16px 18px",marginBottom:14,borderColor:selected===current.correct?`${t.green}42`:`${t.red}42`,background:selected===current.correct?`${t.green}08`:`${t.red}08`,boxShadow:"none"}}>
            <div style={{marginBottom:10}}><MCQFeedbackVerdict correct={selected===current.correct} t={t}/></div>
            {canSeeFeedback?(
              <p style={{fontSize:13,color:t.textSec,lineHeight:1.75}}><GlossaryText text={current.exp} t={t}/></p>
            ):(
              <div>
                <p style={{fontSize:13,color:t.textSec,lineHeight:1.75,marginBottom:10}}>
                  Detailed explanations and per-question feedback are available with Pro.
                </p>
                <button className="btn btn-outline" style={{fontSize:12}} onClick={isGuest?requestSignup:onUpgrade}>
                  {isGuest?"Create free account":"Unlock feedback"}
                </button>
              </div>
            )}
            {onReportQuestion&&<div style={{display:"flex",justifyContent:"flex-end",marginTop:12}}>
              <button
                className="btn btn-ghost"
                style={{fontSize:12,minHeight:34,padding:"7px 10px"}}
                onClick={()=>onReportQuestion?.({kind:"mcq",question:current,selected,correct:current.correct})}
              >
                Report question
              </button>
            </div>}
          </div>
          <AnswerBurst result={answerBurst} t={t}/>
          {finishedReviewMode?(
            <div className="practice-action-bar">
              <div className="practice-action-copy"><strong>Review mode</strong>Choose another question number above, or return to the result summary.</div>
              <button className="btn btn-primary" style={{minWidth:190}} onClick={()=>{setDone(true);setFinishedReviewMode(false);setAnswerBurst(null);}}>
                Back to results →
              </button>
            </div>
          ):(
            <div className="practice-action-bar">
              <div className="practice-action-copy"><strong>{selected===current.correct?"Keep the momentum":"Use the feedback, then continue"}</strong>{qi<questions.length-1?"Your next question is ready.":allAnswered?"Your result summary is ready.":"Some questions still need answers."}</div>
              <button className="btn btn-primary" style={{minWidth:190}} onClick={qi<questions.length-1?nextQ:finishQuiz}>
                {qi<questions.length-1?"Next Question →":allAnswered?"See Results →":"Review Unanswered →"}
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// PBQ BANK
// ═══════════════════════════════════════════════════════════════
function UpgradeModal({price=PRO_ACADEMY_PASS_PRICE,onUpgrade,onClose,t}) {
  return(
    <div style={{padding:"28px 24px",maxWidth:620,margin:"0 auto"}}>
      <div className="card" style={{padding:"24px",borderColor:`${t.accent}45`,background:`linear-gradient(135deg, ${t.accent}10, ${t.surface})`}}>
        <div className="page-title-row" style={{marginBottom:12}}>
          <span className="section-icon" style={{"--section-color":t.accent}}><LockKeyhole size={21} strokeWidth={2.3}/></span>
          <div>
            <h2 style={{fontSize:24,color:t.text}}>PBQs are Pro content</h2>
            <p style={{fontSize:13,color:t.textSec,lineHeight:1.65}}>Your current session cannot access this PBQ from the remote bank. Upgrade to unlock the full simulator.</p>
          </div>
        </div>
        <div style={{padding:"13px 14px",marginBottom:14,borderRadius:10,background:`${t.accent}0c`,border:`1px solid ${t.accent}28`}}>
          <div style={{fontSize:12,fontWeight:950,color:t.accent,marginBottom:4}}>{PRO_ACADEMY_PASS_NAME} · {price}</div>
          <div style={{fontSize:12,color:t.textSec,lineHeight:1.6,marginBottom:8}}>{PRO_ACADEMY_PASS_DESCRIPTION}</div>
          <div className="upgrade-original-line"><ShieldCheck size={14}/>{PRO_ACADEMY_PASS_TRUST}</div>
        </div>
        <div style={{display:"flex",gap:10,flexWrap:"wrap",alignItems:"center",justifyContent:"flex-end"}}>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            {onClose&&<button className="btn btn-ghost" onClick={onClose}>Back</button>}
            <button className="btn btn-primary" onClick={onUpgrade}>View Academy Pass</button>
          </div>
        </div>
      </div>
    </div>
  );
}

function PBQLoadingSkeleton({t}) {
  return(
    <div className="pbq-bank-screen fu" style={{padding:"24px",maxWidth:900,margin:"0 auto"}}>
      <div className="card animate-pulse rounded-xl p-6" style={{padding:24,background:t.surface,border:`1px solid ${t.border}`}}>
        <div style={{height:22,width:"38%",borderRadius:8,background:t.border,marginBottom:14}}/>
        <div style={{height:14,width:"70%",borderRadius:8,background:t.panel,marginBottom:24}}/>
        <div style={{display:"grid",gridTemplateColumns:"repeat(4,minmax(0,1fr))",gap:10,marginBottom:20}}>
          {[0,1,2,3].map(item=><div key={item} style={{height:72,borderRadius:10,background:t.panel,border:`1px solid ${t.border}`}}/>)}
        </div>
        <div style={{display:"grid",gap:10}}>
          {[0,1,2].map(item=><div key={item} style={{height:78,borderRadius:10,background:t.panel,border:`1px solid ${t.border}`}}/>)}
        </div>
      </div>
    </div>
  );
}

function PBQBank({user,attempts,onStart,onUpgrade,onOpenWallet,onUnlockPbq,coinWallet,coinBusy=false,t,starred=[],onToggleStar,showQuestionCodes=false,pbqBank=PBQ_BANK,isLoading=false,loadError=null}) {
  const [chFilter,setChFilter]=useState("all");
  const [typeFilter,setTypeFilter]=useState("all");
  const [lockedQuestion,setLockedQuestion]=useState(null);
  const [showMissedOnly,setShowMissedOnly]=useState(false);
  const [starredView,setStarredView]=useState(false);
  const [visibleCount,setVisibleCount]=useState(12);
  const isPro=user.tier==="pro";
  const unlockedSet=useMemo(()=>new Set(coinWallet?.unlockedPbqIds||[]),[coinWallet?.unlockedPbqIds]);
  const coinBalance=Number(coinWallet?.balance||0);
  const bank=pbqBank?.length ? pbqBank : [];
  const starredSet=useMemo(()=>new Set(starred),[starred]);
  const attempted=new Set(attempts.filter(a=>a.pbq).map(a=>a.qid));
  const correct=new Set(attempts.filter(a=>a.pbq&&a.correct).map(a=>a.qid));
  const missedPbqIds=[...new Set(attempts.filter(a=>a.pbq&&!a.correct).map(a=>a.qid))];
  const starredPbqs=bank.filter(q=>starredSet.has(starKey("pbq",q.id)));

  const filtered=bank.filter(q=>{
    if(chFilter!=="all"&&q.ch!==chFilter)return false;
    if(typeFilter!=="all"&&q.type!==typeFilter)return false;
    if(showMissedOnly&&!missedPbqIds.includes(q.id))return false;
    return true;
  });
  const displayQuestions=[...filtered].sort((a,b)=>{
    if(!isPro){
      if(isFreePBQPreview(a)&&!isFreePBQPreview(b))return -1;
      if(!isFreePBQPreview(a)&&isFreePBQPreview(b))return 1;
    }
    const rank=q=>correct.has(q.id)?2:attempted.has(q.id)?0:1;
    return rank(a)-rank(b);
  });
  const visibleQuestions=displayQuestions.slice(0,visibleCount);
  useEffect(()=>setVisibleCount(12),[chFilter,showMissedOnly,typeFilter]);
  const openLockedPrompt=q=>{
    capture("pbq_locked_clicked", { question_id: q.id, type: q.type, chapter: q.ch });
    setLockedQuestion(q);
  };
  const practiceRandomPbq=()=>{
    const notDone=bank.filter(q=>!attempted.has(q.id));
    const missed=bank.filter(q=>missedPbqIds.includes(q.id));
    const rawPool=notDone.length?notDone:missed.length?missed:[bank[bank.length-1]].filter(Boolean);
    const regular=rawPool.filter(q=>!q.beyondTextbook);
    const beyond=rawPool.filter(q=>q.beyondTextbook);
    const pool=regular.length && beyond.length && Math.random()>.15 ? regular : rawPool;
    const picked=pool[Math.floor(Math.random()*pool.length)];
    if(!picked)return;
    capture("pbq_random_practice_started", { question_id: picked.id, pool: notDone.length?"new":missed.length?"missed":"newest", tier: user.tier });
    onStart(picked);
  };

  if(isLoading) return <PBQLoadingSkeleton t={t}/>;
  if(loadError || !bank.length) return <UpgradeModal onUpgrade={onUpgrade} t={t}/>;

  if(starredView) return(
    <div style={{padding:"24px",maxWidth:900,margin:"0 auto"}}>
      <div className="page-title-row" style={{marginBottom:12}}>
        <NavGlyph type="pbq" active/>
        <div>
          <h2 style={{fontSize:24,fontWeight:800,color:t.text}}>Starred PBQs</h2>
          <p style={{fontSize:13,color:t.textSec}}>Performance-based questions saved for another pass.</p>
        </div>
      </div>
      <button className="btn btn-ghost" style={{marginBottom:16}} onClick={()=>setStarredView(false)}>← Back to PBQ Bank</button>
      {starredPbqs.length?(
        <div style={{display:"grid",gap:10}}>
          {starredPbqs.map(q=>(
            <div key={q.id} className="card card-hover" style={{padding:"14px 18px",display:"flex",gap:12,alignItems:"flex-start",cursor:"pointer"}} onClick={()=>{if(isPro||isFreePBQPreview(q)||unlockedSet.has(q.id))onStart(q);else openLockedPrompt(q);}}>
              <StarButton active onToggle={()=>onToggleStar?.("pbq",q.id)} label="Unstar PBQ"/>
              <SimIcon type={q.type}/>
              <div style={{flex:1,minWidth:0}}>
                <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:8}}>
                  {!isPro&&isFreePBQPreview(q)&&<span className="chip" style={{background:`${t.amber}16`,color:t.amber,borderColor:`${t.amber}40`}}>Preview</span>}
                  {!isPro&&unlockedSet.has(q.id)&&<span className="chip cipher-unlocked-chip"><CipherCoinIcon size={19}/> Coin unlocked</span>}
                  {showQuestionCodes&&<QuestionCodeChip id={q.id} t={t}/>}
                  <SimBadge type={q.type} t={t}/>
                  <DiffBadge d={q.difficulty} t={t}/>
                  <BeyondTextbookTag question={q} t={t}/>
                </div>
                <div style={{fontSize:14,fontWeight:800,color:t.text}}><GlossaryText text={q.title} t={t}/></div>
                <div style={{fontSize:12,color:t.textSec,marginTop:3}}><GlossaryText text={q.cat} t={t}/></div>
              </div>
            </div>
          ))}
        </div>
      ):(
        <div className="card" style={{padding:"20px 22px",color:t.textSec,fontSize:14,lineHeight:1.7}}>
          No starred PBQs yet. Press the star while doing a PBQ to save it here.
        </div>
      )}
    </div>
  );

  return(
    <div className="pbq-bank-screen fu" style={{padding:"24px",maxWidth:900,margin:"0 auto"}}>
      <header className="practice-page-head">
        <div className="practice-page-heading">
          <div className="practice-page-icon"><Puzzle size={23} strokeWidth={2.3}/></div>
          <div>
            <div className="label" style={{color:t.green}}>Applied practice</div>
            <h2>PBQ Simulator</h2>
            <p>Practise the decisions, tools, and workflows behind exam scenarios.</p>
          </div>
        </div>
        <div className="practice-page-meta">
          <span className="practice-meta-pill"><strong>{bank.length}</strong> PBQs</span>
          <span className="practice-meta-pill"><strong>{Object.keys(SIM_TYPES).length}</strong> formats</span>
          <span className="practice-meta-pill">{isPro?"Pro · zero coins":`${unlockedSet.size} coin unlock${unlockedSet.size===1?"":"s"}`}</span>
        </div>
      </header>
      <div style={{marginBottom:16}}>
        <TrustBadge t={t}/>
      </div>

      <MascotGuide
        animation="scan"
        size={84}
        context="pbq-bank"
        message="I’m scanning the PBQ formats for your next challenge."
        className="mascot-guide-page"
        side="left"
      />

      <section className="pbq-bank-hero">
        <div className="pbq-bank-hero-copy">
          <div>
            <div className="label" style={{color:t.green}}>Your PBQ workspace</div>
            <h3>Choose a format, then practise one complete scenario.</h3>
            <p>Use the filters below to focus on a simulation type or exam chapter. Attempted questions stay visible, with missed work prioritised for review.</p>
          </div>
          {isPro&&<button className="btn btn-primary" onClick={practiceRandomPbq}><Sparkles size={16}/> Start a recommended PBQ</button>}
        </div>
        <div className="pbq-metric-grid">
          {[
            {label:"Total PBQs",value:bank.length,color:t.accent},
            {label:"Simulation types",value:Object.keys(SIM_TYPES).length,color:t.text},
            {label:"Attempted",value:attempted.size,color:t.amber},
            {label:"Correct",value:correct.size,color:t.green},
          ].map(s=>(
            <div key={s.label} className="pbq-metric-card" style={{"--metric-color":s.color}}>
              <strong>{s.value}</strong><span>{s.label}</span>
            </div>
          ))}
        </div>
      </section>

      {!isPro&&(
        <div className="card" style={{padding:"18px 22px",marginBottom:20,borderColor:`${t.amber}40`,background:`${t.amber}06`}}>
          <div style={{display:"flex",gap:12,alignItems:"center",flexWrap:"wrap"}}>
            <div style={{flex:1}}>
              <div style={{fontWeight:800,fontSize:16,color:t.text,marginBottom:4}}>Use 50 coins or unlock all PBQs with Pro</div>
              <div style={{fontSize:13,color:t.textSec,lineHeight:1.65}}>
                Free users can try the marked preview and reveal a permanent mystery PBQ for <strong>{CIPHER_COIN_COSTS.pbq} Cipher Coins</strong>. Your first three reveals are p014, p018, and p033; later reveals are random. Pro includes every PBQ with zero coin requirements.
              </div>
            </div>
            <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
              <button className="btn btn-outline" style={{flexShrink:0}} onClick={onOpenWallet}><CipherCoinIcon size={23}/> {coinBalance} coins</button>
              <button className="btn btn-primary" style={{flexShrink:0}} onClick={()=>{capture("upgrade_prompt_clicked", { source: "pbq_access_banner", tier: user.tier });onUpgrade();}}>Unlock all PBQs with Pro →</button>
            </div>
          </div>
        </div>
      )}

      {!isPro&&lockedQuestion&&(
        <div className="card" style={{padding:"18px 22px",marginBottom:20,borderColor:`${t.accent}40`,background:`${t.accent}08`}}>
          <div style={{display:"flex",gap:12,alignItems:"flex-start",flexWrap:"wrap"}}>
            <span className="section-icon" style={{"--section-color":t.accent}}><LockKeyhole size={21} strokeWidth={2.2}/></span>
            <div style={{flex:1,minWidth:220}}>
              <div style={{fontWeight:800,fontSize:16,color:t.text,marginBottom:4}}>Use 50 coins or unlock all PBQs with Pro</div>
              <div style={{fontSize:13,color:t.textSec,lineHeight:1.65}}>
                Spend {CIPHER_COIN_COSTS.pbq} Cipher Coins to reveal one mystery PBQ permanently. The reveal may be a different question from {lockedQuestion.title}. Pro opens the complete bank with zero coin requirements.
              </div>
            </div>
            <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
              <button className="btn btn-primary" style={{fontSize:13}} disabled={coinBusy||coinBalance<CIPHER_COIN_COSTS.pbq} onClick={async()=>{const unlocked=await onUnlockPbq?.();if(unlocked?.purchased||unlocked?.alreadyOwned)setLockedQuestion(null);}}><CipherCoinIcon size={22}/> {coinBalance<CIPHER_COIN_COSTS.pbq?`${CIPHER_COIN_COSTS.pbq-coinBalance} more needed`:`Use ${CIPHER_COIN_COSTS.pbq} coins`}</button>
              {coinBalance<CIPHER_COIN_COSTS.pbq&&<button className="btn btn-outline" style={{fontSize:13}} onClick={onOpenWallet}>How to earn</button>}
              <button className="btn btn-outline" style={{fontSize:13}} onClick={()=>{capture("upgrade_prompt_clicked", { source: "locked_pbq_prompt", question_id: lockedQuestion.id, tier: user.tier });onUpgrade();}}>Unlock all PBQs with Pro</button>
              <button className="btn btn-ghost" style={{fontSize:13}} onClick={()=>setLockedQuestion(null)}>Not now</button>
            </div>
          </div>
        </div>
      )}
      {isPro&&(
        <div className="pbq-filter-panel">
          <div>
            <div style={{fontWeight:900,fontSize:13,color:t.text}}>Review shortcuts</div>
            <div style={{fontSize:11,color:t.textDim}}>Jump back into questions that need attention.</div>
          </div>
          <div style={{display:"flex",gap:8,flexWrap:"wrap",justifyContent:"flex-end"}}>
            <button className={`btn ${showMissedOnly?"btn-primary":"btn-outline"}`} style={{fontSize:12,flexShrink:0}} disabled={missedPbqIds.length===0} onClick={()=>setShowMissedOnly(v=>!v)}>
              {showMissedOnly?"Show all PBQs":`Missed (${missedPbqIds.length})`}
            </button>
            <button className="btn btn-outline" style={{fontSize:12,flexShrink:0}} onClick={()=>setStarredView(true)}>
              <Star size={14}/> Starred ({starredPbqs.length})
            </button>
          </div>
        </div>
      )}

      {/* Sim type cards */}
      <section className="pbq-type-section">
        <div className="pbq-type-section-head"><h3>Choose a simulation format</h3><span>{typeFilter==="all"?"All formats selected":Object.values(SIM_TYPES).find(item=>item.id===typeFilter)?.label}</span></div>
        <div className="pbq-type-grid">
          {Object.values(SIM_TYPES).map(s=>{
            const count=bank.filter(q=>q.type===s.id).length;
            const active=typeFilter===s.id;
            return(
              <button type="button" key={s.id} className={`pbq-type-card ${active?"active":""}`} style={{"--type-color":s.color}} aria-pressed={active} onClick={()=>setTypeFilter(active?"all":s.id)}>
                <SimIcon type={s.id}/>
                <span><strong>{s.label}</strong><small>{count} question{count!==1?"s":""}</small></span>
              </button>
            );
          })}
        </div>
      </section>

      {/* Filters */}
      <div className="pbq-filter-panel">
        <div className="pbq-chapter-filters" aria-label="Filter PBQs by chapter">
          {CHAPTERS.map(ch=>(
            <button key={ch.id} className="btn" style={{fontSize:13,padding:"7px 14px",background:chFilter===ch.id?`${t.accent}15`:"transparent",color:chFilter===ch.id?t.accent:t.textSec,border:`1px solid ${chFilter===ch.id?t.accent:t.border}`,transition:"all .15s"}} aria-pressed={chFilter===ch.id} onClick={()=>setChFilter(chFilter===ch.id?"all":ch.id)}>
              <ChapterIcon id={ch.id} size={18}/> Ch.{ch.id}
            </button>
          ))}
          {(chFilter!=="all"||typeFilter!=="all"||showMissedOnly)&&<button className="btn btn-ghost" style={{fontSize:13,padding:"7px 12px"}} onClick={()=>{setChFilter("all");setTypeFilter("all");setShowMissedOnly(false);}}><X size={14}/> Clear all</button>}
        </div>
        <div className="pbq-result-summary">Showing {Math.min(visibleQuestions.length,displayQuestions.length)} of {displayQuestions.length}</div>
      </div>

      {/* Question list */}
      <div className="pbq-question-list">
        {visibleQuestions.map(q=>{
          const done=attempted.has(q.id);
          const ok=correct.has(q.id);
          const preview=isFreePBQPreview(q);
          const coinUnlocked=unlockedSet.has(q.id);
          const canOpen=isPro||preview||coinUnlocked;
          const ch=CHAPTERS.find(c=>c.id===q.ch);
          return(
            <div
              key={q.id}
              className="card card-hover pbq-list-card"
              role="button"
              tabIndex={0}
              aria-label={`${canOpen?"Open":"Locked"} PBQ: ${q.title}`}
              style={{opacity:canOpen?1:.75,borderColor:preview?`${t.amber}55`:ok?`${t.green}30`:done?`${t.red}25`:undefined,background:preview&&!isPro?`linear-gradient(135deg, ${t.amber}0d, ${t.surface})`:undefined}}
              onKeyDown={event=>{if(event.key!=="Enter"&&event.key!==" ")return;event.preventDefault();if(canOpen){capture(preview&&!isPro?"pbq_preview_started":"pbq_started", { question_id:q.id,type:q.type,chapter:q.ch,tier:user.tier });onStart(q);}else openLockedPrompt(q);}}
              onClick={()=>{if(canOpen){capture(preview&&!isPro?"pbq_preview_started":"pbq_started", { question_id: q.id, type: q.type, chapter: q.ch, tier: user.tier });onStart(q);}else{openLockedPrompt(q);}}}
            >
              <SimIcon type={q.type}/>
              <div style={{flex:1,minWidth:0}}>
                <div style={{display:"flex",gap:8,marginBottom:5,flexWrap:"wrap"}}>
                  {preview&&!isPro&&<span className="chip" style={{background:`${t.amber}16`,color:t.amber,borderColor:`${t.amber}40`}}>Preview</span>}
                  {!isPro&&coinUnlocked&&<span className="chip cipher-unlocked-chip"><CipherCoinIcon size={19}/> Coin unlocked</span>}
                  {!canOpen&&<span className="chip cipher-locked-cost"><CipherCoinIcon size={19}/>{CIPHER_COIN_COSTS.pbq}</span>}
                  {showQuestionCodes&&<QuestionCodeChip id={q.id} t={t}/>}
                  <SimBadge type={q.type} t={t}/>
                  <DiffBadge d={q.difficulty} t={t}/>
                  <BeyondTextbookTag question={q} t={t}/>
                  {ch&&<span style={{fontSize:13,fontWeight:800,color:t.textDim,display:"inline-flex",alignItems:"center",gap:5}}><ChapterIcon id={ch.id} size={16}/> Ch.{ch.id}</span>}
                </div>
                <div className="pbq-list-title"><GlossaryText text={q.title} t={t}/></div>
                <div className="pbq-list-subtitle"><GlossaryText text={q.cat} t={t}/>{done?` · ${ok?"Completed correctly":"Needs another pass"}`:" · Not attempted"}</div>
              </div>
              <div className="pbq-list-actions">
                <StarButton active={starredSet.has(starKey("pbq",q.id))} onToggle={()=>onToggleStar?.("pbq",q.id)} label="Star PBQ"/>
                <span aria-label={done?(ok?"Completed correctly":"Answered incorrectly"):"Not attempted"}>{done?ok?<CheckCircle2 size={18} color={t.green} strokeWidth={2.4}/>:<XCircle size={18} color={t.red} strokeWidth={2.4}/>:<Circle size={17} color={t.textDim} strokeWidth={1.8}/>}</span>
                <span className={`pbq-open-indicator ${canOpen?"":"locked"}`}>{canOpen?<Play size={16} fill="currentColor" strokeWidth={2}/>:<LockKeyhole size={16} strokeWidth={2.2}/>}</span>
              </div>
            </div>
          );
        })}
        {displayQuestions.length===0&&(
          <div className="card" style={{padding:"26px",textAlign:"center",color:t.textSec}}>
            <div style={{fontWeight:900,color:t.text,marginBottom:5}}>No PBQs match these filters</div>
            <div style={{fontSize:12,marginBottom:14}}>Clear the filters to return to the full simulator bank.</div>
            <button className="btn btn-outline" onClick={()=>{setChFilter("all");setTypeFilter("all");setShowMissedOnly(false);}}>Clear filters</button>
          </div>
        )}
        {visibleQuestions.length<displayQuestions.length&&(
          <div className="pbq-load-more">
            <button className="btn btn-outline" type="button" onClick={()=>setVisibleCount(count=>Math.min(count+12,displayQuestions.length))}>
              Show 12 more <ChevronDown size={16}/>
            </button>
            <span>{displayQuestions.length-visibleQuestions.length} remaining</span>
          </div>
        )}
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// PBQ SIMULATOR
// ═══════════════════════════════════════════════════════════════
function PBQSim({q,onDone,onNext,nextQuestion,t,starred=[],onToggleStar,previewMode=false,onUpgrade,onOpenWallet,isGuest=false,onReportQuestion,showQuestionCodes=false}) {
  const evidence=q?.payload?.evidence || {};
  const [termInput,setTermInput]=useState("");
  const [termHistory,setTermHistory]=useState([]);
  const [selected,setSelected]=useState(null);
  const [submitted,setSubmitted]=useState(false);
  const [orderItems,setOrderItems]=useState(()=>q.items?[...q.items].sort(()=>Math.random()-.5):[]);
  const [blanks,setBlanks]=useState(()=>q.blanks?Object.fromEntries(q.blanks.map(b=>[b.id,""])):{});
  const [showHint,setShowHint]=useState(false);
  const [answerBurst,setAnswerBurst]=useState(null);
  const starredSet=useMemo(()=>new Set(starred),[starred]);

  const isCorrect=()=>{
    if(["TERMINAL SIM","HOTSPOT","LOG ANALYSIS","CONFIG/ACL","SCENARIO"].includes(q.type))return selected===q.correct;
    if(q.type==="ORDERING")return q.correctOrder?.every((id,i)=>orderItems[i]?.id===id);
    if(q.type===SELECT_FILL_PBQ_TYPE)return q.blanks?.every(b=>isFillBlankAnswerCorrect(blanks[b.id],b));
    return false;
  };
  const partResults=useMemo(()=>{
    if(q.type===SELECT_FILL_PBQ_TYPE) {
      return (q.blanks||[]).map((blank,index)=>({
        id:blank.id||index,
        label:`Blank ${index+1}`,
        prompt:blank.sentence,
        userAnswer:blanks[blank.id]||"",
        correctAnswer:blank.answer,
        solution:blank.explanation||blank.solution||"",
        correct:isFillBlankAnswerCorrect(blanks[blank.id],blank),
      }));
    }
    if(q.type==="ORDERING") {
      return (q.correctOrder||[]).map((expectedId,index)=>{
        const expectedItem=q.items?.find(item=>item.id===expectedId);
        const userItem=orderItems[index];
        return {
          id:expectedId,
          label:`Position ${index+1}`,
          userAnswer:userItem?.label||"No item",
          correctAnswer:expectedItem?.label||"Unknown",
          correct:userItem?.id===expectedId,
        };
      });
    }
    if(q.choices||q.options) {
      return [{
        id:"choice",
        label:"Selected answer",
        userAnswer:selected!==null&&selected!==undefined?`${String.fromCharCode(65+selected)}. ${(q.choices||q.options||[])[selected]}`:"Not answered",
        correctAnswer:`${String.fromCharCode(65+q.correct)}. ${(q.choices||q.options||[])[q.correct]}`,
        correct:selected===q.correct,
      }];
    }
    return [];
  },[q,blanks,orderItems,selected]);
  const partCorrectCount=partResults.filter(part=>part.correct).length;
  const pbqChoices=q.choices||q.options||[];
  const selectedOptionFeedback=selected!==null&&selected!==undefined
    ? q.optionFeedback?.[selected] || (selected===q.correct ? ensureFeedbackLead(q.explanation||"",true) : q.wrongFeedback?.[selected] ? ensureFeedbackLead(q.wrongFeedback[selected],false) : "")
    : "";

  const submit=()=>{
    const correct = isCorrect();
    capture("pbq_question_answered", { question_id: q.id, type: q.type, chapter: q.ch, correct, part_correct_count: partCorrectCount, part_count: partResults.length });
    playAnswerSound(correct);
    setAnswerBurst({correct,key:Date.now()});
    setTimeout(()=>setAnswerBurst(null),1700);
    setSubmitted(true);
  };

  const runTerminal=()=>{
    const cmd=termInput.trim();
    if(!cmd)return;
    setTermHistory(h=>[...h,{type:"cmd",text:cmd}]);
    const keywords=["scan","nmap","hash","sha","list","process","connect","netstat","ls","chmod","cat","grep","show","check","run","get","find","read"];
    if(keywords.some(k=>cmd.toLowerCase().includes(k))){
      setTermHistory(h=>[...h,{type:"output",text:q.answer||"Command executed."}]);
    } else {
      setTermHistory(h=>[...h,{type:"error",text:`Command not recognised. Hint: ${q.hint||"Try a relevant command."}`}]);
    }
    setTermInput("");
  };

  const simType=Object.values(SIM_TYPES).find(s=>s.id===q.type)||SIM_TYPES.TERMINAL;
  const canSubmit=q.type===SELECT_FILL_PBQ_TYPE
      ? Boolean(q.blanks?.length)&&q.blanks.every(blank=>String(blanks[blank.id]||"").trim())
      : q.type==="ORDERING"
        ? Boolean(orderItems.length)
        : selected!==null;

  return(
    <div className="pbq-question-screen fu active-practice-screen" style={{padding:"24px",maxWidth:860,margin:"0 auto"}}>
      {/* Header */}
      <header className="pbq-session-header">
        <button className="btn btn-ghost" style={{fontSize:12}} onClick={()=>onDone(null)}>← Back to PBQ Bank</button>
        <div className="pbq-session-title">
          <strong><GlossaryText text={q.title} t={t}/></strong>
          <div className="pbq-session-meta">
            {showQuestionCodes&&<QuestionCodeChip id={q.id} t={t}/>}
            <SimBadge type={q.type} t={t}/>
            <DiffBadge d={q.difficulty} t={t}/>
            <BeyondTextbookTag question={q} t={t}/>
          </div>
          <div style={{marginTop:8}}>
            <TrustBadge t={t} compact/>
          </div>
        </div>
        <StarButton active={starredSet.has(starKey("pbq",q.id))} onToggle={()=>onToggleStar?.("pbq",q.id)} label="Star PBQ"/>
      </header>

      {/* Scenario */}
      <div className="card question-card pbq-scenario-card" style={{"--sim-color":simType.color}}>
        <div className="pbq-scenario-label"><span><FileText size={14}/></span>Read the scenario</div>
        <div className="scenario-text" style={{fontSize:14,color:t.textSec,lineHeight:1.62}}>
          <PBQProseText text={q.scenario} t={t} paragraphGap={6}/>
        </div>
        {q.steps&&<div className="pbq-step-list" style={{"--sim-color":simType.color}}>
          {q.steps.map((s,i)=><div key={i} className="pbq-step-row"><span>{i+1}</span><div>{s}</div></div>)}
        </div>}
      </div>
      <PBQEvidenceViewer title="Code or configuration evidence" content={q?.codeBlock || evidence?.codeBlock} language={q?.codeLanguage || evidence?.codeLanguage} t={t} accent={simType.color}/>

      {/* TERMINAL */}
      {q.type==="TERMINAL SIM"&&(
        <section className="pbq-workspace-section">
          <div className="pbq-workspace-head"><div><h3>Terminal workspace</h3><p>Run a relevant command, review the output, then choose your answer.</p></div><SquareTerminal size={20} color={simType.color}/></div>
          <div className="terminal" style={{minHeight:160}}>
            {termHistory.length===0&&<div style={{color:t.codeMuted}}>Type a command and press Enter. {q.hint}</div>}
            {termHistory.map((h,i)=>(
              <div key={i} style={{color:h.type==="cmd"?t.codeCommand:h.type==="error"?t.codeError:t.codeText}}>
                {h.type==="cmd"&&<span style={{color:t.codePrompt,marginRight:8}}>$</span>}
                {h.text}
              </div>
            ))}
          </div>
          <div style={{display:"flex",gap:8,marginTop:8}}>
            <input className="input" value={termInput} onChange={e=>setTermInput(e.target.value)} onKeyDown={e=>e.key==="Enter"&&runTerminal()} placeholder="Enter command..." style={{fontFamily:"'JetBrains Mono',monospace",fontSize:13}}/>
            <button className="btn btn-outline" style={{fontSize:12,flexShrink:0}} onClick={runTerminal}>Run</button>
          </div>
          <button className="btn btn-ghost" style={{fontSize:11,marginTop:8}} onClick={()=>setShowHint(!showHint)}>
            {showHint?"Hide hint":"Show hint"}
          </button>
          {showHint&&<div style={{fontSize:12,color:t.textDim,marginTop:6,padding:"8px 12px",background:t.panel,borderRadius:6}}>{q.hint}</div>}
        </section>
      )}

      {/* LOG ANALYSIS */}
      {q.type==="LOG ANALYSIS"&&(
        <section className="pbq-workspace-section">
          <div className="pbq-workspace-head"><div><h3>Log evidence</h3><p>Inspect the events before choosing the strongest conclusion.</p></div><ListOrdered size={20} color={simType.color}/></div>
          <PBQEvidenceViewer title="Log evidence" content={q?.logData || evidence?.logData} t={t} accent={simType.color}/>
        </section>
      )}

      {/* CONFIG/ACL */}
      {q.type==="CONFIG/ACL"&&(
        <section className="pbq-workspace-section">
          <div className="pbq-workspace-head"><div><h3>Configuration review</h3><p>This configuration contains an issue. Find the best correction.</p></div><MonitorCog size={20} color={simType.color}/></div>
          <PBQEvidenceViewer title="Current configuration" content={q?.currentConfig || evidence?.currentConfig} t={t} accent={simType.color}/>
        </section>
      )}

      {/* HOTSPOT */}
      {q.type==="HOTSPOT"&&(
        <section className="pbq-workspace-section">
          <div className="pbq-workspace-head"><div><h3>Scenario map</h3><p>Review each detail before selecting the best response.</p></div><Crosshair size={20} color={simType.color}/></div>
          <PBQEvidenceViewer title="Network diagram" content={q?.diagram || evidence?.diagram} t={t} accent={simType.color}/>
        </section>
      )}

      {/* SELECT & FILL */}
      {q.type===SELECT_FILL_PBQ_TYPE&&!submitted&&(
        <section className="pbq-workspace-section">
          <div className="pbq-workspace-head">
            <div>
              <h3>Select an answer for each blank</h3>
              <p>Tap a blank, choose an option, and reuse options whenever the scenario requires it.</p>
            </div>
            <ListChecks size={20} color={simType.color}/>
          </div>
          <PBQSelectionWorkspace
            q={q}
            values={blanks}
            onChange={(blankId,value)=>setBlanks(current=>({...current,[blankId]:value}))}
            t={t}
            accent={simType.color}
          />
        </section>
      )}

      {/* ORDERING */}
      {q.type==="ORDERING"&&!submitted&&(
        <section className="pbq-workspace-section">
          <div className="pbq-workspace-head"><div><h3>Put the steps in order</h3><p>Drag each answer into the correct top-to-bottom sequence. Touch is supported.</p></div><ListOrdered size={20} color={simType.color}/></div>
          <SortableOrderList items={orderItems} onChange={setOrderItems} t={t}/>
        </section>
      )}

      {/* MCQ for most types */}
      {(q.choices||q.options)&&(
        <section className="pbq-workspace-section">
          <div className="pbq-workspace-head"><div><h3>Make your decision</h3><p>Select the strongest response based on the scenario and evidence above.</p></div><Target size={20} color={simType.color}/></div>
          <div className="question-prompt" style={{fontSize:13,color:t.text,marginBottom:10}}><QuestionStemText text={q.question||"Select the best answer:"} t={t} compact/></div>
          <div style={{display:"flex",flexDirection:"column",gap:9}}>
            {(q.choices||q.options||[]).map((choice,i)=>{
              let cls="opt";
              if(submitted){cls+=" done"; if(i===q.correct)cls+=" ok"; else if(i===selected&&i!==q.correct)cls+=" bad";}
              else if(selected===i)cls+=" sel";
              return(
                <button type="button" key={i} className={cls} disabled={submitted} aria-pressed={!submitted&&selected===i} onClick={()=>!submitted&&setSelected(i)}>
                  <div className="opt-ltr">{String.fromCharCode(65+i)}</div>
                  <span className="option-text" style={{fontSize:14,flex:1,lineHeight:1.55,color:t.text}}><GlossaryText text={choice} t={t}/></span>
                  {submitted&&i===q.correct&&<Check size={18} color={t.green} strokeWidth={2.8}/>}
                  {submitted&&i===selected&&i!==q.correct&&<X size={18} color={t.red} strokeWidth={2.8}/>}
                </button>
              );
            })}
          </div>
        </section>
      )}

      {/* Submit / feedback */}
      {!submitted?(
        <div className="practice-action-bar" style={{justifyContent:"flex-end"}}>
          <div className="practice-action-copy"><strong>{canSubmit?"Ready to check":"Complete the activity first"}</strong>{canSubmit?"SecurePlus will mark each part and explain the result.":q.type===SELECT_FILL_PBQ_TYPE?"Choose an answer for every blank before submitting.":"Choose an answer before submitting."}</div>
          <button className="btn btn-primary" style={{minWidth:190}} disabled={!canSubmit} onClick={submit}>
            Check my PBQ →
          </button>
        </div>
      ):(
        <>
          <div className="card answer-feedback" style={{padding:"18px 22px",marginBottom:14,borderColor:isCorrect()?t.green:t.red}}>
            <div style={{display:"flex",alignItems:"center",gap:8,fontWeight:700,fontSize:16,color:isCorrect()?t.green:t.red,marginBottom:10}}>
              {isCorrect()?<CheckCircle2 size={19}/>:<XCircle size={19}/>} {isCorrect()?"Correct":"Incorrect"}
            </div>
            <div style={{fontSize:13,color:t.textSec,lineHeight:1.62}}>
              <PBQProseText text={q.explanation} t={t} paragraphGap={6}/>
            </div>
            {selectedOptionFeedback&&(
              <div style={{marginTop:12,padding:"12px 14px",background:`${isCorrect()?t.green:t.red}08`,borderRadius:9,border:`1px solid ${isCorrect()?t.green:t.red}30`}}>
                <div style={{fontSize:12,fontWeight:900,color:isCorrect()?t.green:t.red,marginBottom:5}}>
                  Why option {String.fromCharCode(65+selected)} is {isCorrect()?"correct":"wrong"}
                </div>
                <div style={{fontSize:13,color:t.textSec,lineHeight:1.65}}><PBQProseText text={selectedOptionFeedback} t={t} paragraphGap={5}/></div>
              </div>
            )}
            {pbqChoices.length>0&&(
              <div style={{marginTop:12,padding:"12px 14px",background:t.panel,borderRadius:10,border:`1px solid ${t.border}`}}>
                <div style={{fontSize:12,fontWeight:950,color:t.text,marginBottom:8}}>Review every option</div>
                <div style={{display:"grid",gap:8}}>
                  {pbqChoices.map((choice,index)=>{
                    const optionCorrect=index===q.correct;
                    const feedback=q.optionFeedback?.[index] || (optionCorrect ? ensureFeedbackLead(q.explanation||"",true) : q.wrongFeedback?.[index] ? ensureFeedbackLead(q.wrongFeedback[index],false) : buildPbqOptionFeedback(q,index,choice,q.correct));
                    return(
                      <div key={index} style={{padding:"10px 12px",borderRadius:9,border:`1px solid ${optionCorrect?t.green:t.border}35`,background:optionCorrect?`${t.green}08`:t.surface}}>
                        <div style={{display:"flex",gap:8,alignItems:"flex-start",fontSize:13,lineHeight:1.5}}>
                          <strong style={{color:optionCorrect?t.green:t.text}}>{String.fromCharCode(65+index)}. {optionCorrect?"Correct.":"Incorrect."}</strong>
                          <span style={{color:t.text}}><GlossaryText text={choice} t={t}/></span>
                        </div>
                        <div style={{fontSize:12,color:t.textSec,lineHeight:1.6,marginTop:5}}><PBQProseText text={feedback} t={t} paragraphGap={5}/></div>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
            {(q.type===SELECT_FILL_PBQ_TYPE||partResults.length>1)&&(
              <div style={{marginTop:12,padding:"12px 14px",background:t.panel,borderRadius:8,border:`1px solid ${t.border}`}}>
                <div style={{display:"flex",justifyContent:"space-between",gap:10,alignItems:"center",marginBottom:8,flexWrap:"wrap"}}>
                  <div style={{fontSize:12,fontWeight:900,color:t.text}}>Part-by-part marking</div>
                  <span className="chip" style={{background:`${partCorrectCount===partResults.length?t.green:t.amber}12`,borderColor:`${partCorrectCount===partResults.length?t.green:t.amber}35`,color:partCorrectCount===partResults.length?t.green:t.amber}}>
                    {partCorrectCount}/{partResults.length} parts correct
                  </span>
                </div>
                <div style={{display:"grid",gap:8}}>
                  {partResults.map(part=>(
                    <div key={part.id} style={{padding:"10px 12px",borderRadius:8,border:`1px solid ${part.correct?t.green:t.red}35`,background:`${part.correct?t.green:t.red}08`}}>
                      <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:4,flexWrap:"wrap"}}>
                        <span style={{fontSize:13,fontWeight:900,color:part.correct?t.green:t.red}}>{part.correct?"Correct":"Incorrect"}</span>
                        <span style={{fontSize:12,fontWeight:800,color:t.text}}>{part.label}</span>
                      </div>
                      {part.prompt&&<div style={{fontSize:12,color:t.textSec,lineHeight:1.5,marginBottom:5}}><PBQProseText text={part.prompt} t={t} paragraphGap={5}/></div>}
                      <div style={{fontSize:12,color:t.textSec,lineHeight:1.55}}>
                        Your answer: <strong style={{color:t.text}}>{part.userAnswer||"Blank"}</strong>
                      </div>
                      {!part.correct&&(
                        <div style={{fontSize:12,color:t.textSec,lineHeight:1.55}}>
                          Correct answer: <strong style={{color:t.green}}>{part.correctAnswer}</strong>
                        </div>
                      )}
                      {part.solution&&(
                        <div style={{fontSize:13,color:t.text,lineHeight:1.65,marginTop:8,padding:"10px 12px",borderRadius:8,background:`linear-gradient(135deg, ${t.green}18, ${t.surface})`,border:`1px solid ${t.green}55`,boxShadow:`0 0 0 3px ${t.green}10, 0 12px 24px ${t.green}12`}}>
                          <strong style={{color:t.green}}>Part solution: </strong><GlossaryText text={part.solution} t={t}/>
                        </div>
                      )}
                    </div>
                  ))}
                </div>
              </div>
            )}
            {/* Show correct drag order / blanks */}
            {q.type==="ORDERING"&&!isCorrect()&&(
              <div style={{marginTop:12}}>
                <div style={{fontSize:12,fontWeight:600,color:t.accent,marginBottom:6}}>Correct order:</div>
                {q.correctOrder?.map((id,i)=>{
                  const item=q.items.find(x=>x.id===id);
                  return<div key={id} style={{fontSize:12,color:t.textSec,padding:"3px 0"}}><span style={{color:t.accent,marginRight:8}}>{i+1}.</span>{item?.label}</div>;
                })}
              </div>
            )}
            {onReportQuestion&&<div style={{display:"flex",justifyContent:"flex-end",marginTop:12}}>
              <button
                className="btn btn-ghost"
                style={{fontSize:12,minHeight:34,padding:"7px 10px"}}
                onClick={()=>onReportQuestion?.({kind:"pbq",question:q,selected,correct:q.correct})}
              >
                Report question
              </button>
            </div>}
          </div>
          {previewMode&&(
            <div className="card" style={{padding:"18px 22px",marginBottom:14,borderColor:`${t.amber}45`,background:`linear-gradient(135deg, ${t.amber}10, ${t.surface})`}}>
              <div style={{display:"flex",gap:12,alignItems:"flex-start",flexWrap:"wrap"}}>
                <span className="mission-badge" style={{background:t.amber}}>P</span>
                <div style={{flex:1,minWidth:220}}>
                  <div style={{fontWeight:900,fontSize:16,color:t.text,marginBottom:4}}>That was your free PBQ preview</div>
                  <div style={{fontSize:13,color:t.textSec,lineHeight:1.65}}>
                    {isGuest
                      ? "Create a free account, then use 50 Cipher Coins for a permanent PBQ reveal or unlock the complete bank with Pro."
                      : `Use ${CIPHER_COIN_COSTS.pbq} Cipher Coins for a permanent PBQ reveal, or unlock every PBQ with the ${PRO_ACADEMY_PASS_NAME}.`}
                  </div>
                </div>
                <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
                  <button className="btn btn-outline" style={{fontSize:13,flexShrink:0}} onClick={()=>{capture("coin_prompt_clicked", { source:"pbq_preview_complete", question_id:q.id, tier:isGuest?"guest":"free" });onOpenWallet?.();}}>
                    {isGuest?"Create account to use 50 coins":`Use ${CIPHER_COIN_COSTS.pbq} coins`}
                  </button>
                  <button className="btn btn-primary" style={{fontSize:13,flexShrink:0}} onClick={()=>{capture("upgrade_prompt_clicked", { source: "pbq_preview_complete", question_id: q.id });onUpgrade?.();}}>
                    {isGuest?"Create account for Pro":"Unlock all PBQs with Pro"}
                  </button>
                </div>
              </div>
            </div>
          )}
          <div className="practice-action-bar" style={{justifyContent:"flex-end",flexWrap:"wrap"}}>
            <AnswerBurst result={answerBurst} t={t}/>
            <button className="btn btn-ghost" onClick={()=>{setSubmitted(false);setSelected(null);setTermHistory([]);setOrderItems(q.items?[...q.items].sort(()=>Math.random()-.5):[]);setBlanks(q.blanks?Object.fromEntries(q.blanks.map(b=>[b.id,""])):{})}}>
              Try Again
            </button>
            <button className="btn btn-primary" onClick={()=>onDone({qid:q.id,correct:isCorrect(),score:partResults.length?partCorrectCount/partResults.length:undefined,partCorrectCount,partCount:partResults.length,type:q.type,title:q.title,ch:q.ch,domain:q.cat,pbq:true})}>
              Back to PBQ Bank
            </button>
            {nextQuestion&&(
              <button className="btn btn-primary" onClick={()=>onNext({qid:q.id,correct:isCorrect(),score:partResults.length?partCorrectCount/partResults.length:undefined,partCorrectCount,partCount:partResults.length,type:q.type,title:q.title,ch:q.ch,domain:q.cat,pbq:true})}>
                Try a different PBQ →
              </button>
            )}
          </div>
        </>
      )}
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// EXAM MODE
// ═══════════════════════════════════════════════════════════════
function ExamModeGuideModal({t,onClose}) {
  const [step,setStep]=useState(0);
  const slides=[
    {
      label:"Setup",
      title:"Build your exam before you start",
      body:"Choose 10 to 50 total questions, then use the split bar to decide how many PBQs and MCQs you want. PBQs appear first, just like a focused exam warm-up.",
      bullets:["Slide toward PBQ for simulation-heavy practice.","Slide toward MCQ for faster knowledge checks.","Timer length scales with total question count."],
    },
    {
      label:"During",
      title:"Use exam tools while answering",
      body:"The timer, answer map, previous/next buttons, and flag button stay available while you work through the exam.",
      bullets:["Use the answer map to jump to any question.","Bold numbers are unanswered questions.","Amber outlines mean a question is flagged."],
    },
    {
      label:"Eliminate",
      title:"Cross out weak MCQ options",
      body:"For MCQs, right-click an option to cross it out. On mobile, long-press an option. This is useful when you narrow the answer down before choosing.",
      bullets:["Crossed-out options stay visible but faded.","Tap or click an option normally to select it.","Right-click or long-press again to undo the cross-out."],
    },
    {
      label:"Review",
      title:"Flag questions for final review",
      body:"Press Flag for review when you want to return later. A corner ribbon appears on the question so it is hard to miss.",
      bullets:["Submit warns you if anything is flagged or unanswered.","After submission, flagged questions remain marked in review.","Incorrect answers are bumped upward for easier review."],
    },
  ];
  const current=slides[step];
  const last=step===slides.length-1;

  return(
    <div className="onboarding-overlay" role="dialog" aria-modal="true" aria-label="Exam Mode guide">
      <div className="onboarding-modal card">
        <button className="btn btn-ghost" style={{position:"absolute",top:14,right:14,minHeight:32,padding:"4px 10px",fontSize:12}} onClick={onClose}>
          Skip
        </button>
        <div className="chip" style={{background:`${t.accent}12`,color:t.accent,borderColor:`${t.accent}35`,marginBottom:14}}>
          {current.label}
        </div>
        <h2 style={{fontSize:24,fontWeight:900,color:t.text,marginBottom:8}}>{current.title}</h2>
        <p style={{fontSize:14,color:t.textSec,lineHeight:1.7,marginBottom:18}}>{current.body}</p>
        <div style={{display:"flex",flexDirection:"column",gap:10,marginBottom:22}}>
          {current.bullets.map(item=>(
            <div key={item} style={{display:"flex",gap:10,alignItems:"flex-start",fontSize:13,color:t.textSec,lineHeight:1.6}}>
              <Check size={16} color={t.green} strokeWidth={2.6}/>
              <span>{item}</span>
            </div>
          ))}
        </div>
        <div style={{display:"flex",gap:7,marginBottom:20}}>
          {slides.map((_,i)=>(
            <div key={i} style={{height:7,flex:1,borderRadius:99,background:i<=step?t.accent:t.border}}/>
          ))}
        </div>
        <div style={{display:"flex",gap:10,justifyContent:"space-between",flexWrap:"wrap"}}>
          <button className="btn btn-ghost" onClick={()=>setStep(s=>Math.max(0,s-1))} disabled={step===0}>
            Back
          </button>
          <button className="btn btn-primary" onClick={()=>last?onClose():setStep(s=>s+1)}>
            {last ? "Got it" : "Next"}
          </button>
        </div>
      </div>
    </div>
  );
}

function ExamMode({user,attempts=[],onSave,onUpgrade,onOpenWallet,onConsumeExamPass,examPasses=0,t,showQuestionCodes=false,pbqBank=PBQ_BANK,mcqBank=MCQ_BANK,onSessionComplete,canPreviewDeepDives=false,onOpenDeepDives}) {
  const sessionKey=`exam:${practiceSessionOwner(user)}`;
  const [questionCount,setQuestionCount]=useState(20);
  const [pbqCount,setPbqCount]=useState(2);
  const [started,setStarted]=useState(false);
  const [done,setDone]=useState(false);
  const [questions,setQuestions]=useState([]);
  const [answers,setAnswers]=useState({});
  const [qi,setQi]=useState(0);
  const [flagged,setFlagged]=useState({});
  const [timeLeft,setTimeLeft]=useState(3600);
  const [timeSpent,setTimeSpent]=useState({});
  const [saved,setSaved]=useState(false);
  const [resumeAvailable,setResumeAvailable]=useState(false);
  const [expandedReview,setExpandedReview]=useState({});
  const [showExamGuide,setShowExamGuide]=useState(false);
  const [submittingExam,setSubmittingExam]=useState(false);
  const [showScoreDisclaimer,setShowScoreDisclaimer]=useState(false);
  const [completedRows,setCompletedRows]=useState([]);
  const [accessStarting,setAccessStarting]=useState(false);
  const longPressTimers=useRef({});
  const longPressActivated=useRef({});
  const rightClickHandled=useRef({});

  const isPro=user?.tier==="pro";
  const sizes=[10,20,30,40,50];
  const current=questions[qi];
  const answer=answers[qi]||{};
  const examDuration=questionCount*72;
  const mcqCount=Math.max(0,questionCount-pbqCount);
  const liveMcqs=mcqBank?.length ? mcqBank : MCQ_BANK;
  const pbqPercent=questionCount?Math.round((pbqCount/questionCount)*100):0;
  const mcqPercent=100-pbqPercent;
  const examGuideKey=`exam-guide-seen:${practiceSessionOwner(user)}`;

  const shuffle=arr=>[...arr].sort(()=>Math.random()-.5);
  const formatTime=s=>{
    const h=Math.floor(s/3600);
    const m=Math.floor((s%3600)/60);
    const sec=s%60;
    if(h>0) return `${h}:${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")}`;
    return `${String(m).padStart(2,"0")}:${String(sec).padStart(2,"0")}`;
  };
  const initAnswer=item=>{
    if(item.kind==="mcq") return {selected:null,eliminated:{}};
    const q=item.q;
    return {
      selected:null,
      orderItems:q.type==="ORDERING"&&q.items?shuffle(q.items):[],
      blanks:q.blanks?Object.fromEntries(q.blanks.map(b=>[b.id,""])):{},
      termInput:"",
    };
  };
  const updateQuestionCount=size=>{
    setQuestionCount(size);
    setPbqCount(prev=>Math.min(size,Math.max(0,Math.round(size*(prev/Math.max(1,questionCount))))));
  };
  const startExam=async()=>{
    if(!isPro){
      const confirmed=window.confirm("Start this practice exam now? One practice exam voucher will be used. Your voucher is not consumed if you cancel here.");
      if(!confirmed)return;
      setAccessStarting(true);
      try{
        const consumed=await onConsumeExamPass?.();
        if(!consumed)return;
      }finally{
        setAccessStarting(false);
      }
    }
    const examReadyPbqs=(pbqBank?.length?pbqBank:PBQ_BANK).filter(q=>!q.beyondTextbook&&(q.type!=="TERMINAL SIM"||q.choices||q.options));
    const pickedPbq=shuffle(examReadyPbqs).slice(0,pbqCount).map(q=>({kind:"pbq",q:stripPbqHintsForExam(q)}));
    const pickedMcq=shuffle(liveMcqs.filter(q=>!q.beyondTextbook)).slice(0,mcqCount).map(q=>({kind:"mcq",q:shuffleMcqOptions(q)}));
    const examQs=[...pickedPbq,...pickedMcq];
    setQuestions(examQs);
    setAnswers(Object.fromEntries(examQs.map((item,index)=>[index,initAnswer(item)])));
    setFlagged({});
    setTimeSpent({});
    setQi(0);
    setTimeLeft(examDuration);
    setDone(false);
    setSaved(false);
    setCompletedRows([]);
    setStarted(true);
    capture("exam_mode_started", { question_count: questionCount, pbq_count: pbqCount, tier: user.tier });
  };

  useEffect(()=>{
    let active=true;
    DB.getPracticeSession(sessionKey).then(saved=>{
      if(active)setResumeAvailable(Boolean(saved&&!saved.done&&saved.questions?.length));
    });
    return()=>{active=false;};
  },[sessionKey]);

  useEffect(()=>{
    if(!started||done||!questions.length)return;
    DB.savePracticeSession(sessionKey,{questionCount,pbqCount,questions,answers,qi,flagged,timeLeft,timeSpent,done:false,updatedAt:new Date().toISOString()});
  },[sessionKey,started,done,questionCount,pbqCount,questions,answers,qi,flagged,timeLeft,timeSpent]);

  const continueExam=async()=>{
    const saved=await DB.getPracticeSession(sessionKey);
    if(!saved?.questions?.length)return;
    setQuestionCount(saved.questionCount||saved.questions.length||20);
    setPbqCount(Number.isInteger(saved.pbqCount)?saved.pbqCount:saved.questions.filter(item=>item.kind==="pbq").length);
    setQuestions(saved.questions);
    setAnswers(saved.answers||{});
    setQi(saved.qi||0);
    setFlagged(saved.flagged||{});
    setTimeLeft(saved.timeLeft||examDuration);
    setTimeSpent(saved.timeSpent||{});
    setDone(false);
    setSaved(false);
    setCompletedRows([]);
    setStarted(true);
  };
  const updateAnswer=patch=>setAnswers(prev=>({...prev,[qi]:{...(prev[qi]||{}),...patch}}));
  const setAnswerAt=(index,patch)=>setAnswers(prev=>({...prev,[index]:{...(prev[index]||{}),...patch}}));
  const selectMcqOption=optionIndex=>{
    const eliminated={...(answer.eliminated||{})};
    delete eliminated[optionIndex];
    updateAnswer({selected:optionIndex,eliminated});
  };
  const toggleEliminatedOption=(optionIndex,questionIndex=qi)=>{
    setAnswers(prev=>{
      const currentAnswer=prev[questionIndex]||{};
      const eliminated={...(currentAnswer.eliminated||{})};
      const alreadyEliminated=Boolean(eliminated[optionIndex]);
      if(alreadyEliminated) delete eliminated[optionIndex];
      else {
        const eliminatedCount=Object.values(eliminated).filter(Boolean).length;
        if(eliminatedCount>=3) return prev;
        eliminated[optionIndex]=true;
      }
      const selected=currentAnswer.selected===optionIndex&&!alreadyEliminated ? null : currentAnswer.selected;
      return {...prev,[questionIndex]:{...currentAnswer,selected,eliminated}};
    });
  };
  const startOptionLongPress=(optionIndex,e)=>{
    longPressTimers.current[optionIndex]=window.setTimeout(()=>{
      longPressActivated.current[optionIndex]=true;
      toggleEliminatedOption(optionIndex);
      if(navigator.vibrate) navigator.vibrate(12);
    },520);
  };
  const clearOptionLongPress=optionIndex=>{
    window.clearTimeout(longPressTimers.current[optionIndex]);
    delete longPressTimers.current[optionIndex];
  };
  const pbqCorrect=(q,a={})=>{
    if(["TERMINAL SIM","HOTSPOT","LOG ANALYSIS","CONFIG/ACL","SCENARIO"].includes(q.type)) return a.selected===q.correct;
    if(q.type==="ORDERING") return q.correctOrder?.every((id,i)=>a.orderItems?.[i]?.id===id);
    if(q.type===SELECT_FILL_PBQ_TYPE) return q.blanks?.every(b=>isFillBlankAnswerCorrect(a.blanks?.[b.id],b));
    return false;
  };
  const isCorrect=(item,a={})=>item.kind==="mcq" ? a.selected===item.q.correct : pbqCorrect(item.q,a);
  const isAnswered=(item,a={})=>{
    if(item.kind==="mcq") return a.selected!==null&&a.selected!==undefined;
    const q=item.q;
    if((q.choices||q.options)&&["TERMINAL SIM","HOTSPOT","LOG ANALYSIS","CONFIG/ACL","SCENARIO"].includes(q.type)) return a.selected!==null&&a.selected!==undefined;
    if(q.type===SELECT_FILL_PBQ_TYPE) return q.blanks?.some(b=>(a.blanks?.[b.id]||"").trim());
    if(q.type==="ORDERING") return Boolean(a.orderItems?.length);
    return Boolean(a.termInput);
  };
  const answeredCount=questions.filter((item,index)=>isAnswered(item,answers[index])).length;
  const correctCount=questions.filter((item,index)=>isCorrect(item,answers[index])).length;
  const score=questions.length?Math.round((correctCount/questions.length)*100):0;

  function submitExam(auto=false) {
    if(done||submittingExam) return;
    if(!auto){
      const flaggedCount=Object.values(flagged).filter(Boolean).length;
      const warnings=[];
      if(answeredCount<questions.length) warnings.push(`${questions.length-answeredCount} unanswered question${questions.length-answeredCount===1?"":"s"}`);
      if(flaggedCount) warnings.push(`${flaggedCount} flagged question${flaggedCount===1?"":"s"} for review`);
      if(warnings.length){
        const ok=window.confirm(`Final review checkpoint: you still have ${warnings.join(" and ")}. Are you sure you want to submit?`);
        if(!ok) return;
      }
    }
    setSubmittingExam(true);
    window.setTimeout(()=>{
      const rows=questions.map((item,index)=>{
        const q=item.q;
        return {
          qid:q.id,
          correct:isCorrect(item,answers[index]),
          selected:answers[index]?.selected,
          title:(item.kind==="mcq"?q.q:q.title).slice(0,80),
          ch:q.ch,
          domain:item.kind==="mcq"?(CHAPTERS.find(c=>c.id===q.ch)?.title||""):q.cat,
          topic:item.kind==="mcq"?q.topic:q.type,
          difficulty:q.difficulty,
          mcq:item.kind==="mcq",
          pbq:item.kind==="pbq",
          exam:true,
          timeSpentSeconds:timeSpent[index]||0,
          createdAt:new Date().toISOString(),
        };
      });
      if(!saved){
        rows.forEach(row=>onSave(row));
        setSaved(true);
      }
      const finalScore=rows.length?Math.round((rows.filter(r=>r.correct).length/rows.length)*100):0;
      onSessionComplete?.({
        session_type:"exam",
        score:finalScore,
        duration_seconds:Math.max(1,examDuration-timeLeft),
        questions_count:rows.length,
        chapter_id:null,
      });
      setCompletedRows(rows);
      capture("exam_mode_completed", { question_count: questions.length, correct_count: rows.filter(r=>r.correct).length, score: finalScore, auto_submitted: auto, tier: user.tier });
      DB.clearPracticeSession(sessionKey);
      setDone(true);
      setSubmittingExam(false);
    },900);
  }

  useEffect(()=>{
    if(!started||done||submittingExam)return;
    if(timeLeft<=0){submitExam(true);return;}
    const id=setInterval(()=>{
      setTimeLeft(s=>Math.max(0,s-1));
      setTimeSpent(prev=>({...prev,[qi]:(prev[qi]||0)+1}));
    },1000);
    return()=>clearInterval(id);
  },[started,done,submittingExam,timeLeft,qi]);

  const closeExamGuide=async()=>{
    setShowExamGuide(false);
    try{await storageSet(examGuideKey,"true");}catch{}
    capture("exam_mode_guide_closed", { tier: user?.tier || "unknown" });
  };

  useEffect(()=>{
    if(!isPro&&examPasses<1)return;
    let active=true;
    storageGet(examGuideKey).then(value=>{
      if(active&&!value?.value) setShowExamGuide(true);
    }).catch(()=>{if(active)setShowExamGuide(true);});
    return()=>{active=false;};
  },[examGuideKey,isPro,examPasses]);

  if(!isPro&&examPasses<1) return(
    <div className="exam-setup-screen fu" style={{padding:"28px 24px",maxWidth:760,margin:"0 auto"}}>
      <div className="card" style={{padding:"24px",borderColor:`${t.accent}35`,background:`${t.accent}07`}}>
        <div className="page-title-row" style={{marginBottom:10}}>
          <NavGlyph type="exam" active/>
          <h2 style={{fontSize:24,color:t.text}}>Unlock a full practice exam</h2>
        </div>
        <p style={{fontSize:14,color:t.textSec,lineHeight:1.7,marginBottom:16}}>
          Exchange {CIPHER_COIN_COSTS.examPass} Cipher Coins for one SecurePlus practice exam voucher, or choose Pro for unlimited exams with zero coin requirements. This is not an official CompTIA exam voucher.
        </p>
        <div style={{marginBottom:16}}>
          <TrustBadge t={t}/>
        </div>
        <div style={{display:"flex",gap:10,flexWrap:"wrap"}}>
          <button className="btn btn-primary" onClick={onOpenWallet}><CipherCoinIcon size={24}/> Get an Exam Voucher</button>
          <button className="btn btn-outline" onClick={onUpgrade}>Choose Pro · zero coins</button>
        </div>
      </div>
    </div>
  );

  if(!started) return(
    <>
    <div className="exam-setup-screen fu" style={{padding:"28px 24px",maxWidth:820,margin:"0 auto"}}>
      <div className="page-title-row" style={{marginBottom:18}}>
        <NavGlyph type="exam" active/>
        <div>
          <h2 style={{fontSize:26,color:t.text}}>Exam Mode</h2>
          <p style={{fontSize:14,color:t.textSec}}>{isPro?"Unlimited timed mixed practice with zero coin requirements.":`${examPasses} practice exam voucher${examPasses===1?"":"s"} available · one is used when a new exam begins.`}</p>
          <div style={{marginTop:9}}>
            <TrustBadge t={t} compact/>
          </div>
        </div>
      </div>
      <div className="card" style={{padding:"10px",marginBottom:16,display:"flex",gap:8,flexWrap:"wrap"}}>
        <button className="btn btn-primary" style={{fontSize:12}}>Practice Exam</button>
        {canPreviewDeepDives?(
          <button className="btn btn-outline" style={{fontSize:12}} onClick={onOpenDeepDives}>
            <Layers3 size={15}/> Concept Deep Dives · Preview
          </button>
        ):(
          <button className="btn btn-ghost" style={{fontSize:12,opacity:.72,cursor:"not-allowed"}} disabled title="Coming soon">
            Concept Deep Dives · Coming soon
          </button>
        )}
      </div>
      <div className="card" style={{padding:"20px 22px",marginBottom:16}}>
        <div style={{fontWeight:800,color:t.text,marginBottom:8}}>Exam setup</div>
        <p style={{fontSize:13,color:t.textSec,lineHeight:1.7,marginBottom:16}}>
          Choose the exam length and adjust the MCQ/PBQ split. PBQs appear first. The timer scales by exam length: 50 questions gives 1 hour, 10 questions gives 12 minutes.
        </p>
        <label className="label" style={{display:"block",marginBottom:8}}>Total questions</label>
        <div style={{display:"grid",gridTemplateColumns:"repeat(5,1fr)",gap:8,marginBottom:16}}>
          {sizes.map(size=>(
            <button key={size} className={`btn ${questionCount===size?"btn-primary":"btn-ghost"}`} onClick={()=>updateQuestionCount(size)}>{size}</button>
          ))}
        </div>
        <div style={{marginTop:4}}>
          <div style={{display:"flex",justifyContent:"space-between",gap:12,alignItems:"center",marginBottom:10,flexWrap:"wrap"}}>
            <div>
              <div className="label" style={{marginBottom:3}}>Exam composition</div>
              <div style={{fontSize:13,color:t.textSec}}>
                {pbqCount} PBQ first · {mcqCount} MCQ after · {formatTime(examDuration)} timer
              </div>
            </div>
            <div style={{display:"flex",gap:8,alignItems:"center",fontSize:12,fontWeight:900}}>
              <span style={{color:t.amber}}>{pbqPercent}% PBQ</span>
              <span style={{color:t.textDim}}>·</span>
              <span style={{color:t.accent}}>{mcqPercent}% MCQ</span>
            </div>
          </div>
          <div style={{position:"relative",padding:"16px 0 6px"}}>
            <div style={{height:18,borderRadius:99,overflow:"hidden",display:"flex",border:`1px solid ${t.border}`,boxShadow:`inset 0 0 0 1px ${t.surface}`}}>
              <div style={{width:`${pbqPercent}%`,background:`linear-gradient(90deg, ${t.amber}cc, ${t.amber}88)`,transition:"width .18s"}}/>
              <div style={{width:`${mcqPercent}%`,background:`linear-gradient(90deg, ${t.accent}99, ${t.accent}dd)`,transition:"width .18s"}}/>
            </div>
            <input
              type="range"
              min="0"
              max={questionCount}
              step="1"
              value={pbqCount}
              aria-label="PBQ count"
              onChange={e=>setPbqCount(Number(e.target.value))}
              style={{position:"absolute",left:0,right:0,top:6,width:"100%",height:38,opacity:.001,cursor:"ew-resize"}}
            />
            <div style={{position:"absolute",top:8,left:`clamp(0px, calc(${pbqPercent}% - 11px), calc(100% - 22px))`,width:22,height:34,borderRadius:99,background:t.surface,border:`2px solid ${t.text}`,boxShadow:"0 8px 20px rgba(0,0,0,.22)",pointerEvents:"none",transition:"left .18s"}}/>
          </div>
          <div style={{display:"flex",justifyContent:"space-between",fontSize:11,color:t.textDim,marginTop:4}}>
            <span>100% MCQ</span>
            <span>Balanced</span>
            <span>100% PBQ</span>
          </div>
        </div>
      </div>
      {resumeAvailable&&(
        <div className="card" style={{padding:"16px 20px",marginBottom:16,borderColor:`${t.amber}35`,background:`${t.amber}07`}}>
          <div style={{display:"flex",gap:12,alignItems:"center",flexWrap:"wrap"}}>
            <div style={{flex:1,minWidth:220}}>
              <div style={{fontWeight:800,color:t.text,fontSize:14}}>Unfinished exam found</div>
              <div style={{fontSize:13,color:t.textSec}}>Continue your previous exam with answers, flags, and timer restored.</div>
            </div>
            <button className="btn btn-primary" style={{fontSize:12}} onClick={continueExam}>Continue</button>
          </div>
        </div>
      )}
      <div className="card" style={{padding:"16px 20px",marginBottom:16,borderColor:`${t.amber}35`,background:`${t.amber}07`}}>
        <div style={{display:"flex",alignItems:"center",gap:8,fontWeight:800,color:t.amber,fontSize:14,marginBottom:4}}>
          <span className="chip" style={{background:`${t.amber}16`,color:t.amber,borderColor:`${t.amber}45`}}>Practice score</span>
          <span>Pass/fail disclaimer</span>
        </div>
        <p style={{fontSize:13,color:t.textSec,lineHeight:1.7}}>
          SecurePlus uses <strong style={{color:t.amber}}>80%</strong> as a practice pass mark here. This is not an accurate CompTIA scoring model. The real Security+ exam uses a proprietary scaled score from 100 to 900, and PBQs can carry different weight.
        </p>
      </div>
      <button className="btn btn-primary" style={{width:"100%",justifyContent:"center",padding:"13px"}} onClick={startExam} disabled={accessStarting}>
        {accessStarting?"Opening exam...":isPro?"Start Exam →":"Use 1 pass & start →"}
      </button>
    </div>
    {showExamGuide&&<ExamModeGuideModal t={t} onClose={closeExamGuide}/>}
    </>
  );

  if(submittingExam) return <LoadingScreen t={t}/>;

  const examReviewRows=questions.map((item,index)=>({
    item,
    index,
    ok:isCorrect(item,answers[index]||{}),
    seconds:timeSpent[index]||0,
    target:expectedExamSeconds(item),
  }));
  const timingFocus=Object.values(examReviewRows.reduce((acc,row)=>{
    const q=row.item.q;
    const key=row.item.kind==="mcq" ? `Ch.${q.ch}: ${q.topic}` : `PBQ: ${q.type}`;
    if(!acc[key]) acc[key]={key,total:0,slow:0,missed:0,seconds:0,target:0};
    acc[key].total++;
    acc[key].seconds+=row.seconds;
    acc[key].target+=row.target;
    if(!row.ok) acc[key].missed++;
    if(row.seconds>row.target*1.35) acc[key].slow++;
    return acc;
  },{})).filter(item=>item.missed||item.slow).sort((a,b)=>(b.missed+b.slow)-(a.missed+a.slow)).slice(0,4);
  const incorrectExamRows=examReviewRows.filter(row=>!row.ok);
  const flaggedCount=Object.values(flagged).filter(Boolean).length;
  const avgExamSeconds=examReviewRows.length?Math.round(examReviewRows.reduce((sum,row)=>sum+row.seconds,0)/examReviewRows.length):0;
  const slowCount=examReviewRows.filter(row=>row.seconds>row.target*1.35).length;
  const totalExamSeconds=examReviewRows.reduce((sum,row)=>sum+row.seconds,0);
  const completionRate=questions.length?Math.round((answeredCount/questions.length)*100):0;
  const combinedReadinessAttempts=[...completedRows,...attempts.filter(attempt=>!completedRows.includes(attempt))];
  const reportReadiness=getReadinessProfile(combinedReadinessAttempts);
  const reportReadinessColor=reportReadiness.score>=80?t.green:reportReadiness.score>=65?t.accent:reportReadiness.score>=45?t.amber:t.red;
  const gradeLabel=score>=90?"Outstanding":score>=80?"Practice pass":score>=70?"Nearly there":score>=60?"Building skills":"Focus and rebuild";
  const resultMessage=score>=90
    ? "Excellent control of this exam set. Keep the result stable with another timed attempt after a short review gap."
    : score>=80
      ? "You cleared the SecurePlus practice target. Review the misses so this performance becomes repeatable."
      : score>=70
        ? "You are close to the practice target. A focused repair set can turn the weak areas into a pass."
        : "Use the report below as a study plan. Repair the weakest area first, then retake only the missed questions.";
  const typePerformance=[
    {id:"mcq",label:"MCQ knowledge",rows:examReviewRows.filter(row=>row.item.kind==="mcq"),Icon:BookOpenCheck},
    {id:"pbq",label:"PBQ application",rows:examReviewRows.filter(row=>row.item.kind==="pbq"),Icon:Puzzle},
  ].filter(group=>group.rows.length).map(group=>({
    ...group,
    correct:group.rows.filter(row=>row.ok).length,
    accuracy:Math.round((group.rows.filter(row=>row.ok).length/group.rows.length)*100),
  }));
  const topicPerformance=Object.values(examReviewRows.reduce((acc,row)=>{
    const q=row.item.q;
    const key=row.item.kind==="mcq"?(CHAPTERS.find(chapter=>chapter.id===q.ch)?.title||q.topic||"MCQ"):`PBQ · ${q.type}`;
    if(!acc[key])acc[key]={key,total:0,correct:0};
    acc[key].total++;
    if(row.ok)acc[key].correct++;
    return acc;
  },{})).map(item=>({...item,accuracy:Math.round((item.correct/item.total)*100)}));
  const strongestTopic=[...topicPerformance].sort((a,b)=>b.accuracy-a.accuracy||b.total-a.total)[0];
  const focusTopic=[...topicPerformance].filter(item=>item.correct<item.total).sort((a,b)=>a.accuracy-b.accuracy||b.total-a.total)[0];
  const reportDate=new Date(completedRows[0]?.createdAt||Date.now()).toLocaleDateString(undefined,{day:"numeric",month:"short",year:"numeric"});
  const printReport=()=>{
    capture("exam_report_card_printed", { score, question_count:questions.length, tier:user.tier });
    window.print();
  };
  const retakeIncorrectExam=()=>{
    const missed=incorrectExamRows.map(row=>row.item);
    if(!missed.length)return;
    setQuestions(missed);
    setAnswers(Object.fromEntries(missed.map((item,index)=>[index,initAnswer(item)])));
    setFlagged({});
    setTimeSpent({});
    setExpandedReview({});
    setQi(0);
    setQuestionCount(missed.length);
    setPbqCount(missed.filter(item=>item.kind==="pbq").length);
    setTimeLeft(Math.max(1,missed.length)*72);
    setDone(false);
    setSaved(false);
    setCompletedRows([]);
    setSubmittingExam(false);
    setStarted(true);
    capture("exam_retake_incorrect_started", { question_count: missed.length, tier: user.tier });
  };

  if(done) return(
    <div className="results-shell">
      <section className="card exam-report-card" style={{"--report-color":score>=80?t.green:t.red,"--report-readiness-color":reportReadinessColor}}>
        <header className="exam-report-header">
          <div className="exam-report-brand">
            <span><ShieldCheck size={25} strokeWidth={2.4}/></span>
            <div><strong>SecurePlus</strong><small>Exam report card</small></div>
          </div>
          <div className="exam-report-date"><span>Completed</span><strong>{reportDate}</strong></div>
        </header>

        <div className="exam-report-hero">
          <div className="exam-report-score">
            <div className="exam-report-status-row">
              <span>{score>=80?"Practice passed":"Below practice target"}</span>
              <span className="info-popover">
                <button className="info-btn" type="button" aria-label="Practice score disclaimer" onClick={()=>setShowScoreDisclaimer(value=>!value)}>i</button>
                {showScoreDisclaimer&&(
                  <span className="info-tooltip">
                    SecurePlus uses 80% as a practice pass mark. This is not the official CompTIA scoring model; real exam scoring is proprietary and PBQs may carry different weight.
                  </span>
                )}
              </span>
            </div>
            <RadialScore score={score} correct={correctCount} total={questions.length} t={t}/>
          </div>
          <div className="exam-report-summary">
            <div className="exam-report-kicker">Candidate · {user.name}</div>
            <h1>{gradeLabel}</h1>
            <p>{resultMessage}</p>
            <div className="exam-report-readiness">
              <span className="exam-report-readiness-icon"><Gauge size={22} strokeWidth={2.4}/></span>
              <div>
                <small>Updated readiness</small>
                <strong>{reportReadiness.score}/100 · {reportReadiness.level}</strong>
              </div>
            </div>
          </div>
        </div>

        <div className="exam-report-metrics">
          <div><span>Correct answers</span><strong style={{color:t.green}}>{correctCount}<small> / {questions.length}</small></strong></div>
          <div><span>Completion</span><strong>{completionRate}%</strong></div>
          <div><span>Total time</span><strong>{formatSecondsShort(totalExamSeconds)}</strong></div>
          <div><span>Average pace</span><strong style={{color:slowCount?t.amber:t.green}}>{formatSecondsShort(avgExamSeconds)}</strong></div>
        </div>

        <div className="exam-report-section">
          <div className="exam-report-section-title">
            <div><span>Performance breakdown</span><strong>Knowledge and applied skills</strong></div>
            <small>{flaggedCount} flagged · {slowCount} slow</small>
          </div>
          <div className="exam-report-type-grid">
            {typePerformance.map(group=>(
              <div key={group.id} className="exam-report-type">
                <span className="exam-report-type-icon"><group.Icon size={20} strokeWidth={2.3}/></span>
                <div>
                  <span>{group.label}</span>
                  <strong>{group.correct}/{group.rows.length} correct</strong>
                </div>
                <b style={{color:group.accuracy>=80?t.green:group.accuracy>=65?t.amber:t.red}}>{group.accuracy}%</b>
                <div className="exam-report-type-meter"><span style={{width:`${group.accuracy}%`}}/></div>
              </div>
            ))}
          </div>
        </div>

        <div className="exam-report-insights">
          <div className="exam-report-insight strength">
            <span><Trophy size={18} strokeWidth={2.4}/> Strongest signal</span>
            <strong>{strongestTopic?.key||"Complete more questions"}</strong>
            <p>{strongestTopic?`${strongestTopic.correct}/${strongestTopic.total} correct in this area.`:"A larger exam will reveal a clearer strength."}</p>
          </div>
          <div className="exam-report-insight focus">
            <span><Target size={18} strokeWidth={2.4}/> Best next focus</span>
            <strong>{focusTopic?.key||"Protect your result"}</strong>
            <p>{focusTopic?`${focusTopic.total-focusTopic.correct} missed here. Retake the missed questions after reviewing explanations.`:"No missed topic cluster—repeat a timed set later to confirm consistency."}</p>
          </div>
        </div>

        <footer className="exam-report-footer">
          <span>This report is a SecurePlus practice summary, not an official CompTIA score report.</span>
          <span>Use readiness to choose what to practise next, not to predict the official exam result.</span>
        </footer>
      </section>
      <div className="score-actions">
        <button className="btn btn-outline" onClick={printReport}>
          <FileText size={16}/> Print / Save Report
        </button>
        <button className="btn btn-primary" disabled={!incorrectExamRows.length} onClick={retakeIncorrectExam}>
          Retake Incorrect Questions
        </button>
        <button className="btn btn-outline" onClick={()=>{setStarted(false);setDone(false);}}>
          New Full Exam
        </button>
        <button className="btn btn-ghost" onClick={()=>setStarted(false)}>
          Back to Exam Setup
        </button>
      </div>
      <div className="card" style={{padding:"18px 20px",marginBottom:18,borderColor:`${t.accent}28`,background:`${t.accent}05`}}>
        <div style={{fontWeight:900,color:t.text,fontSize:16,marginBottom:4}}>Timing and topic analysis</div>
        {timingFocus.length?(
          <div className="analytics-grid">
            {timingFocus.map(item=>{
              const avg=Math.round(item.seconds/item.total);
              const expected=Math.round(item.target/item.total);
              const pacing=Math.min(100,Math.round((expected/Math.max(avg,1))*100));
              return(
                <div key={item.key} className="telemetry-card">
                  <div style={{display:"flex",justifyContent:"space-between",gap:10,flexWrap:"wrap",marginBottom:8}}>
                    <div style={{fontSize:13,fontWeight:800,color:t.text}}>{item.key}</div>
                    <div style={{fontSize:12,fontWeight:800,color:item.missed?t.red:t.amber}}>
                      {item.missed} missed · {item.slow} slow
                    </div>
                  </div>
                  <div style={{display:"grid",gridTemplateColumns:"auto 1fr auto",gap:10,alignItems:"center"}}>
                    <span style={{fontSize:12,color:t.textDim,fontWeight:800}}>Pace</span>
                    <div className="telemetry-meter"><span style={{width:`${pacing}%`}}/></div>
                    <span style={{fontSize:12,color:t.textSec,fontWeight:900}}>{formatSecondsShort(avg)} / {formatSecondsShort(expected)}</span>
                  </div>
                </div>
              );
            })}
          </div>
        ):(
          <div style={{fontSize:13,color:t.textSec,lineHeight:1.7}}>Strong pacing. No major slow or missed topic cluster stood out in this exam.</div>
        )}
      </div>
      <div className="review-toolbar">
        <div>
          <h3 style={{fontSize:20,color:t.text,marginBottom:4}}>Answer Review</h3>
          <div style={{fontSize:13,color:t.textSec,lineHeight:1.6}}>Missed questions appear first so you can repair weak spots quickly.</div>
        </div>
        <span className="review-count-pill">{incorrectExamRows.length} missed · {questions.length} total</span>
        <button className="btn btn-outline" onClick={()=>{setStarted(false);setDone(false);}}>New Exam</button>
      </div>
      <div style={{display:"grid",gap:12}}>
        {examReviewRows
          .sort((a,b)=>Number(a.ok)-Number(b.ok)||a.index-b.index)
          .map(({item,index,ok,seconds,target})=>{
          const q=item.q;
          const a=answers[index]||{};
          const title=item.kind==="mcq"?q.q:q.title;
          const expanded=Boolean(expandedReview[index]);
          const reviewColor=ok?t.green:t.red;
          const selectedLabel=a.selected!==null&&a.selected!==undefined ? `${String.fromCharCode(65+a.selected)}. ${q.opts?.[a.selected]||""}` : "Not answered";
          const correctLabel=item.kind==="mcq" ? `${String.fromCharCode(65+q.correct)}. ${q.opts[q.correct]}` : "See solution below";
          return(
            <div
              key={`${item.kind}-${q.id}`}
              className={`card exam-review-card ${ok?"correct":"incorrect"}`}
              style={{"--review-color":reviewColor}}
              onClick={()=>setExpandedReview(prev=>({...prev,[index]:!prev[index]}))}
            >
              <div className="exam-review-main">
                <div className="exam-review-head">
                  <div className="exam-review-status">{ok?<Check size={17} strokeWidth={3}/>:<X size={17} strokeWidth={3}/>}</div>
                  <div style={{minWidth:0}}>
                    <div className="exam-review-meta">
                      <span style={{fontWeight:950,color:reviewColor}}>{ok?"Correct":"Needs review"}</span>
                      {showQuestionCodes&&<QuestionCodeChip id={q.id} t={t}/>}
                      {item.kind==="mcq"?<ChBadge chId={q.ch} t={t}/>:<SimBadge type={q.type} t={t}/>}
                      {flagged[index]&&<span className="chip" style={{background:`${t.amber}14`,color:t.amber,borderColor:`${t.amber}35`}}>Flagged</span>}
                      <span className="chip" style={{background:seconds>target*1.35?`${t.amber}14`:t.panel,color:seconds>target*1.35?t.amber:t.textSec,borderColor:seconds>target*1.35?`${t.amber}35`:t.border}}>
                        {formatSecondsShort(seconds)} / target {formatSecondsShort(target)}
                      </span>
                    </div>
                    <div className="exam-review-title" style={{marginTop:8}}>
                      {expanded ? <QuestionStemText text={title} t={t} compact/> : `${title.slice(0,150)}${title.length>150?"...":""}`}
                    </div>
                  </div>
                  <div className="exam-review-toggle">{expanded?"Hide details":"View details"}</div>
                </div>
              {expanded&&item.kind==="pbq"&&(
                <div style={{fontSize:13,color:t.textSec,lineHeight:1.7,marginBottom:10}}>
                  {q.scenario&&<div style={{marginBottom:8}}><strong style={{color:t.text}}>Scenario: </strong><PBQProseText text={q.scenario} t={t} paragraphGap={5}/></div>}
                  {q.question&&<div style={{marginBottom:8}}><strong style={{color:t.text}}>Question: </strong><PBQProseText text={q.question} t={t} paragraphGap={5}/></div>}
                  {(q.choices||q.options)?.length>0&&(
                    <div style={{display:"grid",gap:7,marginTop:8}}>
                      <strong style={{color:t.text}}>Option review</strong>
                      {(q.choices||q.options||[]).map((choice,choiceIndex)=>{
                        const optionCorrect=choiceIndex===q.correct;
                        const wasSelected=a.selected===choiceIndex;
                        const feedback=q.optionFeedback?.[choiceIndex] || (optionCorrect ? ensureFeedbackLead(q.explanation||"",true) : q.wrongFeedback?.[choiceIndex] ? ensureFeedbackLead(q.wrongFeedback[choiceIndex],false) : buildPbqOptionFeedback(q,choiceIndex,choice,q.correct));
                        return(
                          <div key={choiceIndex} style={{padding:"9px 10px",borderRadius:9,border:`1px solid ${optionCorrect?t.green:wasSelected?t.red:t.border}35`,background:optionCorrect?`${t.green}08`:wasSelected?`${t.red}08`:t.panel}}>
                            <div style={{display:"flex",gap:7,alignItems:"flex-start",color:t.text,lineHeight:1.55}}>
                              <strong style={{color:optionCorrect?t.green:wasSelected?t.red:t.textSec}}>{String.fromCharCode(65+choiceIndex)}. {optionCorrect?"Correct.":"Incorrect."}</strong>
                              <GlossaryText text={choice} t={t}/>
                            </div>
                            <div style={{fontSize:12,color:t.textSec,lineHeight:1.6,marginTop:5}}><PBQProseText text={feedback} t={t} paragraphGap={5}/></div>
                          </div>
                        );
                      })}
                    </div>
                  )}
                  {q.type===SELECT_FILL_PBQ_TYPE&&q.blanks?.length>0&&(
                    <div style={{display:"grid",gap:7,marginTop:8}}>
                      <strong style={{color:t.text}}>Blank review</strong>
                      {q.blanks.map((blank,blankIndex)=>{
                        const userValue=a.blanks?.[blank.id]||"Not answered";
                        const correct=isFillBlankAnswerCorrect(userValue,blank);
                        return(
                          <div key={blank.id||blankIndex} style={{padding:"9px 10px",borderRadius:9,border:`1px solid ${correct?t.green:t.red}35`,background:`${correct?t.green:t.red}08`}}>
                            <div style={{color:t.text,lineHeight:1.55}}><GlossaryText text={blank.sentence} t={t}/></div>
                            <div style={{marginTop:4,fontSize:12}}>Your answer: <strong style={{color:correct?t.green:t.red}}>{userValue}</strong></div>
                            {!correct&&<div style={{fontSize:12}}>Correct answer: <strong style={{color:t.green}}>{blank.answer}</strong></div>}
                          </div>
                        );
                      })}
                    </div>
                  )}
                  {q.type!==SELECT_FILL_PBQ_TYPE&&q.items&&q.targets&&(
                    <div style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:10,marginTop:8}}>
                      <div>
                        <strong style={{color:t.text}}>Items</strong>
                        {q.items.map(item=><div key={item.id}>- {item.label}</div>)}
                      </div>
                      <div>
                        <strong style={{color:t.text}}>Targets</strong>
                        {q.targets.map(target=><div key={target.id}>- {target.label}</div>)}
                      </div>
                    </div>
                  )}
                </div>
              )}
              {item.kind==="mcq"&&(
                <div className="answer-compare">
                  <div className={`answer-compare-box ${ok?"correct":"yours"}`}>
                    <strong>{ok?"Your answer":"Your answer"}</strong>
                    {selectedLabel}
                  </div>
                  <div className="answer-compare-box correct">
                    <strong>Correct answer</strong>
                    {correctLabel}
                  </div>
                </div>
              )}
              <div className="solution-panel">
                {item.kind==="mcq"?(
                  <>
                    <MCQFeedbackVerdict correct={ok} t={t} compact/>
                    <div style={{marginTop:6}}>{q.exp}</div>
                  </>
                ):(
                  <><strong style={{color:t.text}}>Solution: </strong>{q.explanation}</>
                )}
              </div>
              <div className="guidance-panel">
                {examTimeGuidance(item,seconds,ok)}
              </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );

  const q=current?.q;
  const timerGlow=timeLeft<=60 || (timeLeft>0&&timeLeft%60===0);
  return(
    <div style={{padding:"24px",maxWidth:960,margin:"0 auto"}}>
      <div className="top-progress" aria-hidden="true"><span style={{width:`${((qi+1)/questions.length)*100}%`}}/></div>
      <div className="card" style={{padding:"14px 16px",marginBottom:16,display:"flex",gap:12,alignItems:"center",flexWrap:"wrap",position:"sticky",top:12,zIndex:40}}>
        <div className={`exam-timer ${timerGlow?"glow":""}`} style={{fontWeight:900,color:timeLeft<300?t.red:t.text,fontSize:20}}>{formatTime(timeLeft)}</div>
        <div style={{fontSize:13,color:t.textSec}}>Question {qi+1} of {questions.length} · {answeredCount} answered</div>
        <button className={`btn ${flagged[qi]?"btn-primary":"btn-ghost"}`} style={{marginLeft:"auto",fontSize:12}} onClick={()=>setFlagged(f=>({...f,[qi]:!f[qi]}))}>
          {flagged[qi]?"Flagged":"Flag for review"}
        </button>
        <button className="btn btn-primary" style={{fontSize:12}} onClick={()=>submitExam(false)}>Submit Exam</button>
      </div>

      <div className="exam-layout">
        <div>
          <div style={{display:"flex",justifyContent:"space-between",gap:10,marginBottom:12}}>
            <button className="btn btn-ghost" disabled={qi===0} onClick={()=>setQi(i=>Math.max(0,i-1))}>← Previous</button>
            <button className="btn btn-ghost" disabled={qi===questions.length-1} onClick={()=>setQi(i=>Math.min(questions.length-1,i+1))}>Next →</button>
          </div>
          <div className={`card question-card ${current.kind==="pbq"?"pbq-scenario-card":""}`} style={{"--sim-color":current.kind==="pbq"?((Object.values(SIM_TYPES).find(s=>s.id===q.type)?.color)||t.accent):undefined,padding:"20px 22px",marginBottom:16,position:"relative",overflow:"hidden"}}>
            {flagged[qi]&&<div className="exam-flag-ribbon"><span>Review</span></div>}
            <div style={{display:"flex",gap:8,marginBottom:12,flexWrap:"wrap"}}>
              {current.kind==="mcq"?<ChBadge chId={q.ch} t={t}/>:<SimBadge type={q.type} t={t}/>}
              {showQuestionCodes&&<QuestionCodeChip id={q.id} t={t}/>}
              <DiffBadge d={q.difficulty} t={t}/>
              <span className="chip meta-chip">{current.kind==="mcq"?"MCQ":"PBQ"}</span>
              {flagged[qi]&&<span className="chip" style={{background:`${t.amber}16`,color:t.amber,borderColor:`${t.amber}45`}}>Flagged for review</span>}
            </div>
            <div className="question-text" style={{fontSize:16,lineHeight:1.75,color:t.text,fontWeight:700}}>
              <QuestionStemText text={current.kind==="mcq"?q.q:(q.question||q.title)} t={t}/>
            </div>
            {current.kind==="pbq"&&q.scenario&&(
              <div className="scenario-text" style={{fontSize:13,color:t.textSec,lineHeight:1.58,marginTop:12}}>
                <PBQProseText text={q.scenario} t={t} paragraphGap={5}/>
              </div>
            )}
          </div>

          {current.kind==="pbq"&&<PBQEvidenceViewer title="Code or configuration evidence" content={q?.codeBlock || q?.payload?.evidence?.codeBlock} language={q?.codeLanguage || q?.payload?.evidence?.codeLanguage} t={t} accent={(Object.values(SIM_TYPES).find(s=>s.id===q.type)?.color)||t.accent}/>}
          {current.kind==="pbq"&&<PBQEvidenceViewer title="Log evidence" content={q?.logData || q?.payload?.evidence?.logData} t={t} accent={(Object.values(SIM_TYPES).find(s=>s.id===q.type)?.color)||t.accent}/>}
          {current.kind==="pbq"&&<PBQEvidenceViewer title="Network diagram" content={q?.diagram || q?.payload?.evidence?.diagram} t={t} accent={(Object.values(SIM_TYPES).find(s=>s.id===q.type)?.color)||t.accent}/>}
          {current.kind==="pbq"&&<PBQEvidenceViewer title="Current configuration" content={q?.currentConfig || q?.payload?.evidence?.currentConfig} t={t} accent={(Object.values(SIM_TYPES).find(s=>s.id===q.type)?.color)||t.accent}/>}

          {current.kind==="mcq"&&(
            <div style={{display:"grid",gap:9}}>
              <div style={{fontSize:12,color:t.textDim,lineHeight:1.6}}>
                Right-click an option, long-press on mobile, or use Strike to cross it out.
              </div>
              {q.opts.map((opt,index)=>{
                const eliminated=Boolean(answer.eliminated?.[index]);
                const eliminatedCount=Object.values(answer.eliminated||{}).filter(Boolean).length;
                const strikeDisabled=!eliminated&&eliminatedCount>=3;
                return(
                <div
                  key={index}
                  className={`opt ${answer.selected===index&&!eliminated?"sel":""} ${eliminated?"eliminated":""}`}
                  onClick={()=>{if(longPressActivated.current[index]){delete longPressActivated.current[index];return;}selectMcqOption(index);}}
                  onContextMenu={e=>{
                    e.preventDefault();
                    if(rightClickHandled.current[index]){
                      delete rightClickHandled.current[index];
                      return;
                    }
                    toggleEliminatedOption(index);
                  }}
                  onPointerDown={e=>{
                    if(e.pointerType==="mouse"&&e.button===2){
                      e.preventDefault();
                      rightClickHandled.current[index]=true;
                      toggleEliminatedOption(index);
                      return;
                    }
                    if(e.pointerType==="touch"||e.pointerType==="pen")startOptionLongPress(index,e);
                  }}
                  onPointerUp={()=>clearOptionLongPress(index)}
                  onPointerCancel={()=>clearOptionLongPress(index)}
                  onPointerLeave={()=>clearOptionLongPress(index)}
                  title="Right-click, long-press, or use Strike to cross out"
                >
                  <div className="opt-ltr">{String.fromCharCode(65+index)}</div>
                  <span className="option-text" style={{fontSize:14,color:t.text,lineHeight:1.55}}><GlossaryText text={opt} t={t}/></span>
                  <button
                    type="button"
                    className="btn btn-ghost"
                    style={{marginLeft:"auto",fontSize:11,minHeight:30,padding:"4px 8px",flexShrink:0,color:eliminated?t.accent:t.textDim,borderColor:eliminated?`${t.accent}70`:t.border,opacity:strikeDisabled ? .55 : 1,cursor:strikeDisabled?"not-allowed":"pointer"}}
                    onClick={e=>{e.stopPropagation();toggleEliminatedOption(index);}}
                    disabled={strikeDisabled}
                    aria-label={`${eliminated?"Undo elimination for":"Eliminate"} option ${String.fromCharCode(65+index)}`}
                    title={strikeDisabled ? "At least one answer must remain unstruck." : `${eliminated?"Undo":"Strike"} option ${String.fromCharCode(65+index)}`}
                  >
                    {eliminated?"Undo":"Strike"}
                  </button>
                </div>
              )})}
            </div>
          )}

          {current.kind==="pbq"&&(q.choices||q.options)&&(
            <div style={{display:"grid",gap:9}}>
              {(q.choices||q.options||[]).map((choice,index)=>(
                <div key={index} className={`opt ${answer.selected===index?"sel":""}`} onClick={()=>updateAnswer({selected:index})}>
                  <div className="opt-ltr">{String.fromCharCode(65+index)}</div>
                  <span className="option-text" style={{fontSize:14,color:t.text,lineHeight:1.55}}><GlossaryText text={choice} t={t}/></span>
                </div>
              ))}
            </div>
          )}

          {current.kind==="pbq"&&q.type===SELECT_FILL_PBQ_TYPE&&(
            <PBQSelectionWorkspace
              q={q}
              values={answer.blanks||{}}
              onChange={(blankId,value)=>updateAnswer({blanks:{...(answer.blanks||{}),[blankId]:value}})}
              t={t}
              accent={(Object.values(SIM_TYPES).find(s=>s.id===q.type)?.color)||t.accent}
              showHints={false}
              compact
            />
          )}

          {current.kind==="pbq"&&q.type==="ORDERING"&&(
            <div>
              <div style={{fontSize:12,color:t.textDim,marginBottom:10}}>Drag each answer to rank it from top to bottom.</div>
              <SortableOrderList items={answer.orderItems||[]} onChange={next=>updateAnswer({orderItems:next})} t={t}/>
            </div>
          )}
        </div>

        <div className="card exam-map">
          <div className="label" style={{marginBottom:10}}>Answer map</div>
          <div className="exam-map-grid">
            {questions.map((item,index)=>{
              const active=index===qi;
              const answered=isAnswered(item,answers[index]);
              return(
                <button
                  key={index}
                  className={`btn exam-map-btn ${active?"active":answered?"answered":"unanswered"} ${flagged[index]?"flagged":""}`}
                  aria-label={`Question ${index+1}${answered?", answered":", unanswered"}${flagged[index]?", flagged":""}`}
                  onClick={()=>setQi(index)}
                >
                  {index+1}
                </button>
              );
            })}
          </div>
          <div style={{fontSize:11,color:t.textDim,lineHeight:1.6,marginTop:10}}>
            Amber boxes need attention. Muted boxes are answered. Amber outline means flagged.
          </div>
        </div>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// PRICING
// ═══════════════════════════════════════════════════════════════
function CipherRewardToast({reward,onClose}) {
  const [isLeaving,setIsLeaving]=useState(false);
  const closeRef=useRef(onClose);
  const closeTimerRef=useRef(null);
  useEffect(()=>{closeRef.current=onClose;},[onClose]);
  useEffect(()=>{
    if(!reward)return undefined;
    setIsLeaving(false);
    const fadeTimer=window.setTimeout(()=>setIsLeaving(true),4200);
    closeTimerRef.current=window.setTimeout(()=>closeRef.current?.(),4580);
    return()=>{
      window.clearTimeout(fadeTimer);
      window.clearTimeout(closeTimerRef.current);
    };
  },[reward]);
  const dismiss=()=>{
    window.clearTimeout(closeTimerRef.current);
    setIsLeaving(true);
    closeTimerRef.current=window.setTimeout(()=>closeRef.current?.(),380);
  };
  if(!reward)return null;
  return (
    <div className={`cipher-reward-toast ${isLeaving?"is-leaving":""}`} role="status" aria-live="polite">
      <CipherCoinIcon size={42} celebrate/>
      <span><strong>{reward.amount>0?`+${reward.amount} Cipher Coins`:reward.title||"Cipher Coin wallet updated"}</strong><small>{reward.message||"Your new balance is ready in the Coin Vault."}</small></span>
      <button type="button" onClick={dismiss} aria-label="Close Cipher Coin message"><X size={15}/></button>
    </div>
  );
}

function CipherCoinVault({user,wallet,onUnlockPbq,onBuyExamPass,onNavigate,onRefresh,t,busy=false}) {
  const isPro=user?.tier==="pro";
  const balance=Number(wallet?.balance||0);
  const transactions=wallet?.transactions||[];
  const [lastUnlockedPbq,setLastUnlockedPbq]=useState(null);
  const remainingPbqCount=PBQ_BANK.filter(question=>!isFreePBQPreview(question)&&!(wallet?.unlockedPbqIds||[]).includes(question.id)).length;
  const unlockedPbqCount=(wallet?.unlockedPbqIds||[]).length;
  const pbqGap=Math.max(0,CIPHER_COIN_COSTS.pbq-balance);
  const examGap=Math.max(0,CIPHER_COIN_COSTS.examPass-balance);
  const pbqProgress=isPro?100:Math.min(100,Math.round((balance/CIPHER_COIN_COSTS.pbq)*100));
  const examProgress=isPro?100:Math.min(100,Math.round((balance/CIPHER_COIN_COSTS.examPass)*100));
  const walletGoal=isPro
    ? {label:"Pro access active",status:"Zero coins needed",progress:100}
    : remainingPbqCount===0
      ? {label:"Next exam voucher",status:examGap?`${examGap} coins to go`:"Ready now",progress:examProgress}
      : pbqGap
        ? {label:"Next mystery PBQ",status:`${pbqGap} coins to go`,progress:pbqProgress}
        : {label:"Mystery PBQ ready",status:"You can reveal now",progress:100};
  const coachMessage=isPro
    ? "Your Pro plan already opens every PBQ and practice exam. Keep coins as a record of your study streak."
    : balance>=CIPHER_COIN_COSTS.examPass
      ? "You have enough for either reward. Pick a permanent PBQ or save an exam voucher for a full practice run."
      : balance>=CIPHER_COIN_COSTS.pbq
        ? "You can reveal a permanent mystery PBQ now. Your first three reveals follow the shared starter path."
        : `You are ${pbqGap} coins away from a mystery PBQ. A perfect MCQ set brings in 15.`;
  const scrollToSection=id=>document.getElementById(id)?.scrollIntoView({behavior:"smooth",block:"start"});
  const revealPbq=async()=>{
    const result=await onUnlockPbq?.();
    if(result?.purchased)setLastUnlockedPbq(result.question||{id:result.resourceId,title:result.resourceId});
  };
  const earnMethods=[
    {title:"New learner gift",body:"Finish Academy onboarding and begin with a one-time welcome balance.",reward:`+${CIPHER_WELCOME_GRANT}`,color:"#d59632",Icon:Sparkles},
    {title:"Daily check-in",body:"Days 1–6 award 5 coins. Every seventh consecutive day awards 10.",reward:"+5 / +10",color:"#e56f65",Icon:CalendarDays,action:"refresh",actionLabel:"Check today’s status"},
    {title:"Perfect MCQ set",body:"Score 100% on at least five questions. Your first perfect set each day earns coins.",reward:"+15",color:"#7766c6",Icon:BookOpenCheck,action:"mcq",actionLabel:"Start an MCQ set"},
    {title:"Perfect Daily Challenge",body:"Answer all five Daily Challenge questions correctly.",reward:"+5",color:"#397fba",Icon:Target,action:"daily",actionLabel:"Open Daily Challenge"},
    {title:"Five-day challenge milestone",body:"Every fifth day in your Daily Challenge streak adds a bonus.",reward:"+5",color:"#288c8a",Icon:Flame,action:"daily",actionLabel:"Build your streak"},
    {title:"Friend referral",body:"When a new student joins with your code, both accounts receive the reward.",reward:"+100 each",color:"#c38d2d",Icon:Share2,action:"referrals",actionLabel:"Invite a friend"},
  ];
  return (
    <div className="cipher-vault-page">
      <section className="cipher-vault-hero">
        <div>
          <div className="cipher-vault-kicker"><CipherCoinIcon size={27}/> Your Coin Vault</div>
          <h1>Your effort has value.</h1>
          <p>Turn steady study habits into PBQ access and SecurePlus practice exam vouchers. Earn coins by learning, then choose how you want to use them.</p>
          <div className="cipher-vault-trust" aria-label="Cipher Coin rules">
            <span><ShieldCheck size={14}/> Never expires</span>
            <span><CheckCircle2 size={14}/> No cash value</span>
            <span><TrendingUp size={14}/> Readiness unchanged</span>
          </div>
          <div className="cipher-coach">
            <MascotAnimation animation="cheer" size={70} interactive hoverAnimation="dance" reactionAnimations={["cheer","surprised","dance"]} label="Cipher gives a Coin Vault tip"/>
            <span className="cipher-coach-copy"><small>Cipher’s next move</small><strong>{coachMessage}</strong></span>
          </div>
        </div>
        <aside className="cipher-wallet-balance" aria-label={`${balance} Cipher Coins available`}>
          <div className="cipher-wallet-head"><CipherCoinIcon size={28}/> Available balance</div>
          <div className="cipher-wallet-amount"><CipherCoinIcon size={62}/><strong>{balance}</strong><span className="cipher-wallet-unit">Cipher Coins<small>Ready to use</small></span></div>
          <div className="cipher-wallet-meta">
            <div><small>Lifetime earned</small><b>{Number(wallet?.lifetimeEarned||0)}</b></div>
            <div><small>PBQs revealed</small><b>{unlockedPbqCount}</b></div>
            <div><small>Exam vouchers</small><b>{Number(wallet?.examPasses||0)}</b></div>
          </div>
          <div className="cipher-wallet-goal">
            <div className="cipher-wallet-goal-head"><span>{walletGoal.label}</span><strong>{walletGoal.status}</strong></div>
            <div className="cipher-wallet-progress" role="progressbar" aria-label={walletGoal.label} aria-valuemin="0" aria-valuemax="100" aria-valuenow={walletGoal.progress}><span style={{width:`${walletGoal.progress}%`}}/></div>
          </div>
          <div className="cipher-wallet-actions">
            <button className="btn btn-primary" type="button" onClick={()=>scrollToSection("cipher-spend")}><Sparkles size={16}/> Use my coins</button>
            <button className="btn btn-ghost" type="button" onClick={onRefresh} disabled={busy}><RotateCcw size={15}/>{busy?"Refreshing...":"Refresh"}</button>
          </div>
        </aside>
      </section>

      {wallet?.error&&<Alert msg={wallet.error} type="warn" t={t}/>}

      <nav className="cipher-vault-jump" aria-label="Coin Vault sections">
        <button type="button" onClick={()=>scrollToSection("cipher-spend")}><Sparkles size={16}/> Spend coins</button>
        <button type="button" onClick={()=>scrollToSection("cipher-earn")}><TrendingUp size={16}/> Earn more</button>
        <button type="button" onClick={()=>scrollToSection("cipher-activity")}><Clock3 size={16}/> Activity</button>
      </nav>

      <section className="cipher-vault-section" id="cipher-spend">
        <div className="cipher-vault-section-head"><div><span className="cipher-section-eyebrow">Choose your reward</span><h2>Use your coins</h2></div><p>PBQ reveals are permanent. Practice exam vouchers are single-use inside SecurePlus—not official CompTIA exam vouchers.</p></div>
        <div className="cipher-spend-grid">
          <article className="cipher-spend-card pbq">
            <div className="cipher-spend-top"><div className="cipher-spend-visual"><Puzzle size={30}/></div><span className="cipher-spend-badge"><BadgeCheck size={13}/> Permanent unlock</span></div>
            <h3>Mystery PBQ reveal</h3>
            <p>Your first three reveals follow p014 → p018 → p033. Later reveals are randomly selected from PBQs you do not own.</p>
            <div className="cipher-access-meter"><div className="cipher-access-label"><span>Your balance</span><strong>{isPro?"Included with Pro":pbqGap?`${pbqGap} more needed`:"Ready to reveal"}</strong></div><div className="cipher-access-track" role="progressbar" aria-label="Progress toward a mystery PBQ" aria-valuemin="0" aria-valuemax={CIPHER_COIN_COSTS.pbq} aria-valuenow={Math.min(balance,CIPHER_COIN_COSTS.pbq)}><span style={{width:`${pbqProgress}%`}}/></div></div>
            <div className="cipher-cost-line"><span className="cipher-cost"><CipherCoinIcon size={25}/>{CIPHER_COIN_COSTS.pbq} coins</span><button className="btn btn-primary" type="button" onClick={revealPbq} disabled={busy||isPro||balance<CIPHER_COIN_COSTS.pbq||remainingPbqCount===0}>{isPro?"Included with Pro":remainingPbqCount===0?"All PBQs unlocked":pbqGap?`${pbqGap} more needed`:busy?"Revealing...":"Reveal a PBQ"}</button></div>
            {lastUnlockedPbq&&<div className="cipher-reveal-result"><MascotAnimation animation="unlock" size={58} label="Cipher celebrates the PBQ reveal"/><span><small>New PBQ revealed</small><strong>{lastUnlockedPbq.title||lastUnlockedPbq.id}</strong><button type="button" onClick={()=>onNavigate("pbq")}>Open PBQ Bank →</button></span></div>}
            {isPro&&<div className="cipher-pro-zero"><Sparkles size={13}/> Pro has every PBQ with zero coin requirements.</div>}
          </article>
          <article className="cipher-spend-card exam">
            <div className="cipher-spend-top"><div className="cipher-spend-visual"><ClipboardCheck size={30}/></div><span className="cipher-spend-badge"><Clock3 size={13}/> One full exam</span></div>
            <h3>Practice exam voucher</h3>
            <p>Run one complete timed SecurePlus practice exam. Your voucher is used only when the exam begins.</p>
            <div className="cipher-access-meter"><div className="cipher-access-label"><span>Your balance</span><strong>{isPro?"Included with Pro":examGap?`${examGap} more needed`:"Ready to exchange"}</strong></div><div className="cipher-access-track" role="progressbar" aria-label="Progress toward a practice exam voucher" aria-valuemin="0" aria-valuemax={CIPHER_COIN_COSTS.examPass} aria-valuenow={Math.min(balance,CIPHER_COIN_COSTS.examPass)}><span style={{width:`${examProgress}%`}}/></div></div>
            <div className="cipher-cost-line"><span className="cipher-cost"><CipherCoinIcon size={25}/>{CIPHER_COIN_COSTS.examPass} coins</span><button className="btn btn-primary" type="button" onClick={onBuyExamPass} disabled={busy||isPro||balance<CIPHER_COIN_COSTS.examPass}>{isPro?"Included with Pro":examGap?`${examGap} more needed`:"Get Exam Voucher"}</button></div>
            {isPro&&<div className="cipher-pro-zero"><Sparkles size={13}/> Pro runs unlimited practice exams without spending coins.</div>}
          </article>
        </div>
      </section>

      <section className="cipher-vault-section" id="cipher-earn">
        <div className="cipher-vault-section-head"><div><span className="cipher-section-eyebrow">Build your balance</span><h2>Ways to earn</h2></div><p>Rewards favour steady learning over endless grinding. Every activity has a clear limit, so the system stays fair.</p></div>
        <div className="cipher-earn-grid">
          {earnMethods.map(({title,body,reward,color,Icon,action,actionLabel})=>(
            <article className="cipher-earn-card" style={{"--earn-color":color}} key={title}>
              <span><Icon size={20}/></span><b>{reward}</b><strong>{title}</strong><p>{body}</p>
              {action&&<button className="cipher-earn-action" type="button" onClick={()=>action==="refresh"?onRefresh():onNavigate(action)} disabled={busy&&action==="refresh"}>{actionLabel}<ChevronRight size={13}/></button>}
            </article>
          ))}
        </div>
      </section>

      <section className="cipher-vault-section">
        <div className="cipher-vault-section-head"><div><span className="cipher-section-eyebrow">Earn together</span><h2>Bring a friend</h2></div><p>Referrals give both learners 100 Cipher Coins, with no limit on how many new friends you can invite.</p></div>
        <ReferralUpgradeBanner user={user} t={t} onFindOutMore={()=>onNavigate("referrals")}/>
      </section>

      <section className="cipher-vault-section" id="cipher-activity">
        <div className="cipher-vault-section-head"><div><span className="cipher-section-eyebrow">Transparent by design</span><h2>Recent activity</h2></div><p>Your ledger shows exactly why coins entered or left your wallet.</p></div>
        <div className="cipher-ledger">
          {transactions.length?transactions.slice(0,12).map(transaction=>(
            <div className="cipher-ledger-row" key={transaction.id||transaction.reference_key}>
              <span><CipherCoinIcon size={25}/></span>
              <span><strong>{cipherTransactionLabel(transaction.event_type)}</strong><small>{transaction.created_at?new Date(transaction.created_at).toLocaleString():"Recorded securely"} · Balance {Number(transaction.balance_after||0)}</small></span>
              <span className={`cipher-ledger-amount ${Number(transaction.amount)>=0?"positive":"negative"}`}>{Number(transaction.amount)>=0?"+":""}{Number(transaction.amount)||0}</span>
            </div>
          )):<div className="cipher-empty-ledger">Your first daily check-in will appear here. Return each day to build a steady balance.<div><button className="btn btn-outline" type="button" style={{marginTop:12,fontSize:12}} onClick={()=>onNavigate("daily")}>Open Daily Challenge</button></div></div>}
        </div>
      </section>
    </div>
  );
}

function ReferralUpgradeBanner({user,t,onFindOutMore}) {
  const [details,setDetails]=useState(null);
  const [error,setError]=useState("");
  const [copied,setCopied]=useState(false);
  const [loading,setLoading]=useState(false);

  useEffect(()=>{
    let active=true;
    if(!user) return;
    if(!isSupabaseConfigured)DB.saveReferralOwner(user.referralCode||makeReferralCode(user.email),user.email);
    setError("");
    setLoading(true);
    getReferralDetails()
      .then(data=>{if(active)setDetails(data);})
      .catch(err=>{if(active)setError(err.message || "Unable to load your referral link.");})
      .finally(()=>{if(active)setLoading(false);});
    return()=>{active=false;};
  },[user?.id,user?.email]);

  const code=details?.referralCode || user?.referralCode || "";
  const shareUrl=code ? `${window.location.origin}/?ref=${encodeURIComponent(code)}` : "";
  const invitedCount=details?.invitedCount || 0;

  const copyLink=async()=>{
    if(!shareUrl)return;
    try{
      await navigator.clipboard?.writeText(shareUrl);
      setCopied(true);
      capture("referral_link_copied", { source: "cipher_coin_referral", invited_count: invitedCount });
      setTimeout(()=>setCopied(false),1800);
    }catch{
      window.prompt("Copy your referral link", shareUrl);
    }
  };

  return(
    <div className="card" style={{padding:"22px 24px",marginBottom:18,borderColor:`${t.green}45`,background:`linear-gradient(135deg, ${t.green}12, ${t.accent}10 70%, ${t.surface})`}}>
      <div style={{display:"flex",gap:16,alignItems:"flex-start",justifyContent:"space-between",flexWrap:"wrap"}}>
        <div style={{flex:"1 1 260px"}}>
          <div className="label" style={{color:t.green,marginBottom:8}}>Cipher Coin referrals</div>
          <h3 style={{fontSize:22,fontWeight:900,color:t.text,marginBottom:8}}>Help a friend begin. Both earn 100.</h3>
          <p style={{fontSize:13,color:t.textSec,lineHeight:1.75,marginBottom:12}}>
            When a new student creates an account using your referral link, their wallet receives 100 Cipher Coins and yours receives 100 too.
          </p>
          <div style={{display:"flex",gap:8,flexWrap:"wrap"}}>
            <span className="chip" style={{background:`${t.green}18`,borderColor:`${t.green}55`,color:t.green}}>+100 for your friend</span>
            <span className="chip" style={{background:`${t.green}12`,borderColor:`${t.green}35`,color:t.green}}>+100 for you</span>
            <span className="chip" style={{background:`${t.accent}12`,borderColor:`${t.accent}35`,color:t.accent}}>{invitedCount} joined so far</span>
            <span className="chip" style={{background:`${t.amber}12`,borderColor:`${t.amber}35`,color:t.amber}}>One reward per new account</span>
          </div>
          {onFindOutMore&&(
            <button className="btn btn-outline" style={{fontSize:12,marginTop:14}} onClick={onFindOutMore}>
              Find out more
            </button>
          )}
        </div>
        <div style={{flex:"1 1 260px",minWidth:0}}>
          <div style={{fontSize:12,fontWeight:800,color:t.textDim,marginBottom:6}}>Your referral link</div>
          <div style={{display:"flex",gap:8,alignItems:"stretch"}}>
            <input className="input" readOnly value={loading?"Loading referral link...":error||shareUrl||"Referral setup needed"} style={{fontSize:12,fontFamily:"'JetBrains Mono',monospace"}}/>
            <button className="btn btn-primary" style={{fontSize:13,whiteSpace:"nowrap"}} onClick={copyLink} disabled={!shareUrl}>
              {copied?"Copied":"Copy"}
            </button>
          </div>
          <div style={{fontSize:12,color:t.textDim,lineHeight:1.6,marginTop:8}}>
            The signup page opens with your code already filled in. Rewards are applied once the new account is created.
          </div>
          {error&&(
            <div style={{fontSize:12,color:t.amber,lineHeight:1.6,marginTop:8}}>
              Cipher Coin referrals are waiting for database setup. Run <code>supabase/cipher-coins.sql</code> in Supabase SQL Editor.
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

