function LegalPage({type,t}) {
  const isPrivacy = type === "privacy";
  const sections = isPrivacy ? [
    {
      title:"Information we collect",
      body:"We collect account details such as your email address, authentication provider, subscription status, and practice activity so SecurePlus can save your progress and unlock the correct features.",
    },
    {
      title:"How we use information",
      body:"We use your information to provide the practice platform, authenticate your account, process subscriptions through Stripe, send account emails through Supabase or our email provider, improve the product, and respond to support requests.",
    },
    {
      title:"Payments",
      body:"Payments are handled by Stripe. SecurePlus does not store your card number. Stripe may process payment details, billing information, and subscription events according to Stripe's own privacy and security practices.",
    },
    {
      title:"Data sharing",
      body:"We share data only with service providers needed to run the site, such as Supabase, Stripe, Vercel, email delivery providers, and analytics or security tools we choose to enable. We do not sell personal information.",
    },
    {
      title:"Your choices",
      body:"You can request help, billing support, or account deletion by contacting secureplus.support@gmail.com. If you delete your account, saved profile and practice data may be removed according to our database retention settings.",
    },
  ] : [
    {
      title:"Use of SecurePlus",
      body:"SecurePlus provides CompTIA Security+ practice content for study and preparation. You agree to use the site lawfully and not abuse, scrape, resell, reverse engineer, or interfere with the platform.",
    },
    {
      title:"Accounts",
      body:"You are responsible for keeping your login information secure. You should use a real email address so you can verify your account, reset your password, and receive account notices.",
    },
    {
      title:"Subscriptions",
      body:"Paid access is billed through Stripe. Subscription features are unlocked only when Stripe and Supabase show an active or trialing subscription. You can cancel through the billing portal when available or by contacting support.",
    },
    {
      title:"Educational content",
      body:"SecurePlus is an independent study tool and is not affiliated with or endorsed by CompTIA. Exam names and trademarks belong to their respective owners. Practice questions are for learning and are not real exam questions.",
    },
    {
      title:"Limitations",
      body:"We work to keep the site accurate and available, but we do not guarantee exam results, uninterrupted service, or error-free content. Use SecurePlus as one part of your broader study plan.",
    },
  ];

  return(
    <div style={{padding:"28px 24px",maxWidth:780,margin:"0 auto"}}>
      <div className="page-title-row">
        <NavGlyph type={isPrivacy ? "privacy" : "terms"} active/>
        <h2 style={{fontSize:24,fontWeight:800,color:t.text}}>
          {isPrivacy ? "Privacy Policy" : "Terms & Conditions"}
        </h2>
      </div>
      <p style={{color:t.textSec,fontSize:14,marginBottom:20}}>
        Last updated: May 9, 2026. Questions? Contact{" "}
        <a href="mailto:secureplus.support@gmail.com" style={{color:t.accent,fontWeight:700}}>secureplus.support@gmail.com</a>.
      </p>

      <div style={{display:"flex",flexDirection:"column",gap:12}}>
        {sections.map(section=>(
          <section key={section.title} className="card" style={{padding:"18px 20px"}}>
            <h3 style={{fontSize:15,fontWeight:700,color:t.text,marginBottom:6}}>{section.title}</h3>
            <p style={{fontSize:13,color:t.textSec,lineHeight:1.75}}>{section.body}</p>
          </section>
        ))}
      </div>
    </div>
  );
}

function AccountSupportPage({user,t,onDeleteAccount,onCancelMembership,onNavigate,billingLoading=false}) {
  const isPro=user?.tier==="pro";
  const hasPaidSubscription=["active","trialing"].includes(user?.subscriptionStatus || "");
  const isRenewalCancelled=Boolean(user?.subscriptionCancelAtPeriodEnd);
  const subscriptionEndLabel=formatSubscriptionDate(user?.subscriptionCurrentPeriodEnd);
  const cards=[
    {title:"Contact support",body:"Email us for account, billing, content, or technical issues.",color:t.accent,Icon:MessageSquareWarning,action:"Email support",href:`mailto:${SUPPORT_EMAIL}`},
    {title:"Privacy policy",body:"See what account, payment, and practice data SecurePlus uses.",color:t.green,Icon:LockKeyhole,action:"Open privacy",view:"privacy"},
    {title:"Terms & Conditions",body:"Review subscription, content, and acceptable-use terms.",color:t.amber,Icon:FileText,action:"Open terms",view:"terms"},
  ];
  return(
    <div className="account-support-page">
      <section className="card account-support-hero">
        <div>
          <div className="label" style={{color:t.accent}}>Account, legal, and support</div>
          <h2>Manage the serious account stuff in one place.</h2>
          <p>Use this page for support, legal documents, cancellation, and account deletion. Deletion still requires secure email verification before anything is removed.</p>
          <div className="account-support-profile">
            <span><UserRound size={16}/>{user?.email||"Signed-in account"}</span>
            <span><ShieldCheck size={16}/>{isRenewalCancelled?"Pro until period end":isPro?"Pro active":"Free plan"}</span>
          </div>
        </div>
        <div className="account-support-safe-card">
          <ShieldCheck size={30}/>
          <strong>Deletion is protected</strong>
          <span>The red button sends a secure email link first. The email alone does not delete the account.</span>
        </div>
      </section>

      <section className="account-support-grid">
        {cards.map(card=>(
          <article className="card account-support-card" style={{"--support-color":card.color}} key={card.title}>
            <span><card.Icon size={22}/></span>
            <h3>{card.title}</h3>
            <p>{card.body}</p>
            {card.href?(
              <a className="btn btn-outline" href={card.href}>{card.action}</a>
            ):(
              <button className="btn btn-outline" type="button" onClick={()=>onNavigate(card.view)}>{card.action}</button>
            )}
          </article>
        ))}
      </section>

      <section className="card account-danger-zone">
        <div>
          <div className="label" style={{color:t.red}}>Account controls</div>
          <h3>Billing and deletion</h3>
          <p>
            {hasPaidSubscription
              ? isRenewalCancelled
                ? `Your renewal is already cancelled. You will not be billed again${subscriptionEndLabel ? `, and Pro access remains until ${subscriptionEndLabel}` : ""}.`
                : `Cancel renewal if you only want to stop the next bill. Your Pro access remains until the current paid period ends${subscriptionEndLabel ? ` (${subscriptionEndLabel})` : ""}.`
              : "No active Stripe membership is linked to this account. Delete account only if you want saved learning data removed too."}
          </p>
        </div>
        <div className="account-danger-actions">
          <button className="btn btn-outline" type="button" onClick={onCancelMembership} disabled={billingLoading||!hasPaidSubscription||isRenewalCancelled}>
            {isRenewalCancelled?"Renewal already cancelled":billingLoading?"Cancelling renewal...":"Cancel renewal"}
          </button>
          <button className="btn btn-danger" type="button" onClick={onDeleteAccount}>
            Delete account
          </button>
        </div>
      </section>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// ONBOARDING
// ═══════════════════════════════════════════════════════════════
function OnboardingModal({user,wallet,t,onClose,onWallet,onPbq,onRefreshWallet}) {
  const [step,setStep]=useState(0);
  const [spendPlan,setSpendPlan]=useState([]);
  const plannedCost=spendPlan.reduce((sum,item)=>sum+CIPHER_COIN_COSTS[item],0);
  const planRemaining=CIPHER_WELCOME_GRANT-plannedCost;
  const planCounts=spendPlan.reduce((counts,item)=>({...counts,[item]:(counts[item]||0)+1}),{});
  const addToPlan=item=>{
    const cost=CIPHER_COIN_COSTS[item];
    if(cost>planRemaining)return;
    setSpendPlan(current=>[...current,item]);
  };
  const slides=[
    {
      id:"gift",
      Icon:Sparkles,
      animation:"dance",
      title:`A welcome gift for ${user?.name ? user.name.split(" ")[0] : "you"}`,
      body:`Your Academy account begins with ${CIPHER_WELCOME_GRANT} Cipher Coins. They help you try locked practice through steady effort, and they never reduce your readiness score.`,
    },
    {
      id:"earn",
      Icon:CalendarDays,
      animation:"cheer",
      title:"Study habits mint more",
      body:"The loop is simple: Daily Challenge, earn coins, unlock a PBQ or exam voucher, read the report card, then return tomorrow.",
    },
    {
      id:"spend",
      Icon:CircleDollarSign,
      animation:"thinking",
      title:"Try your first coin plan",
      body:"Tap the choices to explore what your welcome gift can unlock. This small planner does not spend real coins.",
    },
    {
      id:"ready",
      Icon:ShieldCheck,
      animation:"unlock",
      title:"Your Coin Vault is ready",
      body:"Use coins if you have time. Use Pro if your exam is soon. Pro unlocks every PBQ and practice exam with zero coin requirements.",
    },
  ];
  const slide=slides[step];
  const last=step===slides.length-1;
  const walletReady=wallet?.status==="ready";
  const walletError=wallet?.status==="error";
  const liveBalance=Number(wallet?.balance||0);

  return(
    <div className="onboarding-overlay cipher-walkthrough-overlay" role="dialog" aria-modal="true" aria-label="Cipher Coin walkthrough">
      <div className="onboarding-modal card cipher-walkthrough">
        <div className="cipher-walkthrough-top">
          <span>Coin tour · {step+1}/{slides.length}</span>
          <button className="btn btn-ghost" type="button" onClick={onClose}>Skip tour</button>
        </div>

        <div className="cipher-walkthrough-hero">
          <MascotAnimation animation={slide.animation} size={104} interactive hoverAnimation="cheer" reactionAnimations={["surprised","cheer","dance"]} label="Cipher guides the Coin walkthrough"/>
          <div>
            <div className="cipher-walkthrough-kicker"><slide.Icon size={15}/> Cipher Coin guide</div>
            <h2>{slide.title}</h2>
            <p>{slide.body}</p>
          </div>
        </div>

        <div className="cipher-walkthrough-stage">
          {slide.id==="gift"&&(
            <div className="cipher-welcome-gift">
              <div className="cipher-welcome-coins" aria-hidden="true"><CipherCoinIcon size={54}/><CipherCoinIcon size={64}/><CipherCoinIcon size={50}/></div>
              <div>
                <small>Welcome grant</small>
                <strong>+{CIPHER_WELCOME_GRANT}</strong>
                <span>
                  {walletReady
                    ? `Your saved wallet: ${liveBalance} coins${liveBalance>CIPHER_WELCOME_GRANT?" including today’s activity":""}`
                    : walletError
                      ? "We could not verify the saved grant yet. Your balance has not been guessed."
                      : "Securing the grant in your saved wallet..."}
                </span>
                {walletError&&<button className="btn btn-outline" type="button" style={{marginTop:9,fontSize:11}} onClick={onRefreshWallet}>Retry wallet check</button>}
              </div>
            </div>
          )}

          {slide.id==="earn"&&(
            <div className="cipher-walkthrough-earn">
              {[
                ["Open SecurePlus daily","+5, or +10 every 7th day",CalendarDays],
                ["Perfect an MCQ set","+15 once per day",BookOpenCheck],
                ["Perfect the Daily Challenge","+5, with streak bonuses",Target],
                ["Refer a new learner","+100 for both learners",Share2],
              ].map(([title,detail,Icon])=><div key={title}><Icon size={18}/><span><strong>{title}</strong><small>{detail}</small></span></div>)}
            </div>
          )}

          {slide.id==="spend"&&(
            <div className="cipher-plan-builder">
              <div className="cipher-plan-budget"><span>Welcome budget</span><strong>{planRemaining}</strong><small>coins remaining</small></div>
              <div className="cipher-plan-actions">
                <button type="button" onClick={()=>addToPlan("pbq")} disabled={planRemaining<CIPHER_COIN_COSTS.pbq}><Puzzle size={20}/><span><strong>Mystery PBQ</strong><small>{CIPHER_COIN_COSTS.pbq} coins · {planCounts.pbq||0} planned</small></span></button>
                <button type="button" onClick={()=>addToPlan("examPass")} disabled={planRemaining<CIPHER_COIN_COSTS.examPass}><ClipboardCheck size={20}/><span><strong>Practice exam voucher</strong><small>{CIPHER_COIN_COSTS.examPass} coins · {planCounts.examPass||0} planned</small></span></button>
              </div>
              <div className="cipher-plan-note"><Sparkles size={15}/><span>The first three PBQ reveals are p014, p018, and p033. Later reveals are random.</span>{spendPlan.length>0&&<button type="button" onClick={()=>setSpendPlan([])}><RotateCcw size={13}/> Reset</button>}</div>
            </div>
          )}

          {slide.id==="ready"&&(
            <div className="cipher-ready-grid">
              <button type="button" onClick={()=>{onClose();onWallet?.();}}><CipherCoinIcon size={42}/><span><strong>Open Coin Vault</strong><small>See your balance, rewards, and redemptions.</small></span><ChevronRight size={18}/></button>
              <button type="button" onClick={()=>{onClose();onPbq?.();}}><Puzzle size={25}/><span><strong>Visit PBQ Simulator</strong><small>Preview a PBQ or see your revealed collection.</small></span><ChevronRight size={18}/></button>
            </div>
          )}
        </div>

        <div style={{display:"flex",gap:7,marginBottom:20}}>
          {slides.map((_,i)=>(
            <div key={i} className="cipher-walkthrough-progress" data-active={i<=step}/>
          ))}
        </div>
        <div className="cipher-walkthrough-actions">
          <button className="btn btn-ghost" onClick={()=>setStep(s=>Math.max(0,s-1))} disabled={step===0}>
            Back
          </button>
          <button className="btn btn-primary" onClick={()=>last?onClose():setStep(s=>s+1)}>
            {last ? "Finish tour" : "Continue"}
          </button>
        </div>
      </div>
    </div>
  );
}

function ProWelcomeModal({user,t,onClose,onNavigate}) {
  const [selected,setSelected]=useState("pbq");
  const firstName=user?.name ? user.name.split(" ")[0] : "there";
  const choices=[
    {
      id:"pbq",
      title:"Start PBQ practice",
      body:"Open the full PBQ simulator with no coin spending or preview limits.",
      Icon:Puzzle,
      color:t.accent,
      view:"pbq",
      cta:"Open PBQs",
    },
    {
      id:"exam",
      title:"Run Exam Mode",
      body:"Use timed mixed practice and get a report card when you finish.",
      Icon:ClipboardCheck,
      color:t.green,
      view:"exam",
      cta:"Start Exam Mode",
    },
    {
      id:"deep-dives",
      title:"Review weak concepts",
      body:"Use Concept Deep Dives when Smart Review points to a weak topic.",
      Icon:BookOpenCheck,
      color:t.amber,
      view:"deep-dives",
      cta:"Open Deep Dives",
    },
  ];
  const active=choices.find(choice=>choice.id===selected)||choices[0];
  const finish=(view=active.view)=>{
    capture("pro_welcome_completed", { selected: view });
    onClose?.();
    onNavigate?.(view);
  };

  return(
    <div className="onboarding-overlay cipher-walkthrough-overlay" role="dialog" aria-modal="true" aria-labelledby="pro-welcome-title">
      <div className="onboarding-modal card pro-welcome">
        <div className="pro-welcome-top">
          <span><Sparkles size={14}/> Pro unlocked</span>
          <button className="btn btn-ghost" type="button" onClick={()=>{capture("pro_welcome_skipped", { tier:user?.tier || "unknown" });onClose?.();}}>Skip</button>
        </div>

        <div className="pro-welcome-hero">
          <MascotAnimation animation="cheer" size={112} interactive hoverAnimation="dance" reactionAnimations={["cheer","dance","unlock"]} label="Cipher welcomes you to Pro"/>
          <div>
            <h2 id="pro-welcome-title">Welcome to Pro, {firstName}.</h2>
            <p>
              Your Pro Academy Pass is active. PBQs, Exam Mode, Smart Review, report cards, and Concept Deep Dives now open with zero Cipher Coin requirements.
            </p>
          </div>
        </div>

        <div className="pro-welcome-mini">
          <ShieldCheck size={18}/>
          <span><strong>{PRO_ACADEMY_PASS_TRUST}</strong> Pro gives convenience, not shortcuts. The best first step is one focused practice action.</span>
        </div>

        <div className="pro-welcome-grid" aria-label="Choose your first Pro action">
          {choices.map(({id,title,body,Icon,color})=>(
            <button
              key={id}
              type="button"
              className={`pro-welcome-choice ${selected===id?"selected":""}`}
              style={{"--pro-choice-color":color}}
              onClick={()=>setSelected(id)}
              aria-pressed={selected===id}
            >
              <span className="pro-welcome-choice-icon"><Icon size={22}/></span>
              <strong>{title}</strong>
              <span>{body}</span>
            </button>
          ))}
        </div>

        <div className="pro-welcome-actions">
          <button className="btn btn-ghost" type="button" onClick={onClose}>Maybe later</button>
          <button className="btn btn-primary" type="button" onClick={()=>finish()}>
            {active.cta} <ChevronRight size={17}/>
          </button>
        </div>
      </div>
    </div>
  );
}

function DiagnosticQuiz({user,t,onComplete}) {
  const questions=useMemo(()=>buildDiagnosticQuestions(),[]);
  const [index,setIndex]=useState(0);
  const [selected,setSelected]=useState(null);
  const [submitted,setSubmitted]=useState(false);
  const [results,setResults]=useState([]);
  const [saving,setSaving]=useState(false);
  const [showSummary,setShowSummary]=useState(false);
  const current=questions[index];
  const correctCount=results.filter(r=>r.correct).length;
  const done=showSummary&&questions.length>0&&results.length===questions.length;
  const chapterResults=CHAPTERS.map(ch=>{
    const rows=results.filter(r=>r.ch===ch.id);
    return {chapter:ch,total:rows.length,correct:rows.filter(r=>r.correct).length,missed:rows.filter(r=>!r.correct)};
  }).filter(item=>item.total>0);
  const weakChapters=chapterResults.filter(item=>item.correct<item.total).sort((a,b)=>(a.correct/a.total)-(b.correct/b.total));

  const submit=()=>{
    if(selected===null||!current)return;
    const correct=selected===current.correct;
    const attempt={
      qid:current.id,
      correct,
      selected,
      title:current.q.slice(0,60),
      ch:current.ch,
      domain:CHAPTERS.find(ch=>ch.id===current.ch)?.title||"",
      topic:current.topic,
      difficulty:current.difficulty,
      mcq:true,
      diagnostic:true,
      createdAt:new Date().toISOString()
    };
    setResults(prev=>[...prev,attempt]);
    playAnswerSound(correct);
    capture("diagnostic_question_answered", { question_id: current.id, chapter: current.ch, topic: current.topic, correct });
    setSubmitted(true);
  };

  const next=()=>{
    if(index<questions.length-1){
      setIndex(i=>i+1);
      setSelected(null);
      setSubmitted(false);
    }
  };

  const finish=async()=>{
    setSaving(true);
    await onComplete(results);
    setSaving(false);
  };

  if(done) return (
    <div style={{minHeight:"100vh",background:t.bg,padding:"28px 20px",display:"grid",placeItems:"center"}}>
      <div className="card" style={{width:"100%",maxWidth:720,padding:"26px"}}>
        <div className="label" style={{color:t.accent,marginBottom:8}}>Baseline complete</div>
        <h2 style={{fontSize:28,color:t.text,marginBottom:8}}>Your Smart Review is now personalised.</h2>
        <p style={{fontSize:14,color:t.textSec,lineHeight:1.7,marginBottom:18}}>
          You answered {correctCount}/{questions.length}. SecurePlus will use these results to bring missed concepts back earlier in MCQ Practice.
        </p>
        <div style={{display:"grid",gap:10,marginBottom:18}}>
          {chapterResults.map(item=>{
            const pct=Math.round((item.correct/item.total)*100);
            const color=pct>=80?t.green:pct>=50?t.amber:t.red;
            return(
              <div key={item.chapter.id} style={{padding:"12px 14px",border:`1px solid ${t.border}`,borderRadius:8,background:t.panel}}>
                <div style={{display:"flex",justifyContent:"space-between",gap:10,alignItems:"center",marginBottom:6}}>
                  <div style={{display:"flex",alignItems:"center",gap:8,fontSize:13,fontWeight:900,color:t.text}}>
                    <ChapterIcon id={item.chapter.id} size={22}/> Ch.{item.chapter.id}: {item.chapter.title}
                  </div>
                  <span style={{fontSize:13,fontWeight:900,color}}>{item.correct}/{item.total}</span>
                </div>
                <ProgBar v={pct} c={color} h={7}/>
              </div>
            );
          })}
        </div>
        <div className="card" style={{padding:"14px 16px",background:`${t.accent}08`,borderColor:`${t.accent}30`,boxShadow:"none",marginBottom:18}}>
          <div style={{fontWeight:900,color:t.text,fontSize:14,marginBottom:4}}>Recommended first move</div>
          <div style={{fontSize:13,color:t.textSec,lineHeight:1.65}}>
            {weakChapters.length
              ? `Start Smart Review with ${weakChapters.slice(0,2).map(item=>`Chapter ${item.chapter.id}`).join(" and ")}. Missed diagnostic questions will be prioritised.`
              : "Strong baseline. Start Smart Review to keep these topics fresh over time."}
          </div>
        </div>
        <button className="btn btn-primary" style={{width:"100%",justifyContent:"center",padding:"12px"}} disabled={saving} onClick={finish}>
          {saving?"Saving baseline...":"Start Smart Review →"}
        </button>
      </div>
    </div>
  );

  if(!current) return null;

  return (
    <div style={{minHeight:"100vh",background:t.bg,padding:"28px 20px",display:"grid",placeItems:"center"}}>
      <div className="card" style={{width:"100%",maxWidth:760,padding:"24px"}}>
        <div style={{display:"flex",justifyContent:"space-between",gap:12,alignItems:"center",marginBottom:16,flexWrap:"wrap"}}>
          <div>
            <div className="label" style={{color:t.accent,marginBottom:6}}>New account baseline</div>
            <h2 style={{fontSize:24,color:t.text}}>Mini mock test</h2>
            <div style={{fontSize:13,color:t.textSec}}>5 short, beginner-friendly questions · one per chapter.</div>
          </div>
          <span className="chip" style={{background:`${t.accent}10`,borderColor:`${t.accent}35`,color:t.accent}}>Question {index+1}/{questions.length}</span>
        </div>
        <div className="top-progress" aria-hidden="true"><span style={{width:`${((index+1)/questions.length)*100}%`}}/></div>
        <div className="card question-card" style={{padding:"20px 22px",marginBottom:16,background:t.panel}}>
          <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:12}}>
            <ChBadge chId={current.ch} t={t}/>
            <DiffBadge d={current.difficulty} t={t}/>
            <span className="chip meta-chip" style={{fontSize:11}}>{current.topic}</span>
          </div>
          <div className="question-text" style={{fontSize:17,lineHeight:1.7,color:t.text}}>
            <QuestionStemText text={current.q} t={t}/>
          </div>
        </div>
        <div style={{display:"grid",gap:9,marginBottom:16}}>
          {current.opts.map((opt,i)=>{
            let cls="opt";
            if(submitted){cls+=" done"; if(i===current.correct)cls+=" ok"; else if(i===selected&&i!==current.correct)cls+=" bad";}
            else if(selected===i)cls+=" sel";
            const showSelectedWrongFeedback=submitted&&i===selected&&i!==current.correct;
            return(
              <button key={i} type="button" className={cls} style={{textAlign:"left"}} onClick={()=>!submitted&&setSelected(i)}>
                <span className="opt-ltr">{String.fromCharCode(65+i)}</span>
                <div className="option-body">
                  <span className="option-text" style={{fontSize:14,flex:1,lineHeight:1.55,color:t.text}}><GlossaryText text={opt} t={t}/></span>
                  {showSelectedWrongFeedback&&(
                    <div className="option-inline-feedback">
                      <strong>Why this choice is wrong:</strong>
                      <GlossaryText text={getWrongOptionFeedback(current, i)} t={t}/>
                    </div>
                  )}
                </div>
              </button>
            );
          })}
        </div>
        {!submitted?(
          <button className="btn btn-primary" style={{width:"100%",justifyContent:"center"}} disabled={selected===null} onClick={submit}>Submit Answer</button>
        ):(
          <>
            <div className="card answer-feedback" style={{padding:"14px 16px",marginBottom:12,borderColor:selected===current.correct?`${t.green}42`:`${t.red}42`,background:selected===current.correct?`${t.green}08`:`${t.red}08`,boxShadow:"none"}}>
              <MCQFeedbackVerdict correct={selected===current.correct} t={t}/>
              <p style={{fontSize:13,color:t.textSec,lineHeight:1.65,marginTop:7}}><GlossaryText text={current.exp} t={t}/></p>
            </div>
            <button className="btn btn-primary" style={{width:"100%",justifyContent:"center"}} onClick={index<questions.length-1?next:()=>setShowSummary(true)}>
              {index<questions.length-1?"Next Question →":"See Baseline →"}
            </button>
          </>
        )}
      </div>
    </div>
  );
}

function PasswordUpdateView({t,onDone}) {
  const [form,setForm]=useState({pass:"",confirm:""});
  const [err,setErr]=useState("");
  const [ok,setOk]=useState("");
  const [loading,setLoading]=useState(false);
  const set=k=>e=>setForm(f=>({...f,[k]:e.target.value}));
  const submit=async()=>{
    setErr("");setOk("");
    if(form.pass!==form.confirm){setErr("Passwords do not match.");return;}
    const passwordIssue=getPasswordIssue(form.pass);
    if(passwordIssue){setErr(passwordIssue);return;}
    setLoading(true);
    try{
      const { error } = await supabase.auth.updateUser({ password: form.pass });
      if(error) throw error;
      setOk("Password updated. You can continue to SecurePlus.");
      setTimeout(onDone,700);
    }catch(e){
      setErr(e.message||"Unable to update password.");
    }finally{
      setLoading(false);
    }
  };

  return(
    <div style={{minHeight:"100vh",display:"grid",placeItems:"center",padding:24}}>
      <div className="card" style={{width:"100%",maxWidth:430,padding:"28px 28px"}}>
        <div style={{display:"inline-flex",alignItems:"center",gap:10,padding:"7px 11px",border:`1px solid ${t.border}`,borderRadius:8,background:t.panel,marginBottom:20}}>
          <BrandMark size={28}/>
          <span style={{fontWeight:800,color:t.text}}>SecurePlus</span>
        </div>
        <h1 style={{fontSize:26,color:t.text,marginBottom:8}}>Set a new password</h1>
        <p style={{fontSize:13,color:t.textSec,lineHeight:1.6,marginBottom:18}}>
          Use 8+ characters with uppercase, lowercase, a number, and a special character.
        </p>
        <Alert msg={err} type="error" t={t}/>
        <Alert msg={ok} type="success" t={t}/>
        <div style={{display:"flex",flexDirection:"column",gap:14}}>
          <div><label style={{display:"block",fontSize:13,fontWeight:500,marginBottom:5,color:t.text}}>New Password</label>
            <input className="input" type="password" placeholder="At least 8 characters" value={form.pass} onChange={set("pass")} onKeyDown={e=>e.key==="Enter"&&submit()}/></div>
          <div><label style={{display:"block",fontSize:13,fontWeight:500,marginBottom:5,color:t.text}}>Confirm Password</label>
            <input className="input" type="password" placeholder="••••••••" value={form.confirm} onChange={set("confirm")} onKeyDown={e=>e.key==="Enter"&&submit()}/></div>
          <button className="btn btn-primary" style={{width:"100%",justifyContent:"center",padding:"11px"}} onClick={submit} disabled={loading}>
            {loading?"Updating...":"Update Password"}
          </button>
        </div>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// APP ROOT
// ═══════════════════════════════════════════════════════════════
const APP_HISTORY_VIEWS = Object.freeze(new Set([
  "dashboard",
  "mcq",
  "pbq",
  "exam",
  "daily",
  "coins",
  "pricing",
  "auth",
  "objectives",
  "flashcards",
  "deep-dives",
  "account",
  "privacy",
  "terms",
  "feedback",
  "question-admin",
  "mascot-admin",
  "referrals",
]));

function normalizeAppHistoryView(view) {
  return APP_HISTORY_VIEWS.has(view) ? view : "dashboard";
}

function hasCheckoutReturnParams(search=window.location.search) {
  const params=new URLSearchParams(search);
  return Boolean(params.get("checkout") || params.get("billing") || params.get("session_id"));
}

function buildAppHistoryUrl(view,setId=null) {
  if(typeof window==="undefined")return "/";
  const safeView=normalizeAppHistoryView(view);
  const params=new URLSearchParams();
  if(safeView!=="dashboard")params.set("view",safeView);
  if(safeView==="flashcards"&&setId)params.set("set",setId);
  const query=params.toString();
  return `/${query?`?${query}`:""}`;
}

function readAppHistoryState() {
  if(typeof window==="undefined")return {view:"dashboard",flashcardSetId:null};
  const params=new URLSearchParams(window.location.search);
  const checkout=params.get("checkout");
  const view=checkout==="cancelled" ? "pricing" : normalizeAppHistoryView(params.get("view")||"dashboard");
  return {
    view,
    flashcardSetId:view==="flashcards" ? params.get("set") : null,
  };
}

function scrollSecurePlusPageToTop({behavior="auto"}={}) {
  if(typeof window==="undefined")return;
  const reduceMotion=window.matchMedia?.("(prefers-reduced-motion: reduce)")?.matches;
  const scrollBehavior=reduceMotion?"auto":behavior;
  const reset=()=>{
    document.querySelectorAll(".app-main").forEach(node=>{
      if(typeof node.scrollTo==="function")node.scrollTo({top:0,left:0,behavior:scrollBehavior});
      else node.scrollTop=0;
    });
    window.scrollTo({top:0,left:0,behavior:scrollBehavior});
    document.documentElement.scrollTop=0;
    document.body.scrollTop=0;
  };
  window.requestAnimationFrame(()=>window.requestAnimationFrame(reset));
}

export default function App() {
  const initialParams=new URLSearchParams(window.location.search);
  const urlDeepDiveRequest=initialParams.get("view")==="deep-dives";
  const urlFlashcardsRequest=initialParams.get("view")==="flashcards";
  const urlFlashcardSetRequest=urlFlashcardsRequest?initialParams.get("set"):"";
  const urlPricingRequest=initialParams.get("view")==="pricing"||initialParams.get("checkout")==="cancelled";
  const focusAcronymLibrary=Boolean(urlDeepDiveRequest&&initialParams.get("focus")==="acronyms");
  const devDeepDivePreview=Boolean(import.meta.env.DEV&&initialParams.get("preview")==="deep-dives");
  const devCoinPreview=Boolean(import.meta.env.DEV&&initialParams.get("preview")==="coins");
  const [darkMode,setDarkMode]=useState(()=>{
    try{
      const stored=window.localStorage?.getItem(THEME_STORAGE_KEY);
      if(stored==="dark")return true;
      if(stored==="light")return false;
      return window.matchMedia?.("(prefers-color-scheme: dark)")?.matches||false;
    }catch{return false;}
  });
  const [sidebarHidden,setSidebarHidden]=useState(()=>{
    try{return window.localStorage?.getItem("secureplus-sidebar-hidden")==="true";}catch{return false;}
  });
  const [mobileNavOpen,setMobileNavOpen]=useState(false);
  const [user,setUser]=useState(null);
  const [loading,setLoading]=useState(true);
  const [view,setView]=useState(()=>focusAcronymLibrary||urlFlashcardsRequest?"flashcards":urlDeepDiveRequest||devDeepDivePreview?"deep-dives":urlPricingRequest?"pricing":devCoinPreview?"coins":"dashboard");
  const [attempts,setAttempts]=useState([]);
  const [starred,setStarred]=useState([]);
  const [pbqQ,setPbqQ]=useState(null);
  const [showDaily,setShowDaily]=useState(false);
  const [billingLoading,setBillingLoading]=useState(false);
  const [passwordRecovery,setPasswordRecovery]=useState(false);
  const [showDiagnostic,setShowDiagnostic]=useState(false);
  const [showOnboarding,setShowOnboarding]=useState(false);
  const [showProWelcome,setShowProWelcome]=useState(false);
  const [authStartMode,setAuthStartMode]=useState("login");
  const [authRequestId,setAuthRequestId]=useState(0);
  const [showTrialExpiredPrompt,setShowTrialExpiredPrompt]=useState(false);
  const [referralClaimPrompt,setReferralClaimPrompt]=useState(null);
  const [accountDeletion,setAccountDeletion]=useState(readAccountDeletionState);
  const [questionReport,setQuestionReport]=useState(null);
  const [questionBankVersion,setQuestionBankVersion]=useState(0);
  const [adminQuestionTarget,setAdminQuestionTarget]=useState(null);
  const [practiceFocusMode,setPracticeFocusMode]=useState(false);
  const [mascotPlacements,setMascotPlacements]=useState([]);
  const [remotePbqBank,setRemotePbqBank]=useState([]);
  const [pbqBankLoading,setPbqBankLoading]=useState(Boolean(isSupabaseConfigured));
  const [pbqBankError,setPbqBankError]=useState(null);
  const [smartReviewRequest,setSmartReviewRequest]=useState(null);
  const [deepDiveRequest,setDeepDiveRequest]=useState(null);
  const [flashcardSetRequest,setFlashcardSetRequest]=useState(()=>urlFlashcardSetRequest||null);
  const [assistantFlashcardSet,setAssistantFlashcardSet]=useState(null);
  const [flashcardAuthPrompt,setFlashcardAuthPrompt]=useState(null);
  const [achievementUnlocks,setAchievementUnlocks]=useState([]);
  const [coinWallet,setCoinWallet]=useState(()=>({...emptyCipherWallet(),status:"idle"}));
  const [coinBusy,setCoinBusy]=useState(false);
  const [coinRewardToast,setCoinRewardToast]=useState(null);
  const historyReadyRef=useRef(false);
  const suppressNextHistoryPushRef=useRef(false);
  const lastPageKeyRef=useRef(null);

  const t=darkMode?THEMES.dark:THEMES.light;
  const isRootUser=normalizeEmail(user?.email)===normalizeEmail(SUPPORT_EMAIL);
  const liveMcqBank=useMemo(()=>MCQ_BANK,[questionBankVersion]);
  const livePbqBank=useMemo(
    ()=>isSupabaseConfigured?mergeRemotePBQBanks(PBQ_BANK,remotePbqBank):PBQ_BANK,
    [remotePbqBank,questionBankVersion]
  );
  const useLocalPbqFallback=Boolean(
    isSupabaseConfigured
    && user?.tier==="pro"
    && !pbqBankLoading
    && (pbqBankError || remotePbqBank.length<PBQ_BANK.length)
  );

  useEffect(()=>{
    try{
      window.localStorage?.setItem(THEME_STORAGE_KEY,darkMode?"dark":"light");
      document.documentElement.dataset.theme=darkMode?"dark":"light";
    }catch{}
  },[darkMode]);
  useEffect(()=>{
    if(view==="achievements")setView("dashboard");
  },[view]);
  useEffect(()=>{
    setMobileNavOpen(false);
  },[view]);
  useEffect(()=>{
    const pageKey=showDiagnostic
      ?"diagnostic"
      :showOnboarding
        ?"onboarding"
        :passwordRecovery
          ?"password-recovery"
          :pbqQ?.id
            ?`pbq:${pbqQ.id}`
            :`view:${view}`;
    if(lastPageKeyRef.current===null){
      lastPageKeyRef.current=pageKey;
      return;
    }
    if(lastPageKeyRef.current!==pageKey){
      lastPageKeyRef.current=pageKey;
      scrollSecurePlusPageToTop({behavior:"auto"});
    }
  },[passwordRecovery,pbqQ?.id,showDiagnostic,showOnboarding,view]);
  const effectiveAssistantFlashcardSet=useMemo(()=>{
    if(user?.tier!=="pro")return assistantFlashcardSet;
    if(assistantFlashcardSet?.cards?.length)return assistantFlashcardSet;
    const weakContext=buildCipherAssistantContext(attempts,"flashcards");
    return buildCipherWeakFlashcardSet(weakContext)||buildCipherStarterFlashcardSet();
  },[assistantFlashcardSet,attempts,user?.tier]);

  const importPendingGuestSmartReview=useCallback(async(account,existingAttempts=[])=>{
    const pending=await takePendingGuestSmartReview();
    if(!pending.length||!account)return existingAttempts;
    try{
      if(account.authProvider==="supabase"){
        await Promise.all(pending.map(attempt=>saveSupabaseAttempt(account.id,attempt,{throwOnError:true})));
      }else{
        for(const attempt of [...pending].reverse())await DB.saveAttempt(account.email,attempt);
      }
      capture("guest_smart_review_imported", {
        attempt_count:pending.length,
        chapter_count:new Set(pending.map(attempt=>attempt.ch).filter(Boolean)).size,
      });
      return [...pending].sort((a,b)=>new Date(b.createdAt||0)-new Date(a.createdAt||0)).concat(existingAttempts);
    }catch(error){
      await savePendingGuestSmartReview(pending);
      console.warn("Unable to attach guest Smart Review results",error);
      return existingAttempts;
    }
  },[]);

  useEffect(()=>{
    try{window.localStorage?.setItem("secureplus-sidebar-hidden",sidebarHidden?"true":"false");}catch{}
  },[sidebarHidden]);

  useEffect(()=>{
    const handlePopState=()=>{
      const next=readAppHistoryState();
      suppressNextHistoryPushRef.current=true;
      setFlashcardSetRequest(next.flashcardSetId);
      setView(next.view);
    };
    window.addEventListener("popstate",handlePopState);
    return()=>window.removeEventListener("popstate",handlePopState);
  },[]);

  useEffect(()=>{
    if(typeof window==="undefined"||hasCheckoutReturnParams())return;
    const nextUrl=buildAppHistoryUrl(view,flashcardSetRequest);
    const currentUrl=`${window.location.pathname}${window.location.search}`;
    if(!historyReadyRef.current){
      historyReadyRef.current=true;
      if(currentUrl!==nextUrl)window.history.replaceState({secureplusView:view},"",nextUrl);
      return;
    }
    if(suppressNextHistoryPushRef.current){
      suppressNextHistoryPushRef.current=false;
      return;
    }
    if(currentUrl!==nextUrl)window.history.pushState({secureplusView:view},"",nextUrl);
  },[view,flashcardSetRequest]);

  useEffect(()=>{
    if(user) identifyUser(user);
  },[user]);

  const refreshQuestionBankOverrides=useCallback(async()=>{
    if(!isSupabaseConfigured)return;
    try{
      const { data, error } = await supabase
        .from("question_overrides")
        .select("question_kind,question_id,action,payload,status,sort_order,updated_at")
        .eq("status","active");
      if(error) throw error;
      applyQuestionOverrides(data||[]);
      setQuestionBankVersion(v=>v+1);
    }catch(error){
      console.warn("Unable to load question overrides", error);
    }
  },[]);

  useEffect(()=>{
    refreshQuestionBankOverrides();
  },[refreshQuestionBankOverrides]);

  const refreshRemotePBQs=useCallback(async()=>{
    if(!isSupabaseConfigured){
      setRemotePbqBank(PBQ_BANK);
      setPbqBankLoading(false);
      setPbqBankError(null);
      return;
    }
    setPbqBankLoading(true);
    try{
      const {questions}=await loadRemotePBQs();
      setRemotePbqBank(questions);
      setPbqBankError(null);
    }catch(error){
      console.warn("Unable to load remote PBQs", error);
      setRemotePbqBank([]);
      setPbqBankError(error);
    }finally{
      setPbqBankLoading(false);
    }
  },[]);

  useEffect(()=>{
    refreshRemotePBQs();
  },[refreshRemotePBQs,user?.tier,questionBankVersion]);

  const refreshMascotPlacements=useCallback(async()=>{
    if(!isSupabaseConfigured)return;
    try{
      const { data, error }=await supabase
        .from("mascot_placements")
        .select("page_key,enabled,animation,anchor,size,speed,x_offset,y_offset,message,updated_at")
        .order("page_key",{ascending:true});
      if(error)throw error;
      setMascotPlacements((data||[]).map(normalizeMascotPlacement));
    }catch(error){
      if(error?.code!=="PGRST205")console.warn("Unable to load mascot placements",error);
    }
  },[]);

  useEffect(()=>{
    refreshMascotPlacements();
  },[refreshMascotPlacements]);

  const clearLocalAuthState=useCallback(async()=>{
    resetAnalytics();
    await DB.clearSession();
    setPasswordRecovery(false);
    setShowDiagnostic(false);
    setShowOnboarding(false);
    setShowProWelcome(false);
    setShowTrialExpiredPrompt(false);
    setReferralClaimPrompt(null);
    setUser(null);
    setAttempts([]);
    setStarred([]);
    setCoinWallet({...emptyCipherWallet(),status:"idle"});
    setCoinRewardToast(null);
    setPbqQ(null);
    setView("dashboard");
  },[]);

  const forceSupabaseSignOut=useCallback(async()=>{
    if(isSupabaseConfigured){
      await supabase.auth.signOut({ scope: "global" }).catch(()=>{});
      await supabase.auth.signOut({ scope: "local" }).catch(()=>{});
    }
    await clearLocalAuthState();
  },[clearLocalAuthState]);

  useEffect(()=>{
    if(loading||user||accountDeletion.stage!=="confirm")return;
    setAuthStartMode("login");
    setView("auth");
  },[loading,user,accountDeletion.stage]);

  useEffect(()=>{
    if(!isSupabaseConfigured)return undefined;
    const verifyCurrentSupabaseSession=async()=>{
      const { data } = await supabase.auth.getSession();
      if(!data.session)return;
      const { data: verified, error } = await supabase.auth.getUser();
      if(error || !verified?.user){
        await forceSupabaseSignOut();
        return;
      }
      if(isRecentlyDeletedAccount(verified.user)){
        await forceSupabaseSignOut();
        return;
      }
      const profile=await waitForSupabaseProfile(verified.user, 1);
      if(!profile) await forceSupabaseSignOut();
    };
    const verifyRestoredSession=event=>{
      if(event.persisted) verifyCurrentSupabaseSession();
    };
    const verifyVisibleSession=()=>{
      if(document.visibilityState==="visible") verifyCurrentSupabaseSession();
    };
    window.addEventListener("pageshow", verifyRestoredSession);
    document.addEventListener("visibilitychange", verifyVisibleSession);
    window.addEventListener("focus", verifyCurrentSupabaseSession);
    return()=>{
      window.removeEventListener("pageshow", verifyRestoredSession);
      document.removeEventListener("visibilitychange", verifyVisibleSession);
      window.removeEventListener("focus", verifyCurrentSupabaseSession);
    };
  },[forceSupabaseSignOut]);

  const handleTrialExpired=useCallback(()=>{
    setUser(u=>u ? { ...u, tier: "free", referralTrialExpired: true } : u);
    setShowTrialExpiredPrompt(true);
    setView("pricing");
  },[]);

  useEffect(()=>{
    const referralCode = rememberReferralFromUrl();
    if (referralCode) capture("referral_link_opened", { referral_code: referralCode });
  },[]);

  useEffect(()=>{
    capture("app_viewed", { view, signed_in: Boolean(user), tier: user?.tier || "guest" });
  },[view,user?.tier]);

  useEffect(()=>{
    if(view!=="mcq") setPracticeFocusMode(false);
  },[view]);

  useEffect(()=>{
    let active=true;

    if(isSupabaseConfigured){
      const applySupabaseSession=async session=>{
        if(!active)return;
        if(!session?.user){
          await clearLocalAuthState();
          setLoading(false);
          return;
        }
        const { data: verified, error: verifyError } = await supabase.auth.getUser();
        if(verifyError || !verified?.user){
          await forceSupabaseSignOut();
          if(active)setLoading(false);
          return;
        }
        const hadPendingAthena=Boolean(await getFreshPendingAthenaOAuth());
        const verifiedUser=await applyPendingAthenaOAuth(verified.user);
        const loginOAuthIntent=await consumeFreshLoginOAuthIntent();
        if(shouldForceCipherOnboardingAfterLoginOAuth(verifiedUser,{loginIntent:loginOAuthIntent,hadPendingAthena})){
          await forceSupabaseSignOut();
          if(active){
            setAuthStartMode("signup");
            setAuthRequestId(id=>id+1);
            setView("auth");
            setLoading(false);
          }
          return;
        }
        if(isRecentlyDeletedAccount(verifiedUser)){
          await forceSupabaseSignOut();
          if(active)setLoading(false);
          return;
        }
        const appUser=await waitForSupabaseProfile(verifiedUser);
        if(!appUser){
          await forceSupabaseSignOut();
          if(active)setLoading(false);
          return;
        }
        let displayUser=appUser;
        const params = new URLSearchParams(window.location.search);
        let shouldOpenProWelcome=false;
        if(params.get("checkout")==="cancelled"){
          setView("pricing");
          capture("stripe_checkout_cancelled", { source:"stripe_return" });
          const cleanUrl = `${window.location.origin}${window.location.pathname}`;
          window.history.replaceState({}, "", cleanUrl);
        }else if(params.get("checkout")==="success" || params.get("billing")==="return"){
          const checkoutSucceeded=params.get("checkout")==="success";
          const syncedUser = await syncStripeProfile(verifiedUser, params.get("session_id") || "");
          if(syncedUser) {
            displayUser = syncedUser;
            shouldOpenProWelcome=Boolean(checkoutSucceeded&&syncedUser.tier==="pro"&&shouldShowProWelcome(syncedUser));
            const cleanUrl = `${window.location.origin}${window.location.pathname}`;
            window.history.replaceState({}, "", cleanUrl);
          }
        }
        const savedAttempts=await loadSupabaseAttempts(verifiedUser.id);
        const accountAttempts=await importPendingGuestSmartReview(displayUser,savedAttempts);
        if(!active)return;
        const referralClaim = await claimReferralIfPresent(displayUser);
        showReferralClaimErrorOnce(referralClaim);
        if(Number(referralClaim?.coinsAwarded)>0) {
          displayUser = { ...displayUser, cipherCoins: Number(referralClaim.cipherCoins ?? displayUser.cipherCoins ?? 0) };
          if(!referralClaim.alreadyClaimed) setReferralClaimPrompt(referralClaim);
        }
        const savedStarred=(await loadSupabaseStarred(verifiedUser.id)) ?? await DB.getStarred(starOwner(displayUser));
        setUser(displayUser);
        identifyUser(displayUser);
        setAttempts(accountAttempts);
        setStarred(savedStarred);
        const diagnosticDone=await DB.getDiagnosticDone(appUser.email);
        const seen=await DB.getOnboardingSeen(appUser.email);
        if(active&&shouldOpenProWelcome){
          setShowOnboarding(false);
          setShowDiagnostic(false);
          setShowProWelcome(true);
          capture("pro_welcome_viewed", { source:"checkout_success" });
        }else if(active&&!seen) setShowOnboarding(true);
        else if(active&&!diagnosticDone&&accountAttempts.length===0) setShowDiagnostic(true);
        setLoading(false);
      };

      supabase.auth.getSession().then(({ data })=>applySupabaseSession(data.session));
      const { data: listener } = supabase.auth.onAuthStateChange((event, session)=>{
        if(event==="PASSWORD_RECOVERY") setPasswordRecovery(true);
        applySupabaseSession(session);
      });
      return()=>{
        active=false;
        listener?.subscription?.unsubscribe();
      };
    }

    (async()=>{
      const sess=await DB.getSession();
      if(sess?.loggedIn){const u=await DB.getUser(sess.email);if(u){setUser(u);const a=await DB.getAttempts(u.email);const s=await DB.getStarred(starOwner(u));setAttempts(a);setStarred(s);const diagnosticDone=await DB.getDiagnosticDone(u.email);const seen=await DB.getOnboardingSeen(u.email);if(!seen)setShowOnboarding(true);else if(!diagnosticDone&&a.length===0)setShowDiagnostic(true);}}
      setLoading(false);
    })();
    return()=>{active=false;};
  },[clearLocalAuthState,forceSupabaseSignOut,importPendingGuestSmartReview]);

  const handleLogin=useCallback(async u=>{
    if(isRecentlyDeletedAccount(u)){
      await forceSupabaseSignOut();
      return;
    }
    const referralClaim=await claimReferralIfPresent(u);
    showReferralClaimErrorOnce(referralClaim);
    if(Number(referralClaim?.coinsAwarded)>0 && !referralClaim.alreadyClaimed) setReferralClaimPrompt(referralClaim);
    const displayUser=Number(referralClaim?.coinsAwarded)>0 ? { ...u, cipherCoins:Number(referralClaim.cipherCoins ?? u.cipherCoins ?? 0) } : u;
    setUser(displayUser);
    identifyUser(displayUser);
    const savedAttempts=u?.authProvider==="supabase" ? await loadSupabaseAttempts(u.id) : await DB.getAttempts(u.email);
    const a=await importPendingGuestSmartReview(displayUser,savedAttempts);
    const s=u?.authProvider==="supabase" ? ((await loadSupabaseStarred(u.id)) ?? await DB.getStarred(starOwner(displayUser))) : await DB.getStarred(starOwner(displayUser));
    const diagnosticDone=await DB.getDiagnosticDone(displayUser.email);
    const seen=await DB.getOnboardingSeen(displayUser.email);
    if(!seen) setShowOnboarding(true);
    else if(!diagnosticDone&&a.length===0) setShowDiagnostic(true);
    setAttempts(a);setStarred(s);setView("dashboard");setShowDaily(false);
  },[forceSupabaseSignOut,importPendingGuestSmartReview]);
  const handleLogout=useCallback(async()=>{
    await forceSupabaseSignOut();
  },[forceSupabaseSignOut]);
  const refreshCipherWallet=useCallback(async()=>{
    if(!user)return emptyCipherWallet();
    setCoinBusy(true);
    try{
      const wallet=await loadCipherCoinWallet(user);
      setCoinWallet({...wallet,status:"ready",error:""});
      setUser(current=>current?{...current,cipherCoins:wallet.balance,lifetimeCipherCoins:wallet.lifetimeEarned,examPasses:wallet.examPasses}:current);
      return wallet;
    }catch(error){
      setCoinWallet(current=>({...normalizeCipherWallet(current),status:"error",error:error.message||"Unable to load Cipher Coins."}));
      return null;
    }finally{
      setCoinBusy(false);
    }
  },[user?.id,user?.email,user?.authProvider]);

  const runCipherAction=useCallback(async(action,payload={})=>{
    if(!user)return null;
    setCoinBusy(true);
    try{
      const result=await performCipherCoinAction(user,action,payload);
      const wallet=result.wallet ? normalizeCipherWallet(result.wallet) : await loadCipherCoinWallet(user);
      setCoinWallet({...wallet,status:"ready",error:""});
      setUser(current=>current?{...current,cipherCoins:wallet.balance,lifetimeCipherCoins:wallet.lifetimeEarned,examPasses:wallet.examPasses}:current);
      return result;
    }catch(error){
      setCoinWallet(current=>({...normalizeCipherWallet(current),status:"error",error:error.message||"Unable to update Cipher Coins."}));
      alert(error.message||"Unable to update Cipher Coins.");
      return null;
    }finally{
      setCoinBusy(false);
    }
  },[user?.id,user?.email,user?.authProvider]);

  useEffect(()=>{
    if(!user)return undefined;
    let active=true;
    (async()=>{
      try{
        const loaded=await loadCipherCoinWallet(user);
        if(!active)return;
        setCoinWallet({...loaded,status:"ready",error:""});
        const result=await performCipherCoinAction(user,"check_in");
        if(!active)return;
        const wallet=result.wallet ? normalizeCipherWallet(result.wallet) : await loadCipherCoinWallet(user);
        if(!active)return;
        setCoinWallet({...wallet,status:"ready",error:""});
        setUser(current=>current?{...current,cipherCoins:wallet.balance,lifetimeCipherCoins:wallet.lifetimeEarned,examPasses:wallet.examPasses}:current);
        if(result.awarded&&Number(result.amount)>0){
          setCoinRewardToast({amount:Number(result.amount),message:`Daily check-in secured · ${Number(result.streak)||1} day streak.`});
        }
      }catch(error){
        if(active)setCoinWallet(current=>({...normalizeCipherWallet(current),status:"error",error:error.message||"Cipher Coin setup is not ready yet."}));
      }
    })();
    return()=>{active=false;};
  },[user?.id,user?.email,user?.authProvider]);

  const handleUnlockPbq=useCallback(async()=>{
    const confirmed=window.confirm(`Spend ${CIPHER_COIN_COSTS.pbq} Cipher Coins to reveal one permanent mystery PBQ? Your first three reveals follow the shared starter path.`);
    if(!confirmed)return null;
    const result=await runCipherAction("unlock_pbq");
    if(!result)return null;
    const unlockedQuestion=livePbqBank.find(question=>question.id===result.resourceId)||PBQ_BANK.find(question=>question.id===result.resourceId)||result.unlockedPbq||null;
    if(result.purchased){
      setCoinRewardToast({amount:0,title:"Mystery PBQ revealed",message:`${unlockedQuestion?.title||result.resourceId} is now permanently available on this account.`});
      await refreshRemotePBQs();
    }
    return {...result,question:unlockedQuestion};
  },[runCipherAction,refreshRemotePBQs,livePbqBank]);

  const handleBuyExamPass=useCallback(async()=>{
    const confirmed=window.confirm(`Exchange ${CIPHER_COIN_COSTS.examPass} Cipher Coins for one SecurePlus practice exam voucher?`);
    if(!confirmed)return false;
    const result=await runCipherAction("buy_exam_pass");
    if(result?.purchased)setCoinRewardToast({amount:0,title:"Practice exam voucher ready",message:"One SecurePlus practice exam is now available. The voucher is used only when you start a new exam."});
    return Boolean(result?.purchased);
  },[runCipherAction]);

  const handleConsumeExamPass=useCallback(async()=>{
    const result=await runCipherAction("consume_exam_pass");
    return Boolean(result?.consumed);
  },[runCipherAction]);

  const handleDailyCoinReward=useCallback(async({score,total})=>{
    const result=await runCipherAction("daily_challenge",{score,total});
    if(result?.awarded&&Number(result.amount)>0){
      setCoinRewardToast({amount:Number(result.amount),message:result.milestoneReward?"Perfect challenge plus a five-day streak milestone!":"Perfect Daily Challenge completed."});
    }
  },[runCipherAction]);
  const handleUpdateProfile=useCallback(async name=>{
    if(!user)return;
    const clean=name.trim();
    if(user.authProvider==="supabase"){
      const { data, error } = await supabase.auth.updateUser({ data: { full_name: clean, name: clean } });
      if(error) throw error;
      await updateSupabaseAcademyProfile(user.id,{fullName:clean,avatarId:user.avatarId||"default-cipher"});
      const updated={...user,name:clean,loginMethod:data?.user?.app_metadata?.provider || user.loginMethod || "email"};
      setUser(updated);identifyUser(updated);
      return;
    }
    const updated={...user,name:clean,authProvider:user.authProvider||"local",loginMethod:user.loginMethod||"local"};
    await DB.saveUser(updated);
    await DB.saveSession({email:updated.email,name:updated.name,tier:updated.tier,loggedIn:true});
    setUser(updated);identifyUser(updated);
  },[user]);
  const handleUpdateAvatar=useCallback(async avatarId=>{
    if(!user)return;
    const clean=ACADEMY_AVATAR_MAP[avatarId] ? avatarId : "default-cipher";
    if(user.authProvider==="supabase"){
      const { data, error } = await supabase.auth.updateUser({ data: { avatar_id: clean } });
      if(error) throw error;
      await updateSupabaseAcademyProfile(user.id,{fullName:user.name,avatarId:clean});
      const updated={...user,avatarId:clean,loginMethod:data?.user?.app_metadata?.provider || user.loginMethod || "email"};
      setUser(updated);identifyUser(updated);
      return;
    }
    const updated={...user,avatarId:clean,authProvider:user.authProvider||"local",loginMethod:user.loginMethod||"local"};
    await DB.saveUser(updated);
    await DB.saveSession({email:updated.email,name:updated.name,tier:updated.tier,loggedIn:true});
    setUser(updated);identifyUser(updated);
  },[user]);
  const handleChangePassword=useCallback(async password=>{
    if(!user)return;
    if((user.loginMethod||"").toLowerCase().includes("google")){
      throw new Error("This account uses Google SSO. Change your password in your Google account.");
    }
    if(user.authProvider==="supabase"){
      const { error } = await supabase.auth.updateUser({ password });
      if(error) throw error;
      return;
    }
    const updated={...user,password,authProvider:user.authProvider||"local",loginMethod:user.loginMethod||"local"};
    await DB.saveUser(updated);
    setUser(updated);
  },[user]);
  const closeOnboarding=useCallback(async()=>{
    if(user?.email) await DB.saveOnboardingSeen(user.email);
    setShowOnboarding(false);
    const diagnosticDone=user?.email ? await DB.getDiagnosticDone(user.email) : true;
    if(!diagnosticDone&&attempts.length===0)setShowDiagnostic(true);
  },[user,attempts.length]);
  const closeProWelcome=useCallback(()=>{
    markProWelcomeSeen(user);
    setShowProWelcome(false);
  },[user]);
  const handleCancelMembership=useCallback(async()=>{
    if(!user)return;
    if(!isSupabaseConfigured){
      alert("Membership cancellation requires Supabase and Stripe env vars. For now, contact secureplus.support@gmail.com.");
      return;
    }
    if(user.authProvider!=="supabase"){
      alert("Please sign in with your live Supabase account before cancelling renewal. Local demo accounts do not have Stripe billing.");
      return;
    }
    if(user.subscriptionCancelAtPeriodEnd){
      alert("Your renewal is already cancelled. You will not be billed again for this membership.");
      return;
    }
    const confirmed=window.confirm("Cancel Pro renewal now? You will not be billed again, and Pro access will remain until the current paid period ends.");
    if(!confirmed){
      return;
    }
    setBillingLoading(true);
    try{
      capture("membership_cancel_requested", { tier: user.tier, subscription_status: user.subscriptionStatus || "unknown" });
      const token=await getSupabaseAccessToken();
      if(!token){
        alert("Please sign in again before cancelling renewal.");
        return;
      }
      const response=await fetch("/api/stripe/cancel",{
        method:"POST",
        headers:{authorization:`Bearer ${token}`},
      });
      const data=await response.json().catch(()=>({}));
      if(!response.ok||!data.profile) throw new Error(data.error||"Unable to cancel renewal.");
      const { data:authData }=await supabase.auth.getUser();
      const authUser=authData?.user;
      if(authUser){
        const updatedUser=appUserFromProfile(authUser,data.profile);
        setUser(updatedUser);
        identifyUser(updatedUser);
      }else{
        setUser(current=>current ? {
          ...current,
          subscriptionCancelAtPeriodEnd:true,
          subscriptionCurrentPeriodEnd:data.profile.subscription_current_period_end || current.subscriptionCurrentPeriodEnd,
          subscriptionStatus:data.profile.subscription_status || current.subscriptionStatus,
        } : current);
      }
      const endLabel=formatSubscriptionDate(data.profile.subscription_current_period_end);
      alert(`Renewal cancelled. You will not be billed again${endLabel ? `, and Pro access remains until ${endLabel}` : ""}.`);
    }catch(error){
      alert(error.message||"Unable to cancel renewal. Contact secureplus.support@gmail.com.");
    }finally{
      setBillingLoading(false);
    }
  },[user]);
  const handleSyncBilling=useCallback(async()=>{
    if(!user)return;
    if(!isSupabaseConfigured || user.authProvider!=="supabase"){
      alert("Billing sync requires a live Supabase account.");
      return;
    }
    setBillingLoading(true);
    try{
      const { data } = await supabase.auth.getUser();
      const authUser = data?.user;
      if(!authUser){
        alert("Please sign in again before refreshing Pro status.");
        return;
      }
      const syncedUser = await syncStripeProfile(authUser);
      if(!syncedUser){
        alert("No active Stripe subscription was found for this account yet. If you just paid, wait 30 seconds and try again.");
        return;
      }
      setUser(syncedUser);
      identifyUser(syncedUser);
      alert(syncedUser.tier==="pro" ? "Pro status refreshed. Your account is Pro now." : "Stripe synced, but this account is not showing an active subscription.");
    }finally{
      setBillingLoading(false);
    }
  },[user]);
  const clearAccountDeletion=useCallback(()=>{
    try{window.sessionStorage?.removeItem(ACCOUNT_DELETION_TOKEN_KEY);}catch{}
    setAccountDeletion(emptyAccountDeletionState());
  },[]);
  const sendAccountDeletionEmail=useCallback(async()=>{
    if(!user)return;
    setAccountDeletion(current=>({...current,busy:true,error:"",allowRestart:false}));
    try{
      const token=await getSupabaseAccessToken();
      if(!token)throw new Error("Please sign in again before requesting account deletion.");
      const response=await fetch("/api/account/delete-request",{
        method:"POST",
        headers:{authorization:`Bearer ${token}`},
      });
      const data=await response.json().catch(()=>({}));
      if(!response.ok){
        const error=new Error(data.error||"Unable to send the deletion email.");
        error.retryAfterSeconds=Number(data.retryAfterSeconds||0);
        throw error;
      }
      setAccountDeletion({
        ...emptyAccountDeletionState(),
        stage:"sent",
        email:data.email||user.email,
        deliveryChannel:data.deliveryChannel||"",
        retryAt:Date.now()+Number(data.resendAfterSeconds||60)*1000,
      });
      capture("account_deletion_email_requested",{delivery_accepted:true});
    }catch(error){
      const retrySeconds=Number(error.retryAfterSeconds||0);
      setAccountDeletion(current=>({
        ...current,
        busy:false,
        error:error.message||"Unable to send the deletion email.",
        retryAt:retrySeconds?Date.now()+retrySeconds*1000:current.retryAt,
      }));
      capture("account_deletion_email_requested",{delivery_accepted:false});
    }
  },[user]);
  const confirmAccountDeletion=useCallback(async()=>{
    if(!user||!accountDeletion.token)return;
    setAccountDeletion(current=>({...current,busy:true,error:"",allowRestart:false}));
    try{
      const token=await getSupabaseAccessToken();
      if(!token)throw new Error("Please sign in again before deleting your account.");
      const response=await fetch("/api/account/delete",{
        method:"POST",
        headers:{"content-type":"application/json",authorization:`Bearer ${token}`},
        body:JSON.stringify({deletionToken:accountDeletion.token}),
      });
      const data=await response.json().catch(()=>({}));
      if(!response.ok){
        const error=new Error(data.error||"Unable to delete the account.");
        error.allowRestart=response.status===410;
        throw error;
      }
      rememberDeletedAccount(user);
      await DB.saveStarred(starOwner(user),[]);
      try{window.sessionStorage?.removeItem(ACCOUNT_DELETION_TOKEN_KEY);}catch{}
      setAccountDeletion(emptyAccountDeletionState());
      await forceSupabaseSignOut();
      alert("Your SecurePlus account and saved learning data have been permanently deleted.");
      window.location.replace("/");
    }catch(error){
      setAccountDeletion(current=>({
        ...current,
        busy:false,
        error:error.message||"Unable to delete the account. Your data has not been removed.",
        allowRestart:Boolean(error.allowRestart),
      }));
    }
  },[user,accountDeletion.token,forceSupabaseSignOut]);
  const switchDeletionAccount=useCallback(async()=>{
    await forceSupabaseSignOut();
    setAuthStartMode("login");
    setView("auth");
  },[forceSupabaseSignOut]);
  const handleDeleteAccount=useCallback(async()=>{
    if(!user)return;

    if(!isSupabaseConfigured){
      const confirmed=window.confirm("Delete this local demo account and saved progress? This cannot be undone.");
      if(!confirmed)return;
      await DB.saveStarred(starOwner(user),[]);
      await DB.deleteUser(user.email);
      await DB.clearSession();
      setUser(null);setAttempts([]);setStarred([]);setView("dashboard");
      alert("Local demo account deleted from this browser.");
      return;
    }
    if(user.authProvider!=="supabase"){
      alert("This account is not connected to Supabase, so it cannot use production account deletion.");
      return;
    }
    setAccountDeletion({...emptyAccountDeletionState(),stage:"request",email:user.email});
  },[user]);
  const handleUpgrade=useCallback(async (plan="three_month")=>{
    if(!user)return;
    const selectedPlan=plan==="monthly"?"monthly":"three_month";

    if(!isSupabaseConfigured){
      alert("Stripe Checkout is ready in the project code, but Supabase env vars are not configured yet. Add VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY, sign in with Supabase, then try again.");
      return;
    }

    setBillingLoading(true);
    try{
      const token=await getSupabaseAccessToken();
      if(!token){
        alert("Please sign in with Supabase before upgrading. Local demo accounts cannot start real Stripe Checkout.");
        return;
      }

      const response=await fetch("/api/stripe/checkout",{
        method:"POST",
        headers:{
          "content-type":"application/json",
          authorization:`Bearer ${token}`,
        },
        body: JSON.stringify({
          plan:selectedPlan,
          referralCode:getStoredReferralCode(),
        }),
      });
      const data=await response.json().catch(()=>({}));
      if(!response.ok||!data.url) throw new Error(data.error||"Unable to start Checkout.");
      window.location.href=data.url;
    }catch(error){
      alert(error.message||"Unable to start Stripe Checkout.");
    }finally{
      setBillingLoading(false);
    }
  },[user]);
  const handleSaveAttempt=useCallback(async r=>{
    if(!user)return;
    setAttempts(a=>[r,...a]);
    try{
      if(user.authProvider==="supabase") await saveSupabaseAttempt(user.id,r);
      else await DB.saveAttempt(user.email,r);
    }catch(error){
      console.warn("Unable to save attempt remotely", error);
    }
  },[user]);
  const handleDiagnosticComplete=useCallback(async results=>{
    if(!user)return;
    const saved=[...results].reverse();
    setAttempts(prev=>[...saved,...prev]);
    try{
      if(user.authProvider==="supabase") {
        await Promise.all(saved.map(result=>saveSupabaseAttempt(user.id,result)));
      } else {
        for (const result of saved) await DB.saveAttempt(user.email,result);
      }
      await DB.saveDiagnosticDone(user.email);
      const seen=await DB.getOnboardingSeen(user.email);
      setShowDiagnostic(false);
      if(!seen) setShowOnboarding(true);
      setView("mcq");
      capture("diagnostic_completed", { correct_count: results.filter(r=>r.correct).length, question_count: results.length, tier: user.tier });
    }catch(error){
      console.warn("Unable to save diagnostic results", error);
      await DB.saveDiagnosticDone(user.email);
      setShowDiagnostic(false);
      setView("mcq");
    }
  },[user]);
  const handleToggleStar=useCallback((type,id)=>{
    if(!user)return;
    const key=starKey(type,id);
    setStarred(prev=>{
      const exists=prev.includes(key);
      const next=exists?prev.filter(item=>item!==key):[key,...prev];
      DB.saveStarred(starOwner(user),next);
      if(user.authProvider==="supabase") saveSupabaseStar(user.id,type,id,!exists);
      capture("question_star_toggled", { type, id, starred: !exists, tier: user.tier });
      return next;
    });
  },[user]);
  const handleReportQuestion=useCallback(details=>{
    const report=buildQuestionReport(details);
    capture("question_report_opened", { question_id:report.questionId, question_type:report.questionKind, tier: user?.tier||"guest" });
    setQuestionReport(report);
  },[user?.tier]);
  const handleStartChapterReview=useCallback((chapterId,options={})=>{
    setSmartReviewRequest({
      chapterId:String(chapterId),
      count:Math.max(1,Math.min(10,Number(options.count)||10)),
      source:options.source||"chapter_review",
      nonce:Date.now(),
    });
    setView("mcq");
  },[]);
  const handleOpenDeepDive=useCallback((lessonId,options={})=>{
    if(!CONCEPT_DEEP_DIVES.some(dive=>dive.id===lessonId))return;
    setDeepDiveRequest({
      lessonId,
      mode:options.mode||"learn",
      source:options.source||"smart_review",
      nonce:Date.now(),
    });
    setView("deep-dives");
  },[]);
  const handleOpenFlashcards=useCallback((setId=null)=>{
    if(setId&&typeof setId==="object"&&setId.id===ASSISTANT_FLASHCARD_SET_ID){
      setAssistantFlashcardSet({...setId,nonce:Date.now()});
      setFlashcardSetRequest(ASSISTANT_FLASHCARD_SET_ID);
      setView("flashcards");
      return;
    }
    if(setId&&(setId===STARRED_FLASHCARD_SET_ID||SY0701_ACRONYM_SETS.some(set=>set.id===setId))){
      setFlashcardSetRequest(setId);
    }else{
      setFlashcardSetRequest(null);
    }
    setView("flashcards");
  },[]);
  const handleAddDeepDiveWeakTopicToReview=useCallback(({chapterId,lessonId,title}={})=>{
    if(!chapterId)return;
    capture("deep_dive_add_weak_topic_clicked",{chapter:chapterId,lesson_id:lessonId,title});
    handleStartChapterReview(chapterId,{count:10,source:"concept_deep_dive_end_action"});
  },[handleStartChapterReview]);
  const handleTryRelatedDeepDivePbq=useCallback(({chapterId,lessonId,title}={})=>{
    const chapterKey=String(chapterId||"");
    const unlockedIds=coinWallet?.unlockedPbqIds||[];
    const accessible=question=>user?.tier==="pro"||isFreePBQPreview(question)||unlockedIds.includes(question.id);
    const related=livePbqBank.find(question=>String(question.ch)===chapterKey&&accessible(question))
      || livePbqBank.find(question=>String(question.ch)===chapterKey)
      || livePbqBank.find(isFreePBQPreview)
      || null;
    capture("deep_dive_related_pbq_clicked",{chapter:chapterKey,lesson_id:lessonId,title,question_id:related?.id||null,accessible:Boolean(related&&accessible(related))});
    if(related&&accessible(related)){
      setPbqQ(related);
      setView("pbq");
      return;
    }
    setView(user?.tier==="free"?"coins":"pbq");
  },[coinWallet?.unlockedPbqIds,livePbqBank,user?.tier]);
  const handleGuestPbqPreview=useCallback(()=>{
    const preview=livePbqBank.find(isFreePBQPreview)||PBQ_BANK.find(isFreePBQPreview)||null;
    capture("pbq_preview_cta_clicked", {
      source:view==="auth"?"marketing_home":"guest_home",
      question_id:preview?.id||FREE_PBQ_PREVIEW_ID,
    });
    setPbqQ(preview);
    setView("pbq");
  },[livePbqBank,view]);
  const handleAchievementSessionComplete=useCallback(async payload=>{
    if(!user)return;
    if(user.authProvider!=="supabase"){
      if(payload?.session_type==="practice"&&Number(payload?.score)===100&&Number(payload?.questions_count)>=5){
        const reward=await runCipherAction("perfect_mcq",{questionsCount:Number(payload.questions_count)});
        if(reward?.awarded)setCoinRewardToast({amount:15,message:"Perfect MCQ set · first reward of the day."});
      }
      return;
    }
    try{
      const result=await submitAchievementSession(payload);
      if(result.totalStars!==null&&result.totalStars!==undefined){
        setUser(current=>current?{...current,totalStars:Number(result.totalStars)||0}:current);
      }
      if(result.newlyUnlocked?.length){
        setAchievementUnlocks(result.newlyUnlocked);
        capture("achievements_unlocked", { achievement_ids: result.newlyUnlocked.join(","), count: result.newlyUnlocked.length });
      }
      if(result.coinReward?.awarded&&Number(result.coinReward.amount)>0){
        setCoinRewardToast({amount:Number(result.coinReward.amount),message:"Perfect MCQ set · first reward of the day."});
        await refreshCipherWallet();
      }
    }catch(error){
      console.warn("Unable to submit achievement session", error);
    }
  },[user,runCipherAction,refreshCipherWallet]);
  const handleEditReportedQuestion=useCallback(target=>{
    if(!target?.id)return;
    setAdminQuestionTarget({...target,nonce:Date.now()});
    setView("question-admin");
    capture("admin_feedback_edit_question_clicked", { question_id: target.id, question_type: target.kind, report_id: target.reportId });
  },[]);
  const handlePBQDone=useCallback(async (result,options={})=>{
    if(result&&user){
      setAttempts(a=>[result,...a]);
      try{
        if(user.authProvider==="supabase") await saveSupabaseAttempt(user.id,result);
        else await DB.saveAttempt(user.email,result);
      }catch(error){
        console.warn("Unable to save PBQ attempt remotely", error);
      }
      await handleAchievementSessionComplete({
        session_type:"pbq",
        score:Number.isFinite(Number(result.score))?Math.round(Number(result.score)*100):(result.correct?100:0),
        duration_seconds:Math.max(1,Math.round(Number(result.duration_seconds||result.timeSpentSeconds||1))),
        questions_count:1,
        chapter_id:result.ch||null,
      });
    }
    if(options.nextQuestion){
      setPbqQ(options.nextQuestion);
      setView("pbq");
      return;
    }
    setPbqQ(null);setView("pbq");
  },[user,handleAchievementSessionComplete]);

  const CSS=makeCSS(t);

  if(loading) return(
    <>
      <style>{CSS}</style>
      <LoadingScreen t={t}/>
    </>
  );

  if(passwordRecovery) return(
    <>
      <style>{CSS}</style>
      <div style={{background:t.bg,minHeight:"100vh"}}>
        <PasswordUpdateView t={t} onDone={()=>{setPasswordRecovery(false);setView("dashboard");}}/>
      </div>
    </>
  );

  if(user&&accountDeletion.stage==="confirm") return(
    <>
      <style>{CSS}</style>
      <div style={{minHeight:"100vh",background:t.bg}}>
        <div style={{padding:"16px 22px",display:"flex",alignItems:"center",gap:9,borderBottom:`1px solid ${t.border}`,background:t.surface}}>
          <BrandMark size={32}/><strong style={{color:t.text}}>SecurePlus account security</strong>
        </div>
      </div>
      <AccountDeletionModal
        state={accountDeletion}
        user={user}
        t={t}
        onClose={clearAccountDeletion}
        onSend={sendAccountDeletionEmail}
        onConfirm={confirmAccountDeletion}
        onSwitchAccount={switchDeletionAccount}
      />
    </>
  );

  if(showDaily&&!user) return(
    <>
      <style>{CSS}</style>
      <div style={{background:t.bg,minHeight:"100vh"}}>
        <div style={{background:t.surface,borderBottom:`1px solid ${t.border}`,padding:"12px 24px",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <button type="button" onClick={()=>setView("dashboard")} style={{display:"flex",alignItems:"center",gap:8,background:"transparent",border:0,padding:0,cursor:"pointer",textAlign:"left"}}><BrandMark size={28}/><span style={{fontWeight:700,fontSize:15,color:t.text}}>SecurePlus</span></button>
          <div style={{display:"flex",gap:8}}>
            <button className="btn btn-ghost" style={{fontSize:12}} onClick={()=>setShowDaily(false)}>← Back</button>
            <button className="btn btn-outline" style={{fontSize:12}} onClick={()=>setShowDaily(false)}>Sign In / Register</button>
          </div>
        </div>
        <DailyChallenge t={t} onLogin={()=>setShowDaily(false)}/>
      </div>
    </>
  );

  if(!user&&(view==="privacy"||view==="terms")) return(
    <>
      <style>{CSS}</style>
      <div style={{background:t.bg,minHeight:"100vh"}}>
        <div style={{background:t.surface,borderBottom:`1px solid ${t.border}`,padding:"12px 24px",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <button type="button" onClick={()=>setView("dashboard")} style={{display:"flex",alignItems:"center",gap:8,background:"transparent",border:0,padding:0,cursor:"pointer",textAlign:"left"}}><BrandMark size={28}/><span style={{fontWeight:700,fontSize:15,color:t.text}}>SecurePlus</span></button>
          <button className="btn btn-outline" style={{fontSize:12}} onClick={()=>setView("dashboard")}>Sign In / Register</button>
        </div>
        <LegalPage type={view} t={t}/>
      </div>
    </>
  );

  if(!user&&view==="auth") return(
    <>
      <style>{CSS}</style>
      <AuthView key={`auth-${authStartMode}-${authRequestId}`} onLogin={handleLogin} t={t} onDaily={()=>setView("daily")} onNavigate={setView} onPracticeMcq={()=>setView("mcq")} onPreviewPbq={handleGuestPbqPreview} initialMode={authStartMode} securityNotice={accountDeletion.stage==="confirm"}/>
    </>
  );

  if(!user){
    const guestUser={name:"Guest",email:"guest@secureplus.local",tier:"free",joined:new Date().toISOString(),streak:0,authProvider:"guest",loginMethod:"guest"};
    const guestCoinWallet=normalizeCipherWallet(emptyCipherWallet());
    const activeGuestPbq=pbqQ ? (livePbqBank.find(question=>question.id===pbqQ.id)||pbqQ) : null;
    const devCoinWallet=normalizeCipherWallet({
      balance:150,
      lifetimeEarned:250,
      examPasses:1,
      unlockedPbqIds:["p014"],
      checkInStreak:6,
      transactions:[
        {id:"preview-check-in",amount:5,balance_after:150,event_type:"daily_check_in",created_at:new Date().toISOString()},
        {id:"preview-mcq",amount:15,balance_after:145,event_type:"perfect_mcq",created_at:new Date(Date.now()-86400000).toISOString()},
        {id:"preview-pbq",amount:-50,balance_after:130,event_type:"pbq_unlock",created_at:new Date(Date.now()-172800000).toISOString()},
      ],
    });
    const goToSignup=()=>{setPbqQ(null);setAuthStartMode("signup");setAuthRequestId(id=>id+1);setView("auth");};
    const goToLogin=()=>{setPbqQ(null);setAuthStartMode("login");setAuthRequestId(id=>id+1);setView("auth");};
    const allowedGuestViews=new Set(["dashboard","mcq","pbq","daily","objectives","flashcards","deep-dives",...(devCoinPreview?["coins"]:[])]);
    const guestNavItems=[
      {id:"dashboard",icon:"dashboard",label:"Dashboard",mobileLabel:"Home"},
      {id:"mcq",icon:"mcq",label:"MCQ Practice",mobileLabel:"MCQ"},
      {id:"pbq",icon:"pbq",label:"PBQ Simulator",mobileLabel:"PBQ"},
      {id:"exam",icon:"exam",label:"Exam Mode",mobileLabel:"Exam"},
      {id:"daily",icon:"daily",label:"Daily Challenge",mobileLabel:"Daily"},
      ...(devCoinPreview?[{id:"coins",icon:"coins",label:"Cipher Coins",mobileLabel:"Coins"}]:[]),
      {id:"objectives",icon:"objectives",label:"Objectives",mobileLabel:"Goals"},
      {id:"flashcards",icon:"flashcards",label:"Flashcards",mobileLabel:"Cards"},
      {id:"deep-dives",icon:"deep-dives",label:"Concept Deep Dives",mobileLabel:"Deep Dives"},
    ];
    const guestGo=id=>{
      if(allowedGuestViews.has(id)) setView(id);
      else {
        capture("guest_locked_nav_clicked", { target:id });
        setView(id);
      }
    };
    const lockedTitle={
      pbq:"Create an account to unlock PBQ previews",
      exam:"Create an account before Exam Mode",
      "deep-dives":"Create an account to preview Concept Deep Dives",
      pricing:"Sign up before upgrading",
      objectives:"Create an account to save your study path",
    }[view] || "Create an account to save progress";
    return(
      <>
        <style>{CSS}</style>
        <div className={`app-shell ${practiceFocusMode?"practice-focus-mode":""}`}>
          <a className="skip-link" href="#secureplus-main">Skip to study content</a>
          {sidebarHidden&&(
            <button className="sidebar-restore" type="button" onClick={()=>setSidebarHidden(false)}>
              <NavGlyph type="dashboard" active/>
              Show menu
            </button>
          )}
          <aside className={`sidebar ${sidebarHidden?"hidden":""}`}>
            <div style={{padding:"18px 16px",borderBottom:`1px solid ${t.border}`}}>
              <button type="button" onClick={()=>setView("dashboard")} style={{display:"flex",alignItems:"center",gap:9,fontWeight:700,fontSize:16,color:t.text,background:"transparent",border:0,padding:0,cursor:"pointer",textAlign:"left"}}><BrandMark size={30}/> SecurePlus</button>
              <div style={{fontSize:11,color:t.textDim,marginTop:4}}>Guest mode · progress is not saved</div>
              <button className="btn btn-ghost" type="button" style={{fontSize:12,justifyContent:"flex-start",width:"100%",marginTop:12}} onClick={()=>setSidebarHidden(true)}>
                Hide sidebar
              </button>
            </div>
            <nav style={{flex:1,padding:"10px 10px",display:"flex",flexDirection:"column",gap:2}}>
              {guestNavItems.map(n=>{
                const locked=!allowedGuestViews.has(n.id);
                return(
                  <button type="button" key={n.id} data-mobile-primary={MOBILE_PRIMARY_NAV_IDS.has(n.id)?"true":"false"} aria-current={view===n.id?"page":undefined} className={`nav-lnk ${view===n.id?"act":""} ${locked?"locked":""}`} onClick={()=>guestGo(n.id)}>
                    <NavGlyph type={n.icon} active={view===n.id}/>
                    <span className="nav-label"><span className="nav-label-desktop">{n.label}</span><span className="nav-label-mobile">{n.mobileLabel}</span></span>
                    {locked&&<LockKeyhole className="nav-lock-indicator" size={13} strokeWidth={2.4} aria-hidden="true"/>}
                  </button>
                );
              })}
              <button type="button" className={`nav-lnk mobile-more-trigger ${!MOBILE_PRIMARY_NAV_IDS.has(view)?"act":""}`} aria-expanded={mobileNavOpen} onClick={()=>setMobileNavOpen(true)}>
                <span className="nav-glyph" aria-hidden="true"><MoreHorizontal size={19}/></span>
                <span className="nav-label"><span className="nav-label-desktop">More</span><span className="nav-label-mobile">More</span></span>
              </button>
            </nav>
            <div style={{padding:"12px 14px",borderTop:`1px solid ${t.border}`,display:"flex",flexDirection:"column",gap:6}}>
              <button className="btn btn-ghost" style={{fontSize:12,justifyContent:"flex-start"}} onClick={()=>setDarkMode(d=>!d)}>
                {darkMode?<><Sun size={16}/> Light Mode</>:<><Moon size={16}/> Dark Mode</>}
              </button>
              <button className="btn btn-primary" style={{fontSize:12,justifyContent:"center"}} onClick={goToSignup}>
                Create Free Account
              </button>
              <button className="btn btn-outline" style={{fontSize:12,justifyContent:"flex-start"}} onClick={goToLogin}>
                Log In
              </button>
            </div>
          </aside>
          <main id="secureplus-main" className="app-main fu">
            <div className="mobile-topbar">
              <div>
                <button type="button" onClick={()=>setView("dashboard")} style={{display:"flex",alignItems:"center",gap:8,fontWeight:800,fontSize:15,color:t.text,background:"transparent",border:0,padding:0,cursor:"pointer",textAlign:"left"}}><BrandMark size={28}/> SecurePlus</button>
                <div style={{fontSize:11,color:t.textDim}}>Progress is not saved</div>
              </div>
              <div style={{display:"flex",gap:6,alignItems:"center",flexShrink:0}}>
                <button className="btn btn-ghost" style={{fontSize:12,minHeight:34,padding:"6px 10px"}} onClick={()=>setDarkMode(d=>!d)}>
                  {darkMode?<><Sun size={15}/> Light</>:<><Moon size={15}/> Dark</>}
                </button>
                <button className="btn btn-primary" style={{fontSize:12,minHeight:34,padding:"6px 10px"}} onClick={goToSignup}>Sign up</button>
              </div>
            </div>
            {view==="dashboard"&&(
              <GuestDashboardGate t={t} onSignup={goToSignup} onLogin={goToLogin} onPractice={()=>setView("mcq")} onPreviewPbq={handleGuestPbqPreview} onDaily={()=>setView("daily")} onFlashcards={()=>setView("flashcards")}/>
            )}
            {view==="mcq"&&(
              <MCQPractice user={guestUser} attempts={[]} onSave={()=>{}} onUpgrade={goToSignup} onSignup={goToSignup} onFocusModeChange={setPracticeFocusMode} isVisible={view==="mcq"} t={t} starred={[]} onReportQuestion={handleReportQuestion} mcqBank={liveMcqBank}/>
            )}
            {view==="pbq"&&(
              activeGuestPbq ? (
                <PBQSim
                  key={activeGuestPbq.id}
                  q={activeGuestPbq}
                  t={t}
                  previewMode
                  isGuest
                  onDone={()=>{setPbqQ(null);setView("pbq");}}
                  onUpgrade={goToSignup}
                  onOpenWallet={goToSignup}
                  onReportQuestion={handleReportQuestion}
                />
              ) : (
                <PBQBank
                  user={guestUser}
                  attempts={[]}
                  onStart={question=>{if(isFreePBQPreview(question))setPbqQ(question);else goToSignup();}}
                  onUpgrade={goToSignup}
                  onOpenWallet={goToSignup}
                  onUnlockPbq={async()=>{goToSignup();return null;}}
                  coinWallet={guestCoinWallet}
                  t={t}
                  starred={[]}
                  onReportQuestion={handleReportQuestion}
                  pbqBank={livePbqBank}
                />
              )
            )}
            {view==="daily"&&(
              <DailyChallenge t={t} onLogin={goToSignup}/>
            )}
            {view==="objectives"&&<ObjectivesPage t={t}/>}
            {view==="flashcards"&&<FlashcardsPage t={t} initialSetId={flashcardSetRequest} onInitialSetHandled={()=>setFlashcardSetRequest(null)} assistantSet={assistantFlashcardSet} onRequireSignup={reason=>setFlashcardAuthPrompt(reason||"flashcard_star")}/>}
            {view==="deep-dives"&&<ConceptDeepDivesPage t={t} user={guestUser} onOpenFlashcards={()=>setView("flashcards")} onUpgrade={goToSignup}/>}
            {devCoinPreview&&view==="coins"&&<CipherCoinVault user={guestUser} wallet={devCoinWallet} onUnlockPbq={()=>Promise.resolve(null)} onBuyExamPass={()=>{}} onNavigate={setView} onRefresh={()=>{}} t={t}/>}
            {!allowedGuestViews.has(view)&&(
              <GuestLockedPage t={t} title={lockedTitle} onSignup={goToSignup} onLogin={goToLogin} onPractice={()=>setView("mcq")} onDaily={()=>setView("daily")}/>
            )}
            {!practiceFocusMode&&view!=="exam"&&<MascotPlacement placement={mascotPlacements.find(item=>item.page_key===view)}/>}
          </main>
          <MobileNavigationMenu
            open={mobileNavOpen}
            items={guestNavItems.filter(item=>!MOBILE_PRIMARY_NAV_IDS.has(item.id)).map(item=>({...item,locked:!allowedGuestViews.has(item.id)}))}
            currentView={view}
            onNavigate={id=>{setMobileNavOpen(false);guestGo(id);}}
            onClose={()=>setMobileNavOpen(false)}
          />
          {flashcardAuthPrompt&&(
            <FlashcardSavePrompt
              t={t}
              onClose={()=>setFlashcardAuthPrompt(false)}
              onLogin={()=>{setFlashcardAuthPrompt(false);goToLogin();}}
              onSignup={()=>{setFlashcardAuthPrompt(false);goToSignup();}}
              mode={flashcardAuthPrompt==="flashcard_learn_more"?"learn_more":"save"}
            />
          )}
          {questionReport&&<QuestionReportModal report={questionReport} user={null} t={t} onClose={()=>setQuestionReport(null)}/>}
        </div>
      </>
    );
  }

  if(user&&showDiagnostic) return(
    <>
      <style>{CSS}</style>
      <DiagnosticQuiz user={user} t={t} onComplete={handleDiagnosticComplete}/>
    </>
  );

  const activePbq=pbqQ ? (livePbqBank.find(question=>question.id===pbqQ.id) || (!isSupabaseConfigured ? pbqQ : null)) : null;
  const pbqPreviewMode=user?.tier!=="pro"&&isFreePBQPreview(activePbq);
  const pbqCoinUnlocked=Boolean(activePbq&&coinWallet.unlockedPbqIds.includes(activePbq.id));
  const nextPbq=user?.tier==="pro"&&activePbq?getNextRelatedPBQ(activePbq,attempts,livePbqBank):null;

  if(pbqQ) return(
    <>
      <style>{CSS}</style>
      <div style={{background:t.bg,minHeight:"100vh"}}>
        <div style={{background:t.surface,borderBottom:`1px solid ${t.border}`,padding:"12px 24px",display:"flex",alignItems:"center",justifyContent:"space-between"}}>
          <button type="button" onClick={()=>{setPbqQ(null);setView("dashboard");}} style={{display:"flex",alignItems:"center",gap:8,background:"transparent",border:0,padding:0,cursor:"pointer",textAlign:"left"}}>
            <BrandMark size={28}/><span style={{fontWeight:800,fontSize:15,color:t.text}}>SecurePlus</span>
          </button>
        </div>
        {pbqBankLoading ? <PBQLoadingSkeleton t={t}/> : activePbq ? (
          <PBQSim
            key={activePbq.id}
            q={activePbq}
            nextQuestion={nextPbq}
            onDone={handlePBQDone}
            onNext={(result)=>handlePBQDone(result,{nextQuestion:nextPbq})}
            t={t}
            starred={starred}
            onToggleStar={handleToggleStar}
            previewMode={pbqPreviewMode}
            onUpgrade={()=>setView("pricing")}
            onOpenWallet={()=>setView("coins")}
            onReportQuestion={handleReportQuestion}
            showQuestionCodes={isRootUser}
          />
        ) : pbqCoinUnlocked ? <PBQLoadingSkeleton t={t}/> : (
          <UpgradeModal onUpgrade={()=>setView("pricing")} onClose={()=>{setPbqQ(null);setView("pbq");}} t={t}/>
        )}
      </div>
      <AchievementCelebration ids={achievementUnlocks} t={t} onClose={()=>setAchievementUnlocks([])}/>
      {questionReport&&<QuestionReportModal report={questionReport} user={user} t={t} onClose={()=>setQuestionReport(null)}/>}
    </>
  );

  const navItems=[
    {id:"dashboard",icon:"dashboard",label:"Dashboard",mobileLabel:"Home"},
    {id:"mcq",icon:"mcq",label:"MCQ Practice",mobileLabel:"MCQ"},
    {id:"pbq",icon:"pbq",label:"PBQ Simulator",mobileLabel:"PBQ"},
    {id:"exam",icon:"exam",label:"Exam Mode",mobileLabel:"Exam"},
    {id:"daily",icon:"daily",label:"Daily Challenge",mobileLabel:"Daily"},
    {id:"coins",icon:"coins",label:"Cipher Coins",mobileLabel:"Coins"},
    {id:"deep-dives",icon:"deep-dives",label:"Concept Deep Dives",mobileLabel:"Deep Dives"},
    {id:"flashcards",icon:"flashcards",label:"Flashcards",mobileLabel:"Cards"},
    {id:"pricing",icon:"pricing",label:"Upgrade",mobileLabel:"Upgrade"},
    {id:"objectives",icon:"objectives",label:"Objectives",mobileLabel:"Goals"},
    {id:"account",icon:"account",label:"Account & Support",mobileLabel:"Account"},
  ];
  if(isRootUser) {
    navItems.push({id:"feedback",icon:"feedback",label:"Internal Feedback",mobileLabel:"Feedback"});
    navItems.push({id:"question-admin",icon:"question-admin",label:"Question Manager",mobileLabel:"Manager"});
    navItems.push({id:"mascot-admin",icon:"mascot-admin",label:"Mascot Manager",mobileLabel:"Mascot"});
  }

  return(
    <>
      <style>{CSS}</style>
      <div className={`app-shell ${practiceFocusMode?"practice-focus-mode":""}`}>
        <a className="skip-link" href="#secureplus-main">Skip to study content</a>
        {sidebarHidden&&(
          <button className="sidebar-restore" type="button" onClick={()=>setSidebarHidden(false)}>
            <NavGlyph type="dashboard" active/>
            Show menu
          </button>
        )}
        {/* Sidebar */}
        <aside className={`sidebar ${sidebarHidden?"hidden":""}`}>
          {/* Logo */}
          <div style={{padding:"18px 16px",borderBottom:`1px solid ${t.border}`}}>
            <button type="button" onClick={()=>setView("dashboard")} style={{display:"flex",alignItems:"center",gap:9,fontWeight:700,fontSize:16,color:t.text,background:"transparent",border:0,padding:0,cursor:"pointer",textAlign:"left"}}><BrandMark size={30}/> SecurePlus</button>
            <div style={{fontSize:11,color:t.textDim,marginTop:2}}>CompTIA Security+ Practice Platform</div>
            <button className="btn btn-ghost" type="button" style={{fontSize:12,justifyContent:"flex-start",width:"100%",marginTop:12}} onClick={()=>setSidebarHidden(true)}>
              Hide sidebar
            </button>
          </div>

          {/* User */}
          <div style={{padding:"12px 14px",borderBottom:`1px solid ${t.border}`}}>
            <ProfileMenu user={user} t={t} onUpdateProfile={handleUpdateProfile} onUpdateAvatar={handleUpdateAvatar} onChangePassword={handleChangePassword} onLogout={handleLogout}/>
            <div style={{marginTop:10}}><CipherCoinPill balance={coinWallet.balance} onClick={()=>setView("coins")}/></div>
          </div>

          {/* Nav */}
          <nav style={{flex:1,padding:"10px 10px",display:"flex",flexDirection:"column",gap:2}}>
            {navItems.map(n=>(
              <button type="button" key={n.id} data-mobile-primary={MOBILE_PRIMARY_NAV_IDS.has(n.id)?"true":"false"} aria-current={view===n.id?"page":undefined} className={`nav-lnk ${view===n.id?"act":""}`} onClick={()=>setView(n.id==="exam"&&user.tier!=="pro"&&coinWallet.examPasses<1?"coins":n.id)}>
                <NavGlyph type={n.icon} active={view===n.id}/>
                <span className="nav-label"><span className="nav-label-desktop">{n.label}</span><span className="nav-label-mobile">{n.mobileLabel}</span></span>
              </button>
            ))}
            <button type="button" className={`nav-lnk mobile-more-trigger ${!MOBILE_PRIMARY_NAV_IDS.has(view)?"act":""}`} aria-expanded={mobileNavOpen} onClick={()=>setMobileNavOpen(true)}>
              <span className="nav-glyph" aria-hidden="true"><MoreHorizontal size={19}/></span>
              <span className="nav-label"><span className="nav-label-desktop">More</span><span className="nav-label-mobile">More</span></span>
            </button>
          </nav>

          {/* Dark mode + logout */}
          <div style={{padding:"12px 14px",borderTop:`1px solid ${t.border}`,display:"flex",flexDirection:"column",gap:6}}>
            <button className="btn btn-ghost" style={{fontSize:12,justifyContent:"flex-start"}} onClick={()=>setDarkMode(d=>!d)}>
              {darkMode?<><Sun size={16}/> Light Mode</>:<><Moon size={16}/> Dark Mode</>}
            </button>
            <button className="btn btn-signout" style={{fontSize:12,justifyContent:"flex-start"}} onClick={handleLogout}>
              <LogOut size={16}/> Sign Out
            </button>
          </div>
        </aside>

        {/* Main content */}
        <main id="secureplus-main" className="app-main fu">
          <div className="mobile-topbar">
            <div>
              <button type="button" onClick={()=>setView("dashboard")} style={{display:"flex",alignItems:"center",gap:8,fontWeight:800,fontSize:15,color:t.text,background:"transparent",border:0,padding:0,cursor:"pointer",textAlign:"left"}}><BrandMark size={28}/> SecurePlus</button>
              <div style={{fontSize:11,color:t.textDim}}>CompTIA Security+ Practice</div>
            </div>
            <div style={{display:"flex",gap:6,alignItems:"center",flexShrink:0}}>
              <CipherCoinPill compact balance={coinWallet.balance} onClick={()=>setView("coins")}/>
              <button className="btn btn-ghost" style={{fontSize:12,minHeight:34,padding:"6px 10px"}} onClick={()=>setDarkMode(d=>!d)}>
                {darkMode?<><Sun size={15}/> Light</>:<><Moon size={15}/> Dark</>}
              </button>
              <ProfileMenu user={user} t={t} onUpdateProfile={handleUpdateProfile} onUpdateAvatar={handleUpdateAvatar} onChangePassword={handleChangePassword} onLogout={handleLogout} compact/>
            </div>
          </div>
          {view==="dashboard"&&<Dashboard user={user} attempts={attempts} onNav={setView} onStartChapterReview={handleStartChapterReview} onOpenDeepDive={handleOpenDeepDive} onOpenFlashcards={handleOpenFlashcards} coinWallet={coinWallet} t={t} starred={starred} assistantFlashcardSet={effectiveAssistantFlashcardSet}/>}
          <div style={{display:view==="mcq"?"block":"none"}} aria-hidden={view!=="mcq"}>
            <MCQPractice user={user} attempts={attempts} onSave={handleSaveAttempt} onUpgrade={()=>setView("pricing")} onOpenDeepDive={handleOpenDeepDive} onFocusModeChange={setPracticeFocusMode} isVisible={view==="mcq"} t={t} starred={starred} onToggleStar={handleToggleStar} onReportQuestion={handleReportQuestion} showQuestionCodes={isRootUser} smartReviewRequest={smartReviewRequest} onSessionComplete={handleAchievementSessionComplete} mcqBank={liveMcqBank}/>
          </div>
          <div style={{display:view==="pbq"?"block":"none"}} aria-hidden={view!=="pbq"}>
            <PBQBank user={user} attempts={attempts} onStart={q=>user.tier==="free"&&!isFreePBQPreview(q)&&!coinWallet.unlockedPbqIds.includes(q.id)?setView("coins"):setPbqQ(q)} onUpgrade={()=>setView("pricing")} onOpenWallet={()=>setView("coins")} onUnlockPbq={handleUnlockPbq} coinWallet={coinWallet} coinBusy={coinBusy} t={t} starred={starred} onToggleStar={handleToggleStar} showQuestionCodes={isRootUser} pbqBank={livePbqBank} isLoading={pbqBankLoading&&user.tier==="pro"} loadError={user.tier==="pro"&&!useLocalPbqFallback?pbqBankError:null}/>
          </div>
          {view==="exam"&&<ExamMode user={user} attempts={attempts} onSave={handleSaveAttempt} onUpgrade={()=>setView("pricing")} onOpenWallet={()=>setView("coins")} onConsumeExamPass={handleConsumeExamPass} examPasses={coinWallet.examPasses} t={t} showQuestionCodes={isRootUser} pbqBank={livePbqBank} mcqBank={liveMcqBank} onSessionComplete={handleAchievementSessionComplete} canPreviewDeepDives onOpenDeepDives={()=>setView("deep-dives")}/>}
          {view==="daily"&&<DailyChallenge t={t} user={user} onLogin={()=>setView("dashboard")} showQuestionCodes={isRootUser} onCoinReward={handleDailyCoinReward}/>}
          {view==="coins"&&<CipherCoinVault user={user} wallet={coinWallet} onUnlockPbq={handleUnlockPbq} onBuyExamPass={handleBuyExamPass} onNavigate={setView} onRefresh={refreshCipherWallet} t={t} busy={coinBusy}/>}
          {false&&view==="achievements"&&<AchievementsPage user={user} t={t} onBack={()=>setView("dashboard")}/>}
          {view==="pricing"&&<Pricing user={user} onUpgrade={handleUpgrade} onSyncBilling={handleSyncBilling} onCancelMembership={handleCancelMembership} onDeleteAccount={handleDeleteAccount} onNavigate={setView} t={t} billingLoading={billingLoading}/>}
          {view==="referrals"&&<ReferralPage user={user} t={t}/>}
          {view==="objectives"&&<ObjectivesPage t={t}/>}
          {view==="account"&&<AccountSupportPage user={user} t={t} onDeleteAccount={handleDeleteAccount} onCancelMembership={handleCancelMembership} onNavigate={setView} billingLoading={billingLoading}/>}
          {view==="privacy"&&<LegalPage type="privacy" t={t}/>}
          {view==="terms"&&<LegalPage type="terms" t={t}/>}
          {view==="deep-dives"&&<ConceptDeepDivesPage t={t} user={user} openLessonRequest={deepDiveRequest} onOpenLessonRequestHandled={()=>setDeepDiveRequest(null)} focusAcronyms={focusAcronymLibrary} onAddWeakTopicToReview={handleAddDeepDiveWeakTopicToReview} onTryRelatedPbq={handleTryRelatedDeepDivePbq} onOpenFlashcards={handleOpenFlashcards} onUpgrade={()=>setView("pricing")}/>}
          {view==="flashcards"&&<FlashcardsPage t={t} initialSetId={flashcardSetRequest} onInitialSetHandled={()=>setFlashcardSetRequest(null)} assistantSet={effectiveAssistantFlashcardSet} user={user} starred={starred} onToggleStar={handleToggleStar} onRequireSignup={()=>setView("auth")} onOpenDeepDive={handleOpenDeepDive} onUpgrade={()=>setView("pricing")}/>}
          {view==="feedback"&&<AdminFeedbackPage user={user} t={t} onEditQuestion={handleEditReportedQuestion}/>}
          {view==="question-admin"&&<AdminQuestionManagerPage user={user} t={t} onQuestionBankRefresh={refreshQuestionBankOverrides} onPbqBankRefresh={refreshRemotePBQs} pbqBank={livePbqBank} initialTarget={adminQuestionTarget}/>}
          {view==="mascot-admin"&&<AdminMascotManagerPage user={user} t={t} placements={mascotPlacements} onPublished={refreshMascotPlacements}/>}
          {!practiceFocusMode&&view!=="exam"&&view!=="mascot-admin"&&<MascotPlacement placement={mascotPlacements.find(item=>item.page_key===view)}/>}
        </main>
        <MobileNavigationMenu
          open={mobileNavOpen}
          items={navItems.filter(item=>!MOBILE_PRIMARY_NAV_IDS.has(item.id))}
          currentView={view}
          onNavigate={id=>{
            setMobileNavOpen(false);
            setView(id==="exam"&&user.tier!=="pro"&&coinWallet.examPasses<1?"coins":id);
          }}
          onClose={()=>setMobileNavOpen(false)}
        />
        {!practiceFocusMode&&!showOnboarding&&!showProWelcome&&["dashboard","mcq","pbq","daily","coins","objectives","pricing","flashcards"].includes(view)&&(
          <CipherAssistantDock user={user} attempts={attempts} currentView={view} onStartReview={handleStartChapterReview} onOpenFlashcards={handleOpenFlashcards} onUpgrade={()=>setView("pricing")}/>
        )}
        {showOnboarding&&(
          <OnboardingModal
            user={user}
            wallet={coinWallet}
            t={t}
            onClose={closeOnboarding}
            onWallet={()=>setView("coins")}
            onPbq={()=>setView("pbq")}
            onRefreshWallet={refreshCipherWallet}
          />
        )}
        {showProWelcome&&(
          <ProWelcomeModal
            user={user}
            t={t}
            onClose={closeProWelcome}
            onNavigate={setView}
          />
        )}
        {referralClaimPrompt&&(
          <ReferralClaimPrompt
            result={referralClaimPrompt}
            t={t}
            onClose={()=>setReferralClaimPrompt(null)}
            onOpenWallet={()=>{setReferralClaimPrompt(null);setView("coins");}}
          />
        )}
        {questionReport&&<QuestionReportModal report={questionReport} user={user} t={t} onClose={()=>setQuestionReport(null)}/>}
        <AchievementCelebration ids={achievementUnlocks} t={t} onClose={()=>setAchievementUnlocks([])}/>
        <CipherRewardToast reward={coinRewardToast} onClose={()=>setCoinRewardToast(null)}/>
        {(accountDeletion.stage==="request"||accountDeletion.stage==="sent")&&(
          <AccountDeletionModal
            state={accountDeletion}
            user={user}
            t={t}
            onClose={clearAccountDeletion}
            onSend={sendAccountDeletionEmail}
            onConfirm={confirmAccountDeletion}
            onSwitchAccount={switchDeletionAccount}
          />
        )}
      </div>
    </>
  );
}
